USE [master] --Le indica al motor SQL que se posicione sobre la base Master de sistema para crear la base que se necesite 
GO

CREATE DATABASE [Peliculas] -- Comando para crear la base de datos
GO

USE [Peliculas] -- Indica al motor SQL posicionarse sobre la base creada 
GO

--Creacion de las tablas 
CREATE TABLE [dbo].[Actor](
	[ActorID] [int] IDENTITY(1,1) NOT NULL, --IDENTITY indica que esa columna es autonumerica
	[Nombre] [nvarchar](100) NOT NULL,
	[Apellido] [nvarchar](100) NULL,
	[FechaNac] [date] NULL,
	[FechaFall] [date] NULL,
	[Sexo] [nvarchar](20) NULL,
	[PaisID] [int] NULL,
	CONSTRAINT [PK_Actor] PRIMARY KEY CLUSTERED ([ActorID])) -- crea la clave primaria sobre la columna indicada entre parentesis
GO

CREATE TABLE [dbo].[Clasificacion](
	[ClasificacionID] [int] IDENTITY(1,1) NOT NULL,
	[Codigo] [nvarchar](10) NOT NULL,
	[Clasificacion] [nvarchar](50) NULL,
	CONSTRAINT [PK_Clasificacion] PRIMARY KEY CLUSTERED ([ClasificacionID]))
GO

CREATE TABLE [dbo].[Director](
	[DirectorID] [int] IDENTITY(1,1) NOT NULL,
	[Nombre] [nvarchar](100) NOT NULL,
	[Apellido] [nvarchar](100) NULL,
	[FechaNac] [date] NULL,
	[FechaFall] [date] NULL,
	[Sexo] [nvarchar](20) NULL,
	[PaisID] [int] NULL,
	CONSTRAINT [PK_Director] PRIMARY KEY CLUSTERED ([DirectorID]))
GO

CREATE TABLE [dbo].[Estudio](
	[EstudioID] [int] IDENTITY(1,1) NOT NULL,
	[Estudio] [nvarchar](255) NOT NULL,
	CONSTRAINT [PK_Estudio] PRIMARY KEY CLUSTERED ([EstudioID]))
GO

CREATE TABLE [dbo].[Genero](
	[GeneroID] [int] IDENTITY(1,1) NOT NULL,
	[Genero] [nvarchar](50) NOT NULL,
	CONSTRAINT [PK_Genero] PRIMARY KEY CLUSTERED ([GeneroID]))
GO

CREATE TABLE [dbo].[Lenguaje](
	[LenguajeID] [int] IDENTITY(1,1) NOT NULL,
	[Lenguaje] [nvarchar](255) NOT NULL,
	CONSTRAINT [PK__Lenguaje] PRIMARY KEY CLUSTERED ([LenguajeID]))
GO

CREATE TABLE [dbo].[Pais](
	[PaisID] [int] IDENTITY(1,1) NOT NULL,
	[Pais] [nvarchar](255) NOT NULL,
	CONSTRAINT [PK_Pais] PRIMARY KEY CLUSTERED ([PaisID]))
GO

CREATE TABLE [dbo].[Pelicula](
	[PeliculaID] [int] IDENTITY(1,1) NOT NULL,
	[TituloOriginal] [nvarchar](100) NOT NULL,
	[TituloLatam] [nvarchar](100) NULL,
	[TagLine] [nvarchar](255) NULL,
	[FechaEstreno] [date] NULL,
	[Sinopsis] [nvarchar](max) NULL,
	[SitioWeb] [nvarchar](100) NULL,
	[DirectorID] [int] NULL,
	[EstudioID] [int] NULL,
	[PaisID] [int] NULL,
	[LenguajeID] [int] NULL,
	[GeneroID] [int] NULL,
	[Duracion] [smallint] NULL,
	[ClasificacionID] [int] NULL,
	[Presupuesto] [numeric](18, 2) NULL,
	[Recaudacion] [numeric](18, 2) NULL,
	[OscarNomin] [tinyint] NULL,
	[OscarGanados] [tinyint] NULL,
	CONSTRAINT [PK_Pelicula] PRIMARY KEY CLUSTERED ([PeliculaID]))
GO

CREATE TABLE [dbo].[Personaje](
	[PersonajeID] [int] IDENTITY(1,1) NOT NULL,
	[Personaje] [nvarchar](255) NULL,
	[PeliculaID] [int] NULL,
	[ActorID] [int] NULL,
	CONSTRAINT [PK_Personaje] PRIMARY KEY CLUSTERED ([PersonajeID]))
GO

