INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1, N'Jurassic Park', N'Parque Jurásico', N'Una aventura 65 millones de años en la creación.', CAST(N'1993-06-11' AS Date), N'Un rico empresario crea en secreto un parque temático con dinosaurios vivos extraídos de ADN prehistórico. Antes del día de la inauguración, invita a un equipo de expertos y a sus dos ansiosos nietos a experimentar el parque y ayudar a calmar a los ansiosos inversores. Sin embargo, el parque es todo menos divertido cuando los sistemas de seguridad se desconectan y los dinosaurios escapan.', N'http://www.jurassicpark.com/', 4, 41, 241, 1, 8, 126, 2, CAST(63000000.00 AS Numeric(18, 2)), CAST(1029939903.00 AS Numeric(18, 2)), 3, 3)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (2, N'Spider-Man', N'El Hombre Araña', N'Con un gran poder viene una gran responsabilidad.', CAST(N'2002-05-03' AS Date), N'Después de ser mordido por una araña genéticamente alterada, el nerd estudiante de secundaria Peter Parker está dotado de poderes asombrosos.', N'http://www.sonypictures.com/movies/spider-man/', 11, 53, 241, 1, 4, 121, 4, CAST(140000000.00 AS Numeric(18, 2)), CAST(821708551.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (3, N'King Kong', N'King Kong', N'La octava maravilla del mundo.', CAST(N'2005-12-14' AS Date), N'En Nueva York de 1933, un productor de cine demasiado ambicioso obliga a su elenco y contrata a la tripulación del barco a viajar a la misteriosa Isla Calavera, donde se encuentran con Kong, un simio gigante que inmediatamente se enamora de la protagonista.', N'', 12, 42, 167, 1, 8, 187, 4, CAST(207000000.00 AS Numeric(18, 2)), CAST(550500000.00 AS Numeric(18, 2)), 4, 3)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (5, N'Superman Returns', N'Superman Regresa', NULL, CAST(N'2006-07-14' AS Date), N'Superman regresa para descubrir que su ausencia de cinco años le ha permitido a Lex Luthor caminar libre y que aquellos que estaban más cerca de él también se sintieron abandonados y siguieron adelante. Luthor planea su venganza definitiva que podría provocar la muerte de millones de personas y cambiar la faz del planeta para siempre, además de deshacerse del Hombre de Acero.', N'http://www.superman.com', 14, 43, 241, 1, 4, 154, 4, CAST(204000000.00 AS Numeric(18, 2)), CAST(391081192.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (6, N'Titanic', N'Titanic', N'Nada en la tierra podría interponerse entre ellos.', CAST(N'1998-01-23' AS Date), N'84 años después, una mujer de 101 años llamada Rose DeWitt Bukater le cuenta a su nieta Lizzy Calvert, Brock Lovett, Lewis Bodine, Bobby Buell y Anatoly Mikailavich en el Keldysh la historia de su vida ambientada el 10 de abril de 1912, en un barco. llamado Titanic cuando la joven Rose aborda el barco que parte con los pasajeros de clase alta y su madre, Ruth DeWitt Bukater, y su prometido, Caledon Hockley. Mientras tanto, un vagabundo y artista llamado Jack Dawson y su mejor amigo Fabrizio De Rossi ganan billetes de tercera clase para subir al barco en un juego. Y explica toda la historia desde la salida hasta la muerte del Titanic en su primer y último viaje el 15 de abril de 1912 a las 2:20 de la madrugada.', N'http://www.titanicmovie.com', 15, 4, 241, 1, 6, 194, 3, CAST(200000000.00 AS Numeric(18, 2)), CAST(2186772302.00 AS Numeric(18, 2)), 14, 11)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (7, N'Evan Almighty', N'Todopoderoso 2', N'Una comedia de proporciones bíblicas', CAST(N'2007-06-22' AS Date), N'Dios contacta al congresista Evan Baxter y le dice que construya un arca en preparación para una gran inundación.', N'http://www.evanalmighty.com/', 16, 44, 241, 1, 7, 96, 2, CAST(175000000.00 AS Numeric(18, 2)), CAST(173418781.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (8, N'Waterworld', N'Mundo Acuático', N'Más allá del horizonte se encuentra el secreto para un nuevo comienzo.', CAST(N'1995-07-28' AS Date), N'En un mundo futurista donde los casquetes polares se han derretido y han convertido a la Tierra en un planeta líquido, una hermosa camarera rescata a un marino mutante de una prisión en una isla flotante. Se escapan, junto con su joven pupilo, Enola, y zarpan a bordo de su barco. Pero el trío pronto se convierte en el objetivo de un pirata amenazador que codicia el mapa de "Dryland", que está tatuado en la espalda de Enola.', N'', 17, 45, 241, 1, 8, 135, 3, CAST(175000000.00 AS Numeric(18, 2)), CAST(264218220.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (9, N'Pearl Harbor', N'Pearl Harbor', N'Se necesita un momento para cambiar la historia. Se necesita amor para cambiar vidas.', CAST(N'2001-05-21' AS Date), N'La amistad de toda la vida entre Rafe McCawley y Danny Walker se pone a prueba cuando los dos pilotos de combate se ven envueltos en un triángulo amoroso con la bella enfermera naval Evelyn Johnson. Pero la rivalidad entre amigos convertidos en enemigos queda inmediatamente en suspenso cuando se encuentran en el centro del devastador ataque japonés a Pearl Harbor el 7 de diciembre de 1941.', N'', 18, 7, 241, 1, 5, 183, 3, CAST(140000000.00 AS Numeric(18, 2)), CAST(449220945.00 AS Numeric(18, 2)), 4, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (10, N'Transformers', N'Transformers', N'Su guerra. Nuestro mundo.', CAST(N'2007-07-03' AS Date), N'El joven adolescente Sam Witwicky se involucra en la antigua lucha entre dos facciones extraterrestres de robots transformadores: los heroicos Autobots y los malvados Decepticons. Sam tiene la clave de un poder inimaginable y los Decepticons no se detendrán ante nada para recuperarlo.', N'http://www.transformersmovie.com/', 18, 46, 241, 1, 3, 144, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(709709780.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (11, N'Harry Potter and the Order of the Phoenix', N'Harry Potter y la Orden del Fénix', N'El mal debe ser confrontado.', CAST(N'2007-07-11' AS Date), N'Al regresar para su quinto año de estudios en Hogwarts, Harry se sorprende al descubrir que sus advertencias sobre el regreso de Lord Voldemort han sido ignoradas. Sin otra opción, Harry toma el asunto en sus propias manos y entrena a un pequeño grupo de estudiantes (llamado ''Ejército de Dumbledore'') para defenderse de las artes oscuras.', N'http://www.harrypotterorderofthephoenix.com/', 19, 47, 240, 1, 12, 138, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(939885929.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (12, N'Beowulf', N'Beowulf: La Leyenda', N'El mal genera dolor.', CAST(N'2007-11-16' AS Date), N'Beowulf, guerrero escandinavo del siglo VI, se embarca en una misión para matar al ogro humano Grendel, un descendiente de Caín.', N'http://www.beowulfmovie.com/', 20, 48, 241, 1, 12, 115, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(196393745.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (13, N'Bee Movie', N'Bee Movie: La Historia de una Abeja', N'Nacido a Bee Wild.', CAST(N'2007-11-02' AS Date), N'Barry B. Benson, una abeja que acaba de graduarse de la universidad, está desilusionada por su única elección profesional: hacer miel. En un viaje especial fuera de la colmena, Vanessa, una florista de la ciudad de Nueva York, salva la vida de Barry. A medida que su relación florece, descubre que los humanos realmente comen miel y, posteriormente, decide demandarnos.', N'http://www.beemovie.com/', 21, 8, 241, 1, 11, 91, 1, CAST(150000000.00 AS Numeric(18, 2)), CAST(287594577.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (14, N'Pirates of the Caribbean: At World''s End', N'Piratas del Caribe: En el Fin del Mundo', N'Al final del mundo, comienza la aventura.', CAST(N'2007-05-25' AS Date), N'El Capitán Barbossa, que durante mucho tiempo se creía muerto, ha vuelto a la vida y se dirige al borde de la Tierra con Will Turner y Elizabeth Swann. Pero nada es lo que parece.', N'http://disney.go.com/disneypictures/pirates/', 22, 3, 241, 1, 8, 168, 4, CAST(300000000.00 AS Numeric(18, 2)), CAST(963420425.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (15, N'I Am Legend', N'Soy Leyenda', N'El último hombre en la tierra no está solo', CAST(N'2007-12-14' AS Date), N'Robert Neville es un científico que no pudo detener la propagación de un terrible virus que era incurable y creado por el hombre. Inmune, Neville es ahora el último superviviente humano en lo que queda de la ciudad de Nueva York y quizás del mundo. Durante tres años, Neville ha enviado fielmente mensajes de radio diarios, desesperado por encontrar otros supervivientes que puedan estar ahí fuera. Pero él no está solo.', N'http://iamlegend.warnerbros.com/', 23, 49, 241, 1, 10, 100, 5, CAST(150000000.00 AS Numeric(18, 2)), CAST(585349010.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (16, N'Ratatouille', N'Ratatouille', N'Se está muriendo por convertirse en chef.', CAST(N'2007-06-22' AS Date), N'Una rata llamada Remy sueña con convertirse en un gran chef francés a pesar de los deseos de su familia y del evidente problema de ser una rata en una profesión decididamente fóbica a los roedores. Cuando el destino coloca a Remy en las alcantarillas de París, se encuentra en una ubicación ideal debajo de un restaurante que su héroe culinario, Auguste Gusteau, hizo famoso. A pesar de los aparentes peligros de ser un visitante improbable (y ciertamente no deseado) en la cocina de un excelente restaurante francés, la pasión de Remy por la cocina pronto pone en marcha una divertida y emocionante carrera de ratas que pone patas arriba el mundo culinario de París.', N'http://disney.go.com/disneypictures/ratatouille/', 24, 3, 241, 1, 11, 111, 1, CAST(150000000.00 AS Numeric(18, 2)), CAST(623722818.00 AS Numeric(18, 2)), 5, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (17, N'Troy', N'Troya', N'Por pasión. Por honor. Para el destino. Por la victoria. Por amor.', CAST(N'2004-05-14' AS Date), N'En el año 1250 a.C. A finales de la Edad del Bronce, dos naciones emergentes comienzan a chocar. Paris, el príncipe troyano, convence a Helena, reina de Esparta, de que deje a su marido Menelao y navegue con él de regreso a Troya. Después de que Menelao descubre que los troyanos se llevaron a su esposa, le pide a su hermano Agamenón que lo ayude a recuperarla. Agamenón ve esto como una oportunidad de poder. Así que partieron con 1.000 barcos que transportaban a 50.000 griegos hacia Troya. Con la ayuda de Aquiles, los griegos pueden luchar contra los troyanos, nunca antes derrotados.', N'', 25, 50, 241, 1, 8, 162, 5, CAST(175000000.00 AS Numeric(18, 2)), CAST(497409852.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (18, N'Harry Potter and the Goblet of Fire', N'Harry Potter y el Cáliz de Fuego', N'Los tiempos oscuros y difíciles están por delante.', CAST(N'2005-11-06' AS Date), N'Harry comienza su cuarto año en Hogwarts, compite en el traicionero Torneo de los Tres Magos y se enfrenta al malvado Lord Voldemort. Ron y Hermione ayudan a Harry a manejar la presión, pero Voldemort acecha, esperando su oportunidad de destruir a Harry y todo lo que representa.', N'http://harrypotter.warnerbros.com/', 26, 47, 240, 1, 12, 156, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(896911078.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (19, N'Batman Begins', N'Batman Inicia', N'El mal teme al caballero.', CAST(N'2005-06-15' AS Date), N'Impulsado por la tragedia, el multimillonario Bruce Wayne dedica su vida a descubrir y derrotar la corrupción que asola su hogar, Gotham City.  Incapaz de trabajar dentro del sistema, crea una nueva identidad, un símbolo de miedo para el inframundo criminal: The Batman.', N'http://www2.warnerbros.com/batmanbegins/index.html', 27, 43, 241, 1, 4, 141, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(374218673.00 AS Numeric(18, 2)), 1, 0)
GO
