INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (23, N'Lethal Weapon 4', N'Arma Mortal 4', N'Las caras que amas. La acción que esperas.', CAST(N'1998-07-10' AS Date), N'En la última entrega de la franquicia de acción combustible, los detectives inconformistas Martin Riggs y Roger Murtaugh se enfrentan al mafioso asiático Wah Sing Ku, que está metido hasta el cuello en el comercio de esclavos y la falsificación de moneda. Con la ayuda del detective Leo Getz y el sabelotodo policía novato Lee Butters, Riggs y Murtaugh pretenden acabar con Ku y su banda.', N'', 30, 52, 241, 1, 4, 127, 5, CAST(100000000.00 AS Numeric(18, 2)), CAST(285444603.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (24, N'Armageddon', N'Armageddon', N'El día más oscuro de la Tierra será la mejor hora del hombre', CAST(N'1998-07-01' AS Date), N'Cuando un asteroide amenaza con chocar con la Tierra, el jefe de la NASA, Dan Truman, determina que la única forma de detenerlo es perforar su superficie y detonar una bomba nuclear. Esto lo lleva al renombrado perforador Harry Stamper, quien acepta dirigir la peligrosa misión espacial siempre que pueda traer consigo su propio equipo de expertos. Entre ellos se encuentra el engreído A.J. quien Harry cree que no es lo suficientemente bueno para su hija, hasta que la misión demuestra lo contrario.', N'', 18, 7, 241, 1, 3, 151, 3, CAST(140000000.00 AS Numeric(18, 2)), CAST(553709788.00 AS Numeric(18, 2)), 4, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (25, N'Men in Black II', N'Hombres de Negro II', N'Mismo planeta. Nueva escoria.', CAST(N'2002-07-03' AS Date), N'Kay y Jay se reúnen para proporcionar nuestra mejor, última y única línea de defensa contra una siniestra seductora que plantea el desafío más difícil hasta el momento a la impecable misión del MIB: proteger la Tierra de la escoria del universo. Han pasado cuatro años desde que los agentes buscadores de extraterrestres evitaron un desastre intergaláctico de proporciones épicas. Ahora es una carrera contrarreloj, ya que Jay debe convencer a Kay, quien no solo no recuerda en absoluto el tiempo que pasó con el MIB, sino que también es la única persona viva que queda con la experiencia necesaria para salvar la galaxia, para que se reúna con el MIB antes. la tierra se somete a la destrucción final.', N'http://www.sonypictures.com/homevideo/meninblackii/', 31, 41, 241, 1, 3, 89, 2, CAST(140000000.00 AS Numeric(18, 2)), CAST(441818803.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (26, N'Spider-Man 3', N'El Hombre Araña 3', N'La batalla dentro.', CAST(N'2007-05-04' AS Date), N'El aparentemente invencible Spider-Man se enfrenta a una generación completamente nueva de villanos, incluido Sandman, que cambia de forma. Mientras que los superpoderes de Spider-Man son alterados por un organismo alienígena, su alter ego, Peter Parker, lidia con su enemigo Eddie Brock y también queda atrapado en un triángulo amoroso.', N'http://www.sonypictures.com/movies/spider-man3/', 11, 53, 241, 1, 4, 139, 4, CAST(258000000.00 AS Numeric(18, 2)), CAST(890871626.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (27, N'Spider-Man 2', N'El Hombre Araña 2', N'Hay un héroe en todos nosotros.', CAST(N'2004-06-30' AS Date), N'Peter Parker atraviesa una importante crisis de identidad. Agotado por ser Spider-Man, decide dejar de lado su alter ego de superhéroe, lo que deja a la ciudad sufriendo a raíz de la matanza dejada por el malvado Doc Ock. Mientras tanto, Parker todavía no puede expresar sus sentimientos por Mary Jane Watson, una chica a la que ama desde la infancia.', N'http://www.sonypictures.com/movies/spider-man2/', 11, 53, 241, 1, 4, 127, 4, CAST(200000000.00 AS Numeric(18, 2)), CAST(783766341.00 AS Numeric(18, 2)), 3, 1)
GO
