INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (31, N'The World Is Not Enough', N'El Mundo No Basta', N'A medida que comienza la cuenta regresiva para el nuevo milenio, todavía hay un número con el que siempre puede contar.', CAST(N'1999-11-26' AS Date), N'Avaricia, venganza, dominio mundial y terrorismo de alta tecnología: todo está en el día de trabajo de Bond, quien tiene la misión de proteger a la hermosa heredera del petróleo de un notorio terrorista. En una carrera contra el tiempo que culmina en un dramático enfrentamiento submarino, Bond trabaja para desactivar la lucha de poder internacional que tiene el suministro mundial de petróleo en juego.', N'http://www.mgm.com/view/movie/231/The-World-Is-Not-Enough/', 35, 51, 240, 1, 9, 128, 3, CAST(135000000.00 AS Numeric(18, 2)), CAST(361832400.00 AS Numeric(18, 2)), 0, 0)
