INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (32, N'Master and Commander: The Far Side of the World', N'Capitán de Mar y Guerra: La Costa Más Lejana del Mundo', N'El coraje de hacer lo imposible se encuentra en los corazones de los hombres.', CAST(N'2003-11-14' AS Date), N'Después de que un encuentro abrupto y violento con un buque de guerra francés inflige graves daños a su barco, un capitán de la Royal Navy británica comienza una persecución a través de dos océanos para capturar o destruir al enemigo, aunque debe sopesar su compromiso con el deber y su feroz búsqueda de la gloria. contra la seguridad de su devota tripulación, incluido el atento cirujano del barco, su mejor amigo.', N'http://www.masterandcommanderthefarsideoftheworld.com/', 36, 4, 241, 1, 8, 138, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(212011111.00 AS Numeric(18, 2)), 10, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (33, N'War of the Worlds', N'La Guerra de los Mundos', N'Ya están aquí.', CAST(N'2005-06-29' AS Date), N'Ray Ferrier es un trabajador portuario divorciado y un padre menos que perfecto. Poco después de que su ex esposa y su nuevo esposo dejaran a su hijo adolescente y a su hija pequeña para una rara visita de fin de semana, una extraña y poderosa tormenta eléctrica aterriza.', N'', 4, 41, 241, 1, 3, 116, 4, CAST(132000000.00 AS Numeric(18, 2)), CAST(591745540.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (34, N'The Bourne Ultimatum', N'Bourne: El Ultimátum', N'Recuerda todo. Perdonar nada.', CAST(N'2007-08-17' AS Date), N'Bourne sale de su escondite una vez más gracias al reportero Simon Ross, que intenta desvelar la Operación Blackbriar, una mejora del Proyecto Treadstone, en una serie de columnas periodísticas. La información del periodista despierta una nueva serie de recuerdos, y Bourne finalmente debe descubrir su oscuro pasado mientras esquiva los mejores esfuerzos de La Compañía para erradicarlo.', N'http://www.universalstudiosentertainment.com/the-bourne-ultimatum/', 37, 56, 241, 1, 9, 115, 4, CAST(110000000.00 AS Numeric(18, 2)), CAST(442824138.00 AS Numeric(18, 2)), 3, 3)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (35, N'Harry Potter and the Prisoner of Azkaban', N'Harry Potter y el Prisionero de Azkaban', N'La feria de las tinieblas.', CAST(N'2004-05-31' AS Date), N'Harry, Ron y Hermione regresan a Hogwarts para pasar otro año lleno de magia. Harry se encuentra cara a cara con el peligro una vez más, esta vez en la forma del convicto fugitivo, Sirius Black, y recurre al comprensivo profesor Lupin en busca de ayuda.', N'', 38, 47, 240, 1, 12, 141, 2, CAST(130000000.00 AS Numeric(18, 2)), CAST(796688549.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (36, N'The Matrix Reloaded', N'Matrix Recargado', N'Libera tu mente.', CAST(N'2003-05-15' AS Date), N'Seis meses después de los eventos descritos en Matrix, Neo ha demostrado ser un buen augurio para los humanos libres, ya que cada vez más humanos son liberados de Matrix y llevados a Sión, el único bastión de la Resistencia.  El propio Neo ha descubierto sus superpoderes, incluida la supervelocidad, la capacidad de ver los códigos de las cosas dentro de la matriz y un cierto grado de precognición. Pero una mala noticia golpea la resistencia humana: 250.000 máquinas centinelas están excavando en Sion y llegarían allí en 72 horas. Mientras Zion se prepara para la guerra definitiva, el Oráculo aconseja a Neo, Morfeo y Trinity que encuentren al Hacedor de llaves que los ayudaría a llegar a la Fuente.  Mientras tanto, los sueños recurrentes de Neo que representan la muerte de Trinity lo tienen preocupado y, como si no fuera suficiente, el Agente Smith de alguna manera escapó de la eliminación, se ha vuelto más poderoso que antes y ha fijado a Neo como su próximo objetivo.', N'', 39, 49, 241, 1, 3, 138, 5, CAST(150000000.00 AS Numeric(18, 2)), CAST(742128461.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (37, N'The Da Vinci Code', N'El Código Da Vinci', N'Buscar la verdad.', CAST(N'2006-05-19' AS Date), N'Cuando el curador del Louvre es encontrado asesinado en los sagrados pasillos del famoso museo, el profesor de Harvard Robert Langdon y la criptógrafa Sophie Neve deben desenredar una red mortal de engaños que involucra las obras de Leonardo da Vinci.', N'http://www.sonypictures.com/homevideo/thedavincicode/index.html', 40, 20, 241, 1, 18, 146, 4, CAST(125000000.00 AS Numeric(18, 2)), CAST(758239851.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (38, N'Harry Potter and the Philosopher''s Stone', N'Harry Potter y la Piedra Filosofal', N'Deja que comience la magia.', CAST(N'2001-11-16' AS Date), N'Harry Potter ha vivido debajo de las escaleras en la casa de sus tíos toda su vida. Pero en su cumpleaños número 11, descubre que es un mago poderoso y que le espera un lugar en el Colegio Hogwarts de Magia y Hechicería. Mientras aprende a aprovechar sus nuevos poderes con la ayuda del amable director de la escuela, Harry descubre la verdad sobre la muerte de sus padres y sobre el villano culpable.', N'http://harrypotter.warnerbros.com/harrypotterandthedeathlyhallows/mainsite/index.html', 41, 47, 240, 1, 12, 152, 2, CAST(125000000.00 AS Numeric(18, 2)), CAST(974800000.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (39, N'The Day After Tomorrow', N'El Día Después de Mañana', N'¿Dónde estarás?', CAST(N'2004-05-26' AS Date), N'Después de años de aumento del efecto invernadero, se causan estragos en todo el mundo en forma de huracanes catastróficos, tornados, maremotos, inundaciones y el comienzo de una nueva Edad de Hielo. El paleoclimatólogo Jack Hall intenta advertir al mundo y al mismo tiempo guiar a su hijo a un lugar seguro, atrapado en Nueva York después de que la ciudad se vea abrumada por el inicio de una nueva gran helada.', N'http://www.thedayaftertomorrow.com/', 42, 57, 241, 1, 9, 124, 4, CAST(125000000.00 AS Numeric(18, 2)), CAST(542772402.00 AS Numeric(18, 2)), 0, 0)
GO
