INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (41, N'The Last Samurai', N'El Último Samurai', N'Ante un enemigo, en el corazón de un hombre, se encuentra el alma de un guerrero.', CAST(N'2003-12-05' AS Date), N'Nathan Algren es un estadounidense contratado para instruir al ejército japonés en los métodos de la guerra moderna, lo que le lleva a aprender a respetar a los samuráis y los honorables principios que los gobiernan. Presionado para destruir el modo de vida de los samuráis en nombre de la modernización y el comercio abierto, Algren decide convertirse él mismo en un guerrero supremo y luchar por su derecho a existir.', N'', 43, 58, 241, 1, 8, 154, 5, CAST(140000000.00 AS Numeric(18, 2)), CAST(456758981.00 AS Numeric(18, 2)), 4, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (42, N'The Perfect Storm', N'La Tormenta Perfecta', N'Se acerca la tormenta.', CAST(N'2000-06-30' AS Date), N'En octubre de 1991, una confluencia de condiciones climáticas se combinó para formar una tormenta mortal en el Atlántico Norte. Atrapado en la tormenta quedó el barco de pesca con espada Andrea Gail. Magníficos presagios y anticipación llenan este drama de la vida real, mientras que los detalles minuciosos de los barcos pesqueros, sus aparejos y el clima se yuxtaponen con la aventura en el mar.', N'', 25, 6, 241, 1, 8, 130, 3, CAST(120000000.00 AS Numeric(18, 2)), CAST(328718434.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (43, N'Mission: Impossible III', N'Misión: Imposible III', N'La misión comienza 05:05:06.', CAST(N'2006-05-04' AS Date), N'Ethan Hunt, retirado del servicio activo para entrenar a nuevos agentes del FMI, es llamado nuevamente a la acción para enfrentarse al sádico traficante de armas Owen Davian. Hunt debe intentar proteger a su novia mientras trabaja con su nuevo equipo para completar la misión.', N'http://www.missionimpossible.com/', 44, 59, 241, 1, 9, 125, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(397850012.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (44, N'Mission: Impossible II', N'Misión: Imposible II', N'Espere lo imposible de nuevo.', CAST(N'2000-05-24' AS Date), N'Con el genio informático Luther Stickell a su lado y una hermosa ladrona en mente, el agente Ethan Hunt recorre Australia y España para evitar que un ex agente del FMI desatara un arma biológica diseñada genéticamente llamada Quimera. Esta misión, en caso de que Hunt decida aceptarla, lo sumerge en el centro de una crisis internacional de magnitud aterradora.', N'http://www.missionimpossible.com/', 45, 59, 241, 1, 9, 123, 5, CAST(125000000.00 AS Numeric(18, 2)), CAST(546388105.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (45, N'Windtalkers', N'Códigos de Guerra', N'El honor era su código.', CAST(N'2002-08-30' AS Date), N'Joe Enders es un entusiasta marine asignado para proteger a un \"windhablador\", uno de varios indios navajos que fueron utilizados para transmitir mensajes durante la Segunda Guerra Mundial porque su lenguaje hablado era indescifrable para los descifradores de códigos japoneses.', N'', 45, 60, 241, 1, 5, 134, 5, CAST(115000000.00 AS Numeric(18, 2)), CAST(77628265.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (46, N'Star Wars: Episode II - Attack of the Clones', N'Star Wars: Episodio II - El Ataque de los Clones', N'Un Jedi no sabrá enojo. Ni odio. Ni amor.', CAST(N'2002-05-16' AS Date), N'Diez años después de la invasión de Naboo, la galaxia está al borde de una guerra civil. Bajo el liderazgo de un Jedi renegado llamado Conde Dooku, miles de sistemas solares amenazan con separarse de la República Galáctica. Cuando se intenta asesinar a la senadora Padmé Amidala, ex reina de Naboo, se asigna al aprendiz de Jedi Anakin Skywalker, de veinte años, para protegerla. En el transcurso de su misión, Anakin descubre su amor por Padmé así como su lado más oscuro. Pronto, Anakin, Padmé y Obi-Wan Kenobi se ven arrastrados al corazón del movimiento separatista y al comienzo de las Guerras Clon.', N'http://www.starwars.com/films/star-wars-episode-ii-attack-of-the-clones', 7, 13, 241, 1, 3, 142, 2, CAST(115000000.00 AS Numeric(18, 2)), CAST(649400000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (47, N'Monsters, Inc.', N'Monsters, Inc.', N'Nos asustamos porque nos importa.', CAST(N'2002-02-08' AS Date), N'James Sullivan y Mike Wazowski son unos monstruos, se ganan la vida asustando a los niños y son los mejores en el negocio... aunque les tienen más miedo a los niños que a ellos. Cuando un niño entra accidentalmente en su mundo, James y Mike descubren de repente que no hay que temer a los niños y descubren una conspiración que podría amenazar a todos los niños del mundo.', N'http://movies.disney.com/monsters-inc', 46, 10, 241, 1, 11, 92, 1, CAST(115000000.00 AS Numeric(18, 2)), CAST(562800000.00 AS Numeric(18, 2)), 4, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (48, N'Star Wars: Episode I - The Phantom Menace', N'Star Wars: Episodio I - La Amenaza Fantasma', N'Cada generación tiene una leyenda. Cada viaje tiene un primer paso. Cada saga tiene un comienzo.', CAST(N'1999-05-19' AS Date), N'Anakin Skywalker, un joven esclavo fuerte en la Fuerza, es descubierto en Tatooine. Mientras tanto, los malvados Sith han regresado, implementando su plan de venganza contra los Jedi.', N'http://www.starwars.com/films/star-wars-episode-i-the-phantom-menace', 7, 13, 241, 1, 3, 133, 1, CAST(115000000.00 AS Numeric(18, 2)), CAST(1027000000.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (49, N'Star Wars: Episode III - Revenge of the Sith', N'Star Wars: Episodio III - La Venganza de los Sith', N'La saga está completa.', CAST(N'2005-05-19' AS Date), N'Años después del inicio de las Guerras Clon, los nobles Caballeros Jedi lideran un enorme ejército clon en una batalla galáctica contra los separatistas. Cuando los siniestros Sith desvelan un complot milenario para gobernar la galaxia, la República se desmorona y de sus cenizas surge el malvado Imperio Galáctico. El héroe Jedi Anakin Skywalker es seducido por el lado oscuro de la Fuerza para convertirse en el nuevo aprendiz del Emperador: Darth Vader. Los Jedi son diezmados, mientras Obi-Wan Kenobi y el Maestro Jedi Yoda se ven obligados a esconderse. La única esperanza para la galaxia son los propios hijos de Anakin: los niños gemelos nacidos en secreto que crecerán hasta convertirse en héroes.', N'http://www.starwars.com/films/star-wars-episode-iii-revenge-of-the-sith', 7, 13, 241, 1, 3, 140, 4, CAST(113000000.00 AS Numeric(18, 2)), CAST(848800000.00 AS Numeric(18, 2)), 1, 0)
GO
