INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (56, N'Mr. & Mrs. Smith', N'Sr. y Sra. Smith', N'Inteligente y sexy.', CAST(N'2005-06-10' AS Date), N'Después de cinco (o seis) años de felicidad conyugal, los habitantes comunes y corrientes de los suburbios, John y Jane Smith, están atrapados en una enorme rutina. Sin que el otro lo sepa, ambos son asesinos fríamente letales y bien pagados que trabajan para organizaciones rivales. Cuando descubren que son el próximo objetivo del otro, sus vidas secretas chocan en una mezcla picante y explosiva de comedia perversa, pasión reprimida, acción incesante y armamento de alta tecnología.', N'', 52, 65, 241, 1, 4, 120, 5, CAST(110000000.00 AS Numeric(18, 2)), CAST(478336279.00 AS Numeric(18, 2)), 0, 0)
