INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (57, N'The Aviator', N'El Aviador', N'Para algunos hombres, el cielo era el límite. Para él, fue solo el comienzo.', CAST(N'2004-12-25' AS Date), N'Una película biográfica que describe la vida del cineasta y pionero de la aviación Howard Hughes de 1927 a 1947, tiempo durante el cual se convirtió en un exitoso productor de cine y un magnate de la aviación, al tiempo que se volvía más inestable debido a un grave trastorno obsesivo-compulsivo.', N'', 9, 66, 241, 1, 19, 170, 4, CAST(110000000.00 AS Numeric(18, 2)), CAST(214608827.00 AS Numeric(18, 2)), 11, 5)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (58, N'Ali', N'Ali', N'Flota como una mariposa y pican como una abeja.', CAST(N'2001-12-25' AS Date), N'En 1964, un nuevo y atrevido boxeador profesional, recién salido de su medalla de oro olímpica, irrumpe en escena; Casio Arcilla. Audaz y franco, crea una imagen completamente nueva para los afroamericanos en el deporte con su orgullosa confianza pública en sí mismo y su creencia sin complejos de que es el mejor boxeador de todos los tiempos. Sin embargo, en la cima de su carrera, tanto la vida personal como la profesional de Ali enfrentan la prueba definitiva.', N'', 34, 67, 241, 1, 19, 157, 5, CAST(107000000.00 AS Numeric(18, 2)), CAST(87713825.00 AS Numeric(18, 2)), 0, 0)
GO
