GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (61, N'Casino Royale', N'Casino Royale', N'Todos tienen un pasado. Cada leyenda tiene un comienzo.', CAST(N'2006-11-14' AS Date), N'Le Chiffre, banquero de los terroristas del mundo, tiene previsto participar en una partida de póquer de alto riesgo en Montenegro, donde pretende utilizar sus ganancias para establecer su control financiero sobre el mercado terrorista. M envía a Bond, en su primera misión como Agente 00, para asistir a este juego y evitar que Le Chiffre gane. Con la ayuda de Vesper Lynd y Felix Leiter, Bond entra en el juego de póquer más importante de su ya peligrosa carrera.', N'http://www.mgm.com/#/our-titles/233/Casino-Royale-(2006)', 54, 51, 240, 1, 9, 144, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(599000000.00 AS Numeric(18, 2)), 0, 0)
GO
