INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (66, N'American Gangster', N'Gángster Americano', N'Hay dos lados para el sueño americano', CAST(N'2007-11-16' AS Date), N'Tras la muerte de su empleador y mentor, Bumpy Johnson, Frank Lucas se establece como el importador número uno de heroína en el distrito Harlem de Manhattan. Lo hace comprando heroína directamente de la fuente en el sudeste asiático y se le ocurre una forma única de importar las drogas a los Estados Unidos. Basado en una historia real.', N'http://www.americangangster.net/', 51, 20, 241, 1, 19, 158, 6, CAST(100000000.00 AS Numeric(18, 2)), CAST(266465037.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (67, N'Blood Diamond', N'Diamante de Sangre', N'Te costará todo.', CAST(N'2006-12-08' AS Date), N'Un ex mercenario convertido en contrabandista. Un pescador mende. En medio de la explosiva guerra civil que azota a Sierra Leona en 1999, estos hombres se unen para dos misiones desesperadas: recuperar un raro diamante rosa de inmenso valor y rescatar al hijo de un pescador reclutado como niño soldado por las brutales fuerzas rebeldes que están causando tortura y derramamiento de sangre en todo el país.', N'', 43, 69, 241, 1, 8, 143, 5, CAST(100000000.00 AS Numeric(18, 2)), CAST(171407179.00 AS Numeric(18, 2)), 5, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (68, N'Gladiator', N'Gladiador', N'Un héroe se levantará.', CAST(N'2000-05-05' AS Date), N'En el año 180, la muerte del emperador Marco Aurelio sume al Imperio Romano en el caos. Maximus es uno de los generales más capaces y confiables del ejército romano y un asesor clave del emperador. Mientras el tortuoso hijo de Marco, Cómodo, asciende al trono, Máximo está listo para ser ejecutado. Se escapa, pero es capturado por traficantes de esclavos. Renombrado español y obligado a convertirse en gladiador, Maximus debe luchar a muerte con otros hombres para divertir al público que paga. Sus habilidades de batalla le resultan muy útiles y se convierte en uno de los hombres más famosos y admirados que lucharon en el Coliseo. Decidido a vengarse del hombre que le quitó la libertad y arrasó con su familia, Maximus cree que puede usar su fama y habilidad en el ring para vengar la pérdida de su familia y su antigua gloria. Cuando el gladiador comienza a desafiar su gobierno, Cómodo decide poner a prueba su propio temple de lucha enfrentándose a Maximus en una batalla a muerte.', N'', 51, 64, 241, 1, 8, 155, 5, CAST(103000000.00 AS Numeric(18, 2)), CAST(457600000.00 AS Numeric(18, 2)), 12, 5)
GO
