GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (70, N'Gangs of New York', N'Pandillas de Nueva York', N'América nació en las calles.', CAST(N'2002-12-20' AS Date), N'Es 1863. Estados Unidos nació en las calles. Amsterdam Vallon regresa a los Cinco Puntos de América para buscar venganza contra el psicótico capo del mafioso, Bill el Carnicero, que asesinó a su padre años antes. Con un carterista ansioso a su lado y un ejército completamente nuevo, Vallon se abre camino para vengarse del Carnicero y restaurar la paz en la zona.', N'http://video.movies.go.com/gangsofnewyork/', 9, 7, 241, 1, 2, 160, 6, CAST(97000000.00 AS Numeric(18, 2)), CAST(193772504.00 AS Numeric(18, 2)), 10, 0)
GO
