INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (75, N'Rush Hour 3', N'Hora Punta 3', N'¡La prisa está encendida!', CAST(N'2007-08-10' AS Date), N'Después de un intento de asesinato del embajador Han, el inspector Lee y el detective Carter vuelven a la acción mientras se dirigen a París para proteger a una mujer francesa que conoce a los líderes secretos de las Tríadas. Lee también mantiene reuniones secretas con una autoridad de las Naciones Unidas, pero sus luchas personales con un cerebro criminal chino llamado Kenji, que revela que es el hermano perdido de Lee hace mucho tiempo.', N'', 57, 71, 241, 1, 17, 91, 4, CAST(140000000.00 AS Numeric(18, 2)), CAST(258022233.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (76, N'Rush Hour 2', N'Hora Punta 2', N'¡Prepárate para una segunda carrera!', CAST(N'2001-08-03' AS Date), N'Es tiempo de vacaciones para Carter, ya que se encuentra junto a Lee en Hong Kong deseando más emoción. Mientras Carter quiere salir de fiesta y conocer a las damas, Lee busca a un señor de la pandilla Triad que puede ser responsable de matar a dos hombres en la embajada estadounidense. Las cosas se complican cuando la pareja se topa con un complot de falsificación. Los chicos pronto se ven metido hasta el cuello en peleas a puñetazos y situaciones que ponen en peligro sus vidas. Un viaje de regreso a Estados Unidos puede proporcionar respuestas sobre el atentado, la falsificación y la verdadera lealtad de la sexy agente de aduanas Isabella.', N'', 57, 14, 241, 1, 17, 90, 3, CAST(90000000.00 AS Numeric(18, 2)), CAST(347425832.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (77, N'Men in Black', N'Hombres de Negro', N'Protegiendo la tierra de la escoria del universo.', CAST(N'1997-07-02' AS Date), N'Hombres de Negro sigue las hazañas de los agentes Kay y Jay, miembros de una organización ultrasecreta establecida para monitorear y controlar la actividad extraterrestre en la Tierra. Los dos Hombres de Negro se encuentran en medio del complot mortal de un terrorista intergaláctico que ha llegado a la Tierra para asesinar a dos embajadores de galaxias opuestas. Para evitar que los mundos choquen, el MiB debe localizar al terrorista y evitar la destrucción de la Tierra. Es sólo otro día típico para los Hombres de Negro.', N'http://www.sonypictures.com/homevideo/meninblack/', 31, 41, 241, 1, 3, 98, 2, CAST(90000000.00 AS Numeric(18, 2)), CAST(589390539.00 AS Numeric(18, 2)), 3, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (78, N'The Departed', N'Infiltrados', N'Mentiras. Traición. Sacrificio. ¿Qué tan lejos lo llevarás?', CAST(N'2006-10-06' AS Date), N'Para acabar con la mafia irlandesa del sur de Boston, la policía envía a uno de los suyos a infiltrarse en el inframundo, sin darse cuenta de que el sindicato ha hecho lo mismo. Mientras un policía encubierto busca el favor del capo de la mafia, un criminal de carrera asciende en las filas policiales. Pero ambas partes pronto descubren que hay un topo entre ellos.', N'http://thedeparted.warnerbros.com/', 9, 6, 241, 1, 9, 151, 6, CAST(90000000.00 AS Numeric(18, 2)), CAST(289847354.00 AS Numeric(18, 2)), 5, 4)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (79, N'Die Hard: With A Vengeance', N'Duro de Matar: La Venganza', N'Piensa rápido. Mira vivo. Morir duro.', CAST(N'1995-08-18' AS Date), N'El detective de Nueva York John McClane está de regreso y patea traseros a los malos en la tercera entrega de esta serie llena de acción, en la que forma equipo con el civil Zeus Carver para evitar la pérdida de vidas inocentes. McClane pensó que lo había visto todo, hasta que un genio llamado Simon involucra a McClane, su nuevo "socio" (y su amada ciudad) en un juego mortal que exige su concentración.', N'', 58, 72, 241, 1, 4, 131, 5, CAST(90000000.00 AS Numeric(18, 2)), CAST(366101666.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (80, N'Cinderella Man', N'El Hombre que Cambió el Mundo', N'La extraordinaria lucha de un hombre para salvar a la familia que amaba.', CAST(N'2005-09-09' AS Date), N'La historia real del boxeador Jim Braddock quien, en la década de 1920, después de su retiro, tiene un regreso sorpresa para sacarlo a él y a su familia de un estado socialmente pobre.', N'http://www.cinderellamanmovie.com/index.php', 40, 20, 241, 1, 2, 144, 4, CAST(88000000.00 AS Numeric(18, 2)), CAST(108539911.00 AS Numeric(18, 2)), 3, 0)
GO
