INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (86, N'Bruce Almighty', N'Todopoderoso', N'En Bruce confiamos', CAST(N'2003-05-23' AS Date), N'Bruce Nolan trabaja arduamente como reportero de televisión de "interés humano" en Buffalo, Nueva York. A pesar de sus altos índices de audiencia y el amor de su hermosa novia, Grace, Bruce sigue insatisfecho. Al final del peor día de su vida, ridiculiza airadamente a Dios, y el Todopoderoso responde, dotando a Bruce de todos sus poderes divinos.', N'http://www.brucealmighty.com/', 16, 44, 241, 1, 7, 101, 4, CAST(81000000.00 AS Numeric(18, 2)), CAST(484592874.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (87, N'Mission: Impossible', N'Misión: Imposible', N'Espere lo imposible.', CAST(N'1996-05-22' AS Date), N'Cuando Ethan Hunt, el líder de un excelente equipo de espionaje cuya peligrosa operación salió mal sin explicación, descubre que un topo ha penetrado en la CIA, se sorprende al saber que él es el sospechoso número uno. Para limpiar su nombre, Hunt ahora debe descubrir al verdadero agente doble y, en el proceso, igualar el marcador.', N'http://www.missionimpossible.com/', 59, 59, 241, 1, 9, 110, 2, CAST(80000000.00 AS Numeric(18, 2)), CAST(457696359.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (88, N'Deep Impact', N'Impacto Profundo', N'El cielo y la tierra están a punto de chocar.', CAST(N'1998-05-08' AS Date), N'Una roca espacial de siete millas de ancho se precipita hacia la Tierra, amenazando con destruir el planeta. Ahora le toca al presidente de los Estados Unidos salvar al mundo. Nombra a un astronauta veterano y duro para que dirija una tripulación conjunta estadounidense-rusa al espacio para destruir el cometa antes del impacto. Mientras tanto, una periodista emprendedora utiliza su inteligencia para descubrir la primicia del siglo.', N'', 60, 8, 241, 1, 3, 121, 3, CAST(80000000.00 AS Numeric(18, 2)), CAST(349464664.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (89, N'Road to Perdition', N'Camino a la Perdición', N'Ore por Michael Sullivan.', CAST(N'2002-07-12' AS Date), N'Mike Sullivan trabaja como sicario para el jefe criminal John Rooney. Sullivan ve a Rooney como una figura paterna, sin embargo, después de que su hijo es testigo de un asesinato, Mike Sullivan se encuentra huyendo en un intento de salvar la vida de su hijo y al mismo tiempo buscando venganza contra quienes le hicieron daño.', N'', 61, 73, 241, 1, 14, 117, 5, CAST(80000000.00 AS Numeric(18, 2)), CAST(181000000.00 AS Numeric(18, 2)), 6, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (90, N'A Beautiful Mind', N'Una Mente Brillante', N'Necesito creer que algo extra ordinario es posible ...', CAST(N'2001-12-21' AS Date), N'En la Universidad de Princeton, John Nash lucha por hacer una contribución valiosa que sirva como legado al mundo de las matemáticas. Finalmente logra un avance revolucionario que eventualmente le valdrá el Premio Nobel. Después de graduarse, se dedica a la enseñanza y se involucra románticamente con su alumna Alicia. Mientras tanto, el gobierno le pide ayuda para descifrar los códigos soviéticos, lo que pronto lo involucra en un aterrador complot de conspiración. Nash se vuelve cada vez más paranoico hasta que un descubrimiento pone patas arriba todo su mundo. Ahora sólo con la ayuda de Alicia podrá recuperar su fuerza mental y recuperar su condición de gran matemático como lo conocemos hoy.', N'http://www.abeautifulmind.com/', 40, 20, 241, 1, 2, 135, 3, CAST(58000000.00 AS Numeric(18, 2)), CAST(313542341.00 AS Numeric(18, 2)), 8, 4)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (91, N'Children of Men', N'Los Niños del Hombre', N'El futuro es cosa del pasado.', CAST(N'2006-09-22' AS Date), N'En 2027, en un mundo caótico en el que los humanos ya no pueden procrear, un ex activista acepta ayudar a transportar a una mujer milagrosamente embarazada a un santuario en el mar, donde el nacimiento de su hijo puede ayudar a los científicos a salvar el futuro de la humanidad.', N'http://www.universalstudiosentertainment.com/children-of-men/', 38, 74, 241, 1, 3, 109, 5, CAST(76000000.00 AS Numeric(18, 2)), CAST(69900000.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (92, N'Munich', N'Munich', N'El mundo estaba observando en 1972 mientras 11 atletas israelíes fueron asesinados en los Juegos Olímpicos de Munich. Esta es la historia de lo que sucedió después.', CAST(N'2005-12-23' AS Date), N'Durante los Juegos Olímpicos de Munich de 1972, once atletas israelíes son tomados como rehenes y asesinados por un grupo terrorista palestino conocido como Septiembre Negro. En represalia, el gobierno israelí recluta a un grupo de agentes del Mossad para localizar y ejecutar a los responsables del ataque.', N'', 4, 41, 241, 1, 2, 163, 5, CAST(77000000.00 AS Numeric(18, 2)), CAST(130358911.00 AS Numeric(18, 2)), 5, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (93, N'Independence Day', N'El Día de la Independencia', N'Tierra. Échale un buen vistazo. Puede ser el último.', CAST(N'1996-07-02' AS Date), N'El 2 de julio, una nave nodriza alienígena gigante entra en órbita alrededor de la Tierra y despliega varias docenas de naves espaciales "destructoras" en forma de platillo que rápidamente arrasan las principales ciudades del planeta. El 3 de julio, Estados Unidos lleva a cabo un contraataque coordinado que fracasa. El 4 de julio se diseña un plan para acceder al interior de la nave nodriza extraterrestre en el espacio, con el fin de colocar un misil nuclear.', N'', 42, 57, 241, 1, 3, 145, 3, CAST(75000000.00 AS Numeric(18, 2)), CAST(817400891.00 AS Numeric(18, 2)), 2, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (94, N'X-Men', N'X-Men', N'Comienza la evolución', CAST(N'2000-08-18' AS Date), N'Dos mutantes, Rogue y Wolverine, llegan a una academia privada para los de su especie cuyo equipo de superhéroes residentes, los X-Men, deben oponerse a una organización terrorista con poderes similares.', N'', 14, 4, 241, 1, 4, 104, 3, CAST(75000000.00 AS Numeric(18, 2)), CAST(296339527.00 AS Numeric(18, 2)), 0, 0)
GO
