GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (99, N'Talladega Nights: The Ballad of Ricky Bobby', N'Ricky Bobby: Loco por la Velocidad', N'La historia de un hombre que solo podía contar con el #1', CAST(N'2006-09-15' AS Date), N'Amigos de toda la vida e ídolos nacionales Ricky Bobby y Cal Naughton Jr. se han ganado sus galones de NASCAR con su asombrosa habilidad para terminar carreras en el primer y segundo puesto, respectivamente, y con frases como "¡Agita y hornea!" Pero cuando un rival francés El conductor se desliza hacia la pista para desafiar sus récords, tendrá que pisar el acelerador para conservar su estatus de líder.', N'http://www.sonypictures.com/homevideo/talladeganights/', 63, 76, 241, 1, 7, 108, 4, CAST(72500000.00 AS Numeric(18, 2)), CAST(162966177.00 AS Numeric(18, 2)), 0, 0)
