INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (102, N'Jarhead', N'Soldado Anónimo', N'Bienvenido a la succión.', CAST(N'2006-01-13' AS Date), N'Jarhead es una película sobre la experiencia del marine estadounidense Anthony Swofford en la Guerra del Golfo. Después de soportar un arduo campo de entrenamiento, Swafford y su unidad son enviados al Golfo Pérsico, donde están ansiosos por luchar pero se ven obligados a mantenerse alejados de la acción. Mientras tanto, Swofford recibe noticias de que su novia lo está engañando. Quiere desesperadamente matar a alguien y finalmente poner en práctica su entrenamiento.', N'', 61, 1, 241, 1, 5, 125, 5, CAST(72000000.00 AS Numeric(18, 2)), CAST(96889998.00 AS Numeric(18, 2)), 0, 0)
