INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (103, N'The Village', N'La Aldea', N'No hay vuelta atrás', CAST(N'2004-08-20' AS Date), N'Cuando un joven voluntarioso intenta aventurarse más allá de su apartada aldea de Pensilvania, sus acciones desencadenan una cadena de incidentes escalofriantes que alterarán a la comunidad para siempre.', N'', 62, 7, 241, 1, 9, 108, 4, CAST(60000000.00 AS Numeric(18, 2)), CAST(256697520.00 AS Numeric(18, 2)), 1, 0)
