INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (111, N'Die Hard 2', N'Duro de Matar 2', N'Más duro', CAST(N'1990-07-04' AS Date), N'John McClane es un policía fuera de servicio presa de una sensación de déjà vu cuando, en una nevada víspera de Navidad en la capital del país, terroristas toman un importante aeropuerto internacional y mantienen como rehenes a miles de viajeros de vacaciones. Comandos militares renegados liderados por un oficial asesino y rebelde conspiran para rescatar a un narcotraficante de la justicia y están preparados para cualquier contingencia excepto una: los actos heroicos de McClane.', N'', 69, 52, 241, 1, 4, 124, 5, CAST(70000000.00 AS Numeric(18, 2)), CAST(240031094.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (112, N'The Long Kiss Goodnight', N'Un Buen Día para Morir', N'Lo que se olvida no siempre se ha ido.', CAST(N'1996-11-29' AS Date), N'Samantha Caine, ama de casa de los suburbios, es la madre ideal para su hija Caitlin de 8 años. Vive en Honesdale, PA, trabaja como profesora en una escuela y prepara las mejores delicias Rice Krispie de la ciudad. Pero cuando recibe un golpe en la cabeza, comienza a recordar pequeños fragmentos de su vida anterior como agente letal y ultrasecreta.', N'', 69, 14, 241, 1, 4, 120, 6, CAST(65000000.00 AS Numeric(18, 2)), CAST(89456761.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (113, N'Apollo 13', N'Apolo 13', N'Houston, tenemos un problema.', CAST(N'1995-06-30' AS Date), N'La historia real de los problemas técnicos que arruinaron la misión lunar Apolo 13 en 1971, poniendo en riesgo la vida del astronauta Jim Lovell y su tripulación, y el viaje fallido se convirtió en una emocionante saga de heroísmo. A la deriva a más de 200.000 millas de la Tierra, los astronautas trabajan furiosamente con el equipo de tierra para evitar la tragedia.', N'', 40, 20, 241, 1, 13, 140, 2, CAST(52000000.00 AS Numeric(18, 2)), CAST(355237933.00 AS Numeric(18, 2)), 9, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (114, N'Saving Private Ryan', N'Rescatando al Soldado Ryan', N'La misión es un hombre.', CAST(N'1998-07-24' AS Date), N'Mientras las tropas estadounidenses asaltan las playas de Normandía, tres hermanos yacen muertos en el campo de batalla y un cuarto atrapado detrás de las líneas enemigas. El capitán de los guardabosques, John Miller, y siete hombres tienen la tarea de penetrar en territorio controlado por los alemanes y traer al niño a casa.', N'', 4, 41, 241, 1, 5, 170, 5, CAST(70000000.00 AS Numeric(18, 2)), CAST(481840909.00 AS Numeric(18, 2)), 11, 5)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (115, N'Fight Club', N'El Club de la Pelea', N'Travesura. Violencia. Jabón.', CAST(N'1999-10-15' AS Date), N'Un insomne ​​que es una bomba de tiempo y un vendedor de jabón resbaladizo canalizan la agresión masculina primitiva hacia una nueva e impactante forma de terapia. Su concepto se hace popular, con \"clubes de lucha\" clandestinos formándose en cada ciudad, hasta que un excéntrico se interpone en el camino y enciende una espiral fuera de control hacia el olvido.', N'http://www.foxmovies.com/movies/fight-club', 70, 79, 241, 1, 9, 139, 6, CAST(63000000.00 AS Numeric(18, 2)), CAST(100900000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (116, N'The Matrix', N'Matrix', N'Bienvenido al mundo real.', CAST(N'1999-06-11' AS Date), N'Ambientada en el siglo XXII, Matrix cuenta la historia de un hacker informático que se une a un grupo de insurgentes clandestinos que luchan contra las enormes y poderosas computadoras que ahora gobiernan la tierra.', N'http://www.warnerbros.com/matrix', 39, 49, 241, 1, 3, 136, 5, CAST(65000000.00 AS Numeric(18, 2)), CAST(463500000.00 AS Numeric(18, 2)), 4, 4)
GO
