INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (118, N'Cliffhanger', N'Máximo Riesgo', N'El colmo de la aventura.', CAST(N'1993-06-25' AS Date), N'Un año después de perder a su amigo en una trágica caída de 4.000 pies, el ex guardabosques Gabe Walker y su compañero, Hal, son llamados a regresar al mismo pico para rescatar a un grupo de escaladores varados, solo para descubrir que los escaladores son en realidad secuestradores ladrones que Están buscando cajas llenas de dinero.', N'', 69, 15, 241, 1, 4, 113, 5, CAST(65000000.00 AS Numeric(18, 2)), CAST(255325036.00 AS Numeric(18, 2)), 3, 0)
GO
