INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (120, N'GoldenEye', N'GoldenEye', N'Sin limites. Sin miedos. No hay sustitutos.', CAST(N'1995-11-24' AS Date), N'James Bond debe desenmascarar al misterioso líder del Janus Syndicate y evitar que el líder utilice el sistema de armas GoldenEye para infligir una devastadora venganza en Gran Bretaña.', N'http://www.mgm.com/view/movie/757/Goldeneye/', 54, 51, 240, 1, 9, 130, 3, CAST(58000000.00 AS Numeric(18, 2)), CAST(352194034.00 AS Numeric(18, 2)), 0, 0)
