INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (121, N'The Black Dahlia', N'La Dalia Negra', N'Inspirado por el asesinato sin resolver más notorio en la historia de California.', CAST(N'2006-09-15' AS Date), N'Lee Blanchard y Bucky Bleichert son ex boxeadores convertidos en policías en Los Ángeles de la década de 1940 y, cuando una joven aspirante a actriz aparece muerta, Blanchard y Bleichert deben lidiar con la corrupción, el narcisismo, las películas de solteros y la locura familiar mientras persiguen al asesino.', N'', 59, 80, 241, 1, 14, 122, 5, CAST(50000000.00 AS Numeric(18, 2)), CAST(49332692.00 AS Numeric(18, 2)), 1, 0)
