INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (122, N'The Truman Show', N'El Show de Truman', N'En el aire. Inconsciente.', CAST(N'1998-06-05' AS Date), N'Truman Burbank es la estrella de "The Truman Show", un programa de televisión "reality" que se transmite las 24 horas del día y que transmite todos los aspectos de su vida, en vivo y en color, sin su conocimiento. Toda su vida ha sido un culebrón interminable para el consumo del resto del mundo. Y todos los que conoce, incluidos su esposa y su mejor amigo, son realmente actores a los que se les paga para ser parte de su vida.', N'', 36, 81, 241, 1, 2, 103, 2, CAST(60000000.00 AS Numeric(18, 2)), CAST(264118201.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (123, N'Event Horizon', N'Horizonte Final', N'Espacio infinito - Terror infinito', CAST(N'1997-08-15' AS Date), N'En el año 2047, un grupo de astronautas es enviado a investigar y rescatar la nave estelar perdida "Event Horizon". El barco desapareció misteriosamente 7 años antes en su viaje inaugural y con su regreso viene aún más misterio cuando la tripulación del \"Lewis and Clark\" descubre la verdad real detrás de su desaparición y algo aún más aterrador.', N'', 74, 2, 241, 1, 3, 96, 6, CAST(60000000.00 AS Numeric(18, 2)), CAST(47073851.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (124, N'The Bourne Identity', N'Identidad Desconocida', N'Era el arma perfecta hasta que se convirtió en el objetivo.', CAST(N'2002-06-14' AS Date), N'Herido al borde de la muerte y amnesia, Jason Bourne es rescatado en el mar por un pescador. Sin nada más que un número de cuenta en un banco suizo, comienza a reconstruir su vida, pero descubre que muchas personas con las que se encuentra lo quieren muerto. Sin embargo, Bourne se da cuenta de que tiene las habilidades mentales y de combate de un espía de clase mundial, pero ¿para quién trabaja?', N'http://www.universalstudiosentertainment.com/the-bourne-identity/', 52, 56, 241, 1, 9, 118, 4, CAST(60000000.00 AS Numeric(18, 2)), CAST(214034224.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (125, N'Hellboy', N'Hellboy', N'Desde el lado oscuro hasta nuestro lado.', CAST(N'2004-04-02' AS Date), N'En los últimos días de la Segunda Guerra Mundial, los nazis intentan utilizar la magia negra para ayudar a su causa agonizante. Los aliados atacan el campamento donde se lleva a cabo la ceremonia, pero no antes de que un demonio, Hellboy, ya haya sido conjurado. Al unirse a las fuerzas aliadas, Hellboy eventualmente crece hasta la edad adulta, sirviendo a la causa del bien en lugar del mal.', N'http://www.sonypictures.com/homevideo/hellboy/', 71, 19, 241, 1, 4, 122, 4, CAST(66000000.00 AS Numeric(18, 2)), CAST(99318987.00 AS Numeric(18, 2)), 0, 0)
