INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (138, N'Kill Bill: Vol. 2', N'Kill Bill: La Venganza 2', N'La novia está de vuelta para el corte final.', CAST(N'2004-04-23' AS Date), N'La Novia continúa inquebrantablemente con su furia de venganza contra la banda de asesinos que habían intentado matarla a ella y a su hijo por nacer. Visita a cada uno de sus antiguos socios uno por uno, marcando a las víctimas en su Lista de Muerte Cinco hasta que no queda nada por hacer... excepto matar a Bill.', N'', 79, 84, 241, 1, 17, 136, 6, CAST(30000000.00 AS Numeric(18, 2)), CAST(152159461.00 AS Numeric(18, 2)), 0, 0)
