INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (139, N'Blade II', N'Blade II', N'Más rápido. Estafador. Más mortal.', CAST(N'2002-03-22' AS Date), N'Ha ocurrido una rara mutación dentro de la comunidad vampírica: The Reaper. Un vampiro tan consumido por una sed de sangre insaciable que se alimenta tanto de vampiros como de humanos, transformando a las víctimas que tienen la mala suerte de sobrevivir en Reapers. La Nación Vampiro le pide ayuda a Blade para prevenir una plaga de pesadilla que acabaría con humanos y vampiros.', N'http://www.warnerbros.com/blade-ii', 71, 14, 241, 1, 4, 116, 6, CAST(50000000.00 AS Numeric(18, 2)), CAST(155010032.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (140, N'Flags of our Fathers', N'La Conquista del Honor', N'Luchan por su país pero mueren por sus amigos.', CAST(N'2006-10-20' AS Date), N'Había cinco infantes de marina y un ayudante médico de la Armada fotografiados levantando la bandera de los Estados Unidos en el monte Suribachi por Joe Rosenthal el 23 de febrero de 1945. Esta es la historia de tres de los seis militares supervivientes: John ''Doc'' Bradley, Pvt. René Gagnon y Pvt. Ira Hayes, que luchó en la batalla para arrebatar Iwo Jima a los japoneses.', N'', 10, 2, 241, 1, 5, 132, 5, CAST(55000000.00 AS Numeric(18, 2)), CAST(65900249.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (141, N'Casino', N'Casino', N'Nadie se queda en la cima para siempre.', CAST(N'1996-02-23' AS Date), N'La vida del paraíso del juego, Las Vegas, y su oscuro vientre mafioso.', N'', 9, 1, 241, 1, 14, 178, 6, CAST(50000000.00 AS Numeric(18, 2)), CAST(116112375.00 AS Numeric(18, 2)), 1, 0)
