INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (142, N'Robin Hood: Prince of Thieves', N'Robin Hood: El Príncipe de los Ladrones', N'Por el bien de todos los hombres y el amor de una mujer, luchó para defender la justicia violando la ley.', CAST(N'1991-06-14' AS Date), N'Cuando el cobarde sheriff de Nottingham asesina al padre de Robin, el legendario arquero jura venganza. Para cumplir su misión, Robin une fuerzas con un grupo de aldeanos exiliados (y la atractiva Maid Marian), y juntos luchan para poner fin al reinado de terror del malvado sheriff.', N'', 17, 21, 241, 1, 8, 155, 2, CAST(48000000.00 AS Numeric(18, 2)), CAST(390493908.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (143, N'Shrek', N'Shrek', N'El mayor cuento de hadas nunca dijo.', CAST(N'2001-05-18' AS Date), N'No es fácil ser verde, especialmente si eres un ogro simpático (aunque maloliente) llamado Shrek. En una misión para rescatar a una hermosa princesa de las garras de un dragón que escupe fuego, Shrek se une a un compatriota poco común: un burro bromista.', N'http://www.shrek.com/', 67, 86, 241, 1, 11, 90, 1, CAST(60000000.00 AS Numeric(18, 2)), CAST(484409218.00 AS Numeric(18, 2)), 2, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (144, N'Shanghai Knights', N'Shanghai Kid en Londres', N'Una patada real en el culo.', CAST(N'2003-02-07' AS Date), N'El dúo dinámico formado por Chon Wang y Roy O''Bannon regresa para otra loca aventura. Esta vez, están en Londres para vengar el asesinato del padre de Chon, pero terminan en un caso aún mayor. La hermana de Chon está allí para hacer lo mismo, pero en cambio descubre un complot para matar a la familia real. Sin embargo, nadie le cree y depende de Chon y Roy (que tiene el romance en mente) demostrarle que tiene razón.', N'', 81, 7, 241, 1, 17, 114, 4, CAST(50000000.00 AS Numeric(18, 2)), CAST(88323487.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (145, N'Indiana Jones and the Last Crusade', N'Indiana Jones y la Última Cruzada', N'El hombre con el sombrero ha vuelto. Y esta vez, está trayendo a su padre.', CAST(N'1989-05-24' AS Date), N'Cuando el Dr. Henry Jones Sr. desaparece repentinamente mientras busca el Santo Grial, el eminente arqueólogo Indiana debe formar equipo con Marcus Brody, Sallah y Elsa Schneider para seguir los pasos de su padre e impedir que los nazis recuperen el poder de la vida eterna.', N'http://www.indianajones.com/crusade', 4, 13, 241, 1, 8, 127, 2, CAST(48000000.00 AS Numeric(18, 2)), CAST(474200000.00 AS Numeric(18, 2)), 3, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (146, N'Star Trek: First Contact', N'Viaje a las Estrellas: Primer Contacto', N'La resistencia es inútil.', CAST(N'1996-11-22' AS Date), N'Los Borg, una implacable raza de cyborgs, están en curso directo hacia la Tierra. Violando las órdenes de mantenerse alejados de la batalla, el Capitán Picard y la tripulación del recién encargado USS Enterprise E persiguen a los Borg en el tiempo para evitar que los invasores cambien la historia de la Federación y asimilen la galaxia.', N'http://www.startrek.com/startrek/view/series/MOV/008/index.html', 68, 2, 241, 1, 3, 111, 3, CAST(45000000.00 AS Numeric(18, 2)), CAST(146027888.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (147, N'Blade', N'Blade: Cazador de Vampiros', N'Parte hombre. Parte de vampiro. Todo héroe.', CAST(N'1998-08-21' AS Date), N'Cuando la madre de Blade fue mordida por un vampiro durante el embarazo, no sabía que le había dado a su hijo un regalo especial mientras moría: todos los buenos atributos vampíricos en combinación con las mejores habilidades humanas. Blade y su mentor Whistler luchan contra un malvado vampiro rebelde (Deacon Frost) que planea hacerse cargo del anticuado consejo de vampiros, capturar a Blade y resucitar al voraz dios de la sangre, La Magra.', N'http://www.warnerbros.com/blade', 82, 14, 241, 1, 12, 120, 6, CAST(40000000.00 AS Numeric(18, 2)), CAST(131183530.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (148, N'Patriot Games', N'Juegos de Patriotas', N'No por honor. No para el país. Para su esposa e hijo.', CAST(N'1992-06-05' AS Date), N'Cuando el analista de la CIA Jack Ryan interfiere con un asesinato del IRA, una facción renegada apunta a Jack y su familia como venganza.', N'', 73, 2, 241, 1, 9, 117, 5, CAST(45000000.00 AS Numeric(18, 2)), CAST(178051587.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (149, N'The Fugitive', N'El Fugitivo', N'Una esposa asesinada. Un hombre de un solo brazo. Un detective obsesionado. Comienza la persecución.', CAST(N'1993-08-06' AS Date), N'Richard Kimble, acusado injustamente de asesinar a su esposa, escapa de la ley en un intento de encontrar al asesino y limpiar su nombre. Lo persigue un equipo de alguaciles estadounidenses liderados por el ayudante Samuel Gerard, un detective decidido que no descansará hasta que capturen a Richard. Mientras Richard lidera al equipo a través de una serie de intrincadas persecuciones, descubre los secretos detrás de la muerte de su esposa y lucha por exponer al asesino antes de que sea demasiado tarde.', N'', 83, 6, 241, 1, 9, 130, 3, CAST(44000000.00 AS Numeric(18, 2)), CAST(368875760.00 AS Numeric(18, 2)), 7, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (150, N'The Prestige', N'El Gran Truco', N'¿Estás mirando de cerca?', CAST(N'2006-10-20' AS Date), N'Una misteriosa historia de dos magos cuya intensa rivalidad los lleva a una batalla de por vida por la supremacía, llena de obsesión, engaño y celos con consecuencias peligrosas y mortales.', N'http://wwws.warnerbros.de/theprestige/', 27, 7, 241, 1, 18, 130, 4, CAST(40000000.00 AS Numeric(18, 2)), CAST(109700000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (151, N'The Last of the Mohicans', N'El Último de los Mohicanos', N'El primer héroe estadounidense.', CAST(N'1992-09-25' AS Date), N'Mientras los soldados ingleses y franceses luchan por el control de las colonias americanas en el siglo XVIII, los colonos y los nativos americanos se ven obligados a tomar partido. Cora y su hermana Alice, sin saberlo, se meten en problemas, pero Hawkeye, un colono huérfano adoptado por el último de los mohicanos, los salva a regañadientes.', N'', 34, 21, 241, 1, 8, 112, 3, CAST(40000000.00 AS Numeric(18, 2)), CAST(75505856.00 AS Numeric(18, 2)), 1, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (152, N'Apocalypto', N'Apocalypto', N'Nadie puede superar su destino.', CAST(N'2006-12-08' AS Date), N'Ambientada en la civilización maya, cuando la idílica presencia de un hombre es brutalmente perturbada por una violenta fuerza invasora, éste es llevado a un peligroso viaje a un mundo gobernado por el miedo y la opresión, donde le espera un final desgarrador. Por un giro del destino y estimulado por el poder de su amor por su mujer y su familia, hará una escapada desesperada para regresar a casa y, en última instancia, salvar su forma de vida.', N'', 65, 7, 241, 8, 8, 138, 6, CAST(40000000.00 AS Numeric(18, 2)), CAST(120600000.00 AS Numeric(18, 2)), 3, 0)
GO
