INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (154, N'Back to the Future Part III', N'Volver al Futuro III', N'Han guardado el mejor viaje para el final ... pero esta vez pueden haber ido demasiado lejos.', CAST(N'1990-05-25' AS Date), N'La última entrega de la trilogía Regreso al futuro encuentra a Marty sacando el confiable DeLorean de un pozo de mina y buscando a Doc en el Salvaje Oeste de 1885. Pero cuando su máquina del tiempo se estropea, los viajeros quedan varados en una tierra de espuelas. Surgen más problemas cuando Doc se enamora de la bella maestra Clara Clayton y Marty se enreda con Buford Tannen.', N'http://www.backtothefuture.com/movies/backtothefuture3', 20, 41, 241, 1, 3, 118, 2, CAST(40000000.00 AS Numeric(18, 2)), CAST(244500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (155, N'Back to the Future Part II', N'Volver al Futuro II', N'¿Carreteras? A dónde vamos, ¡no necesitamos carreteras!', CAST(N'1989-11-22' AS Date), N'Marty y Doc vuelven a hacerlo en esta loca secuela del éxito de taquilla de 1985 mientras el dúo de viajeros en el tiempo se dirige al 2015 para cortar de raíz algunos problemas de la familia McFly. Pero las cosas salen mal gracias al matón Biff Tannen y a un molesto almanaque deportivo. En un último intento por aclarar las cosas, Marty se encuentra destinado a 1955 y cara a cara con sus padres adolescentes... otra vez.', N'http://www.backtothefuture.com/movies/backtothefuture2', 20, 41, 241, 1, 3, 108, 2, CAST(40000000.00 AS Numeric(18, 2)), CAST(331900000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (156, N'Licence to Kill', N'007: Con Licencia para Matar', N'Su lado malo es un lugar peligroso para estar.', CAST(N'1989-06-13' AS Date), N'James Bond y su colega estadounidense Félix Leiter arrestan al narcotraficante Sánchez, quien logra escapar y se venga de Félix y su esposa. Bond sólo sabe una cosa: la venganza.', N'http://www.mgm.com/view/movie/1111/License-to-Kill/', 84, 51, 240, 1, 9, 133, 5, CAST(32000000.00 AS Numeric(18, 2)), CAST(156000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (157, N'The Living Daylights', N'007: Su Nombre es Peligro', N'Con licencia para emocionar.', CAST(N'1987-06-27' AS Date), N'James Bond ayuda a un general ruso a escapar hacia el oeste. Pronto descubre que la KGB quiere matarlo por ayudar al general. Poco tiempo después, el General es secuestrado por el Servicio Secreto, lo que hace que 007 sospeche.', N'http://www.mgm.com/view/movie/1132/The-Living-Daylights/', 84, 51, 240, 1, 9, 131, 2, CAST(40000000.00 AS Numeric(18, 2)), CAST(191200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (158, N'Sin City', N'Ciudad del Pecado', N'Camina por el callejón derecho en Sin City y puedes encontrar cualquier cosa ...', CAST(N'2005-04-01' AS Date), N'Bienvenidos a la ciudad del pecado. Esta ciudad atrae a los duros, a los corruptos y a los que tienen el corazón roto. Algunos lo llaman oscuro… Duro. Luego están quienes lo consideran su hogar: policías corruptos, mujeres sexys, justicieros desesperados. Algunos buscan venganza, otros anhelan la redención y luego están los que esperan un poco de ambas cosas. Un universo de héroes improbables y reacios que todavía intentan hacer lo correcto en una ciudad a la que se niega a importarle.', N'http://www.miramax.com/movie/sin-city/', 85, 23, 241, 1, 14, 124, 6, CAST(40000000.00 AS Numeric(18, 2)), CAST(158800000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (159, N'Serenity', N'Serenidad', N'No puedo detener la señal.', CAST(N'2005-10-07' AS Date), N'Cuando la tripulación renegada del Serenity acepta esconder a un fugitivo en su barco, se encuentran en una batalla llena de acción entre el implacable poder militar de un régimen totalitario que destruirá cualquier cosa (o a cualquiera) para recuperar a la niña y las criaturas sedientas de sangre. que deambulan por las zonas inexploradas del espacio. Pero... el mayor peligro de todos puede estar en su barco.', N'', 86, 1, 241, 1, 3, 119, 5, CAST(39000000.00 AS Numeric(18, 2)), CAST(38869464.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (160, N'Star Trek: Generations', N'Viaje a las Estrellas: Generaciones', N'Audazmente ir.', CAST(N'1994-11-18' AS Date), N'El capitán Jean-Luc Picard y la tripulación del Enterprise-D se encuentran en desacuerdo con el científico renegado Soran, que está destruyendo sistemas estelares enteros. Sólo un hombre puede ayudar a Picard a detener el plan de Soran... y lleva muerto setenta y ocho años.', N'', 87, 2, 241, 1, 3, 118, 2, CAST(35000000.00 AS Numeric(18, 2)), CAST(118071125.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (161, N'Never Say Never Again', N'Nunca Digas Nunca Jamás', N'Sean Connery es James Bond 007', CAST(N'1983-10-07' AS Date), N'James Bond regresa como el agente secreto 007 una vez más para luchar contra la malvada organización SPECTRE. Bond debe derrotar a Largo, quien ha robado dos ojivas atómicas para chantajearlas. Pero Bond tiene un aliado en la novia de Largo, la esbelta Domino, quien se enamora de Bond y busca venganza. Esta es la última vez que Sean Connery interpreta al Agente Secreto 007 de Su Majestad.', N'http://www.mgm.com/view/movie/1345/Never-Say-Never-Again/', 88, 88, 241, 1, 9, 134, 2, CAST(36000000.00 AS Numeric(18, 2)), CAST(160000000.00 AS Numeric(18, 2)), 0, 0)
GO
