INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (169, N'The Assassination of Jesse James by the Coward Robert Ford', N'El Asesinato de Jesse James por el Cobarde Robert Ford', N'Más allá del mito se encuentra la mayor traición de Estados Unidos', CAST(N'2007-09-21' AS Date), N'Se rumorea que el forajido Jesse James es el "arma más rápida de Occidente". Robert Ford, un entusiasta recluta de la notoria pandilla de James, finalmente se pone celoso del famoso forajido y, cuando Robert y su hermano sienten la oportunidad de matar a James, su acción asesina eleva a su objetivo a un estado casi mítico.', N'http://jessejamesmovie.warnerbros.com/', 93, 90, 241, 1, 1, 159, 5, CAST(30000000.00 AS Numeric(18, 2)), CAST(15000000.00 AS Numeric(18, 2)), 2, 0)
GO
