INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (184, N'O Brother, Where Art Thou?', N'¿Dónde Estás, Hermano?', N'Tienen un plan ... pero no una pista.', CAST(N'2000-09-15' AS Date), N'En el profundo sur durante la década de 1930, tres convictos fugitivos buscan un tesoro escondido mientras un implacable agente de la ley los persigue. En su viaje se topan con muchos personajes cómicos y situaciones increíbles. Basado en la ''Odisea'' de Homero.', N'', 5, 7, 241, 1, 7, 107, 3, CAST(26000000.00 AS Numeric(18, 2)), CAST(71900000.00 AS Numeric(18, 2)), 2, 0)
