INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (186, N'The Passion of the Christ', N'La Pasión de Cristo', N'Por sus heridas, fuimos curados.', CAST(N'2004-03-26' AS Date), N'\"La Pasión de Cristo\" es una película sobre las últimas 12 horas de la vida de Jesús. El director Mel Gibson recibió muchas críticas de la crítica y el público por su descripción explícita y su enfoque en la violencia y el sufrimiento de Cristo, especialmente por parte de la comunidad judía. Los idiomas de la película son árabe, latín y hebreo y sus actores son legos, lo que también fue recibido controvertidamente.', N'http://www.thepassionofthechrist.com/', 65, 25, 241, 7, 2, 126, 6, CAST(30000000.00 AS Numeric(18, 2)), CAST(611900000.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (187, N'The Untouchables', N'Los Intocables', N'¿Qué estás dispuesto a hacer?', CAST(N'1987-06-03' AS Date), N'El joven agente del Tesoro Elliot Ness llega a Chicago y está decidido a acabar con Al Capone, pero no será fácil porque Capone tiene a la policía en el bolsillo. Ness conoce a Jimmy Malone, un patrullero veterano y probablemente el más honorable de la fuerza. Le pide a Malone que lo ayude a capturar a Capone, pero Malone le advierte que si va tras Capone, irá a la guerra.', N'', 59, 2, 241, 1, 14, 119, 5, CAST(25000000.00 AS Numeric(18, 2)), CAST(106240936.00 AS Numeric(18, 2)), 4, 1)
GO
