INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (189, N'Anchorman: The Legend of Ron Burgundy', N'El Reportero: La Leyenda de Ron Burgundy', N'Te traen las noticias para que no tengas que conseguirlo tú mismo.', CAST(N'2004-09-10' AS Date), N'Estamos en la década de 1970, y el presentador súper sexista de San Diego, Ron Burgundy, es el líder de la televisión local, pero todo eso está a punto de cambiar cuando la ambiciosa reportera Veronica Corningstone llega como nueva empleada a su estación.', N'', 63, 76, 241, 1, 7, 95, 4, CAST(26000000.00 AS Numeric(18, 2)), CAST(90600000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (190, N'Scarface', N'Cara Cortada', N'El mundo es tuyo...', CAST(N'1983-12-09' AS Date), N'Después de obtener una tarjeta verde a cambio de asesinar a un funcionario del gobierno cubano, Tony Montana reclama el tráfico de drogas en Miami. Tony asesina brutalmente a cualquiera que se interponga en su camino y eventualmente se convierte en el mayor narcotraficante del estado, controlando casi toda la cocaína que llega a través de Miami. Pero la mayor presión de la policía, las guerras con los cárteles de la droga colombianos y su propia paranoia alimentada por las drogas sirven para avivar las llamas de su eventual caída.', N'', 59, 1, 241, 1, 14, 170, 6, CAST(25000000.00 AS Numeric(18, 2)), CAST(65900000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (191, N'Star Trek IV: The Voyage Home', N'Viaje a las Estrellas IV: Misión Salvar la Tierra', N'La clave para guardar el futuro solo se puede encontrar en el pasado.', CAST(N'1986-11-26' AS Date), N'Fugitivos de la Federación por su atrevido rescate de Spock del condenado planeta Génesis, el almirante Kirk (William Shatner) y su tripulación comienzan su viaje a casa para enfrentar la justicia por sus acciones. Pero a medida que se acercan a la Tierra, la encuentran a merced de una misteriosa presencia alienígena cuyas señales están destruyendo lentamente el planeta. En un intento desesperado por responder a la llamada de la sonda, Kirk y su tripulación se remontan a finales del siglo XX. Sin embargo, pronto descubren que el mundo que alguna vez conocieron es más extraño que cualquier cosa que hayan encontrado en los confines de la galaxia.', N'', 99, 2, 241, 1, 3, 122, 2, CAST(21000000.00 AS Numeric(18, 2)), CAST(133000000.00 AS Numeric(18, 2)), 4, 0)
GO
