INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (196, N'From Dusk Till Dawn', N'Del Crepúsculo al Amanecer', N'Una noche es todo lo que se encuentra entre ellos y la libertad. Pero va a ser una noche infernal.', CAST(N'1996-01-19' AS Date), N'Seth Gecko y su hermano menor Richard huyen tras un sangriento robo a un banco en Texas. Se escapan a través de la frontera hacia México y estarán libres en casa a la mañana siguiente, cuando paguen al capo local. Sólo tienen que sobrevivir "desde el anochecer hasta el amanecer" en el punto de encuentro, que resulta ser un infierno de local de striptease.', N'http://www.miramax.com/movie/from-dusk-till-dawn/', 103, 23, 241, 1, 10, 108, 6, CAST(20000000.00 AS Numeric(18, 2)), CAST(25728961.00 AS Numeric(18, 2)), 0, 0)
