GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (199, N'Back to the Future', N'Volver al Futuro', N'Es el único niño en meterse en problemas antes de nacirse.', CAST(N'1985-07-03' AS Date), N'El adolescente de los ochenta Marty McFly es enviado accidentalmente al pasado, a 1955, interrumpiendo sin darse cuenta el primer encuentro de sus padres y atrayendo el interés romántico de su madre. Marty debe reparar el daño a la historia reavivando el romance de sus padres y, con la ayuda de su excéntrico amigo inventor Doc Brown, regresar a 1985.', N'http://www.backtothefuture.com/movies/backtothefuture1', 20, 41, 241, 1, 3, 116, 2, CAST(19000000.00 AS Numeric(18, 2)), CAST(392000000.00 AS Numeric(18, 2)), 4, 1)
