INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (202, N'Borat: Cultural Learnings of America for Make Benefit Glorious Nation of Kazakhstan', N'Borat: Lecciones Culturales de América para Beneficio de la Gloriosa Nación de Kazajistán', N'Ven a Kazajstán, ¡es bueno!', CAST(N'2006-11-02' AS Date), N'El periodista kazajo Borat Sagdiyev viaja a Estados Unidos para realizar un documental. Mientras zigzaguea por todo el país, Borat se encuentra con personas reales en situaciones reales con consecuencias histéricas. Su comportamiento retrógrado genera fuertes reacciones a su alrededor exponiendo prejuicios e hipocresías en la cultura estadounidense.', N'http://www.boratmovie.com/', 104, 28, 240, 1, 7, 84, 5, CAST(18000000.00 AS Numeric(18, 2)), CAST(261600000.00 AS Numeric(18, 2)), 1, 0)
