INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (215, N'Hulk', N'Hulk', N'Desatar al héroe dentro', CAST(N'2003-06-20' AS Date), N'Bruce Banner, un investigador genético con un pasado trágico, sufre una exposición masiva a la radiación en su laboratorio que hace que cuando se enoja se transforma en un monstruo verde furioso.', N'', 8, 1, 241, 1, 4, 138, 4, CAST(137000000.00 AS Numeric(18, 2)), CAST(245300000.00 AS Numeric(18, 2)), 0, 0)
