GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (245, N'The Terminator', N'Terminator', N'Tu futuro está en sus manos.', CAST(N'1984-10-26' AS Date), N'En un futuro post-apocalíptico, las supercomputadoras tiránicas reinantes teletransportan a un cyborg asesino conocido como "Terminator" al año 1984 para matar a Sarah Connor, cuyo hijo no nacido está destinado a liderar a los insurgentes contra la hegemonía mecánica del siglo XXI. Mientras tanto, el movimiento de resistencia humana envía a un guerrero solitario para salvaguardar a Sarah. ¿Podrá detener la máquina de matar prácticamente indestructible?', N'http://www.mgm.com/#/our-titles/1970/The-Terminator/', 15, 106, 241, 1, 3, 108, 5, CAST(6400000.00 AS Numeric(18, 2)), CAST(78400000.00 AS Numeric(18, 2)), 0, 0)
GO
