INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (250, N'Memento', N'Amnesia', N'Algunos recuerdos se olvidan mejor.', CAST(N'2000-09-05' AS Date), N'Leonard Shelby, que sufre pérdida de memoria a corto plazo después de una lesión en la cabeza, se embarca en una sombría búsqueda para encontrar al delincuente que asesinó a su esposa en este descarnado y complejo thriller que tiene más nudos que la soga de un verdugo. Para llevar a cabo su plan, Shelby toma fotografías Polaroid de personas y lugares, anotando notas contextuales en el reverso de las fotografías para ayudarle en su búsqueda y refrescar su memoria. Incluso se tatúa su propio cuerpo en un intento desesperado por recordar.', N'http://www.otnemem.com/', 27, 108, 241, 1, 9, 113, 5, CAST(9000000.00 AS Numeric(18, 2)), CAST(39700000.00 AS Numeric(18, 2)), 2, 0)
GO
