INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (267, N'Indiana Jones and the Kingdom of the Crystal Skull', N'Indiana Jones y el Reino de la Calavera de Cristal', N'La aventura continúa. . .', CAST(N'2008-05-22' AS Date), N'Ambientada durante la Guerra Fría, los soviéticos, liderados por Irina Spalko, que empuña una espada, están en busca de una calavera de cristal que tiene poderes sobrenaturales relacionados con una mística Ciudad Perdida de Oro. Después de ser capturado y luego escapar de ellos, Indy se ve obligado a dirigirse a Perú a instancias de un joven cuyo amigo (y colega de Indy), el profesor Oxley, ha sido capturado por su conocimiento del paradero del cráneo.', N'http://www.indianajones.com/site/index.html', 4, 13, 241, 1, 8, 122, 4, CAST(185000000.00 AS Numeric(18, 2)), CAST(786600000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (270, N'Transformers: Age of Extinction', N'Transformers: La Era de la Extinción', N'Esta no es la guerra. Es extinción.', CAST(N'2014-06-27' AS Date), N'A medida que la humanidad recoge los pedazos, tras la conclusión de "Transformers: Dark of the Moon", los Autobots y Decepticons prácticamente han desaparecido de la faz del planeta. Sin embargo, un grupo de poderosos e ingeniosos hombres de negocios y científicos intentan aprender de las incursiones pasadas de los Transformers y ampliar los límites de la tecnología más allá de lo que pueden controlar, todo mientras una antigua y poderosa amenaza de los Transformers pone a la Tierra en su punto de mira.', N'http://www.transformersmovie.com', 18, 46, 241, 1, 3, 165, 4, CAST(210000000.00 AS Numeric(18, 2)), CAST(1091000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (271, N'The Hobbit: The Battle of the Five Armies', N'El Hobbit: La Batalla de los Cinco Ejércitos', N'Sea testigo del capítulo definitorio de la saga de la Tierra Media', CAST(N'2014-12-01' AS Date), N'Inmediatamente después de los acontecimientos de La Desolación de Smaug, Bilbo y los enanos intentan defender la montaña de tesoros de Erebor de otros que la reclaman: los hombres de la arruinada Ciudad del Lago y los elfos del Bosque Negro. Mientras tanto, un ejército de Orcos liderado por Azog el Profanador marcha hacia Erebor, impulsado por el ascenso del señor oscuro Sauron. Enanos, elfos y hombres deben unirse, y la esperanza de la Tierra Media cae en manos de Bilbo.', N'http://www.thehobbit.com/', 12, 14, 167, 1, 12, 174, 4, CAST(250000000.00 AS Numeric(18, 2)), CAST(955100000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (272, N'Guardians of the Galaxy', N'Guardianes de la Galaxia', N'Todos los héroes comienzan en alguna parte.', CAST(N'2014-08-01' AS Date), N'A años luz de la Tierra, 26 años después de ser secuestrado, Peter Quill se convierte en el principal objetivo de una persecución tras descubrir un orbe buscado por Ronan el Acusador.', N'http://marvel.com/guardians', 128, 53, 241, 1, 3, 122, 4, CAST(195900000.00 AS Numeric(18, 2)), CAST(774200000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (273, N'Maleficent', N'Maléfica', N'No creas el cuento de hadas.', CAST(N'2014-05-28' AS Date), N'La historia no contada del villano más emblemático de Disney del clásico de 1959 ''La Bella Durmiente''. Maléfica, una joven hermosa y de corazón puro, lleva una vida idílica creciendo en un pacífico reino forestal, hasta que un día un ejército invasor amenaza la armonía de la tierra.  Maléfica se convierte en la protectora más feroz de la tierra, pero finalmente sufre una traición despiadada, un acto que comienza a convertir su corazón en piedra. Empeñada en vengarse, Maléfica se enfrenta a una batalla épica con el sucesor del Rey invasor y, como resultado, maldice a su hija recién nacida, Aurora. A medida que la niña crece, Maléfica se da cuenta de que Aurora tiene la clave para la paz en el reino y también para la verdadera felicidad de Maléfica.', N'http://movies.disney.com/maleficent', 130, 3, 241, 1, 12, 98, 2, CAST(180000000.00 AS Numeric(18, 2)), CAST(758400000.00 AS Numeric(18, 2)), 1, 0)
GO
