INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (277, N'The Amazing Spider-Man 2', N'El Sorprendente Hombre Araña 2: La Amenaza de Electro', N'No más secretos.', CAST(N'2014-04-10' AS Date), N'Para Peter Parker, la vida es ocupada. Entre eliminar a los malos como Spider-Man y pasar tiempo con la persona que ama, Gwen Stacy, la graduación de la escuela secundaria no puede llegar lo suficientemente rápido. Peter no ha olvidado la promesa que le hizo al padre de Gwen de protegerla manteniéndose alejado, pero esa es una promesa que no puede cumplir. Las cosas cambiarán para Peter cuando surja un nuevo villano, Electro, un viejo amigo, Harry Osborn, regrese y Peter descubra nuevas pistas sobre su pasado.', N'http://www.theamazingspiderman.com', 135, 53, 241, 1, 4, 141, 4, CAST(255000000.00 AS Numeric(18, 2)), CAST(709000000.00 AS Numeric(18, 2)), 0, 0)
GO
