INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (287, N'Gravity', N'Gravedad', N'No dejes ir', CAST(N'2013-10-04' AS Date), N'La Dra. Ryan Stone, una brillante ingeniera médica en su primera misión en el Transbordador, con el veterano astronauta Matt Kowalsky al mando de su último vuelo antes de retirarse. Pero en una caminata espacial aparentemente rutinaria, ocurre un desastre. El Transbordador es destruido, dejando a Stone y Kowalsky completamente solos, atados a nada más que el uno al otro y girando en espiral hacia la oscuridad del espacio. El silencio ensordecedor les dice que han perdido cualquier vínculo con la Tierra y cualquier posibilidad de rescate. A medida que el miedo se convierte en pánico, cada bocanada de aire devora el poco oxígeno que queda. Pero el único camino a casa puede ser adentrarse más en la aterradora extensión del espacio.', N'http://gravitymovie.warnerbros.com/', 38, 47, 241, 1, 3, 91, 4, CAST(100000000.00 AS Numeric(18, 2)), CAST(723200000.00 AS Numeric(18, 2)), 10, 7)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (288, N'Man of Steel', N'El Hombre de Acero', N'Creerás que un hombre puede volar.', CAST(N'2013-06-14' AS Date), N'Un niño descubre que tiene poderes extraordinarios y que no es de esta tierra. Cuando era joven, viaja para descubrir de dónde vino y para qué fue enviado aquí. Pero el héroe que hay en él debe emerger si quiere salvar al mundo de la aniquilación y convertirse en el símbolo de esperanza para toda la humanidad.', N'http://www.manofsteel.com/', 76, 43, 241, 1, 4, 143, 4, CAST(225000000.00 AS Numeric(18, 2)), CAST(668000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (289, N'Thor: The Dark World', N'Thor: Un Mundo Oscuro', N'Profundizar en la oscuridad', CAST(N'2013-10-22' AS Date), N'Thor lucha para restaurar el orden en todo el cosmos... pero una antigua raza liderada por el vengativo Malekith regresa para sumergir el universo nuevamente en la oscuridad. Enfrentado a un enemigo que ni siquiera Odin y Asgard pueden resistir, Thor debe embarcarse en su viaje más peligroso y personal hasta el momento, uno que lo reunirá con Jane Foster y lo obligará a sacrificarlo todo para salvarnos a todos.', N'http://marvel.com/thor', 144, 53, 241, 1, 4, 112, 4, CAST(170000000.00 AS Numeric(18, 2)), CAST(644600000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (290, N'The Avengers', N'Los Vengadores', N'Se requiere algún ensamblaje.', CAST(N'2012-05-04' AS Date), N'Cuando surge un enemigo inesperado que amenaza la seguridad global, Nick Fury, director de la agencia internacional de mantenimiento de la paz conocida como S.H.I.E.L.D., se ve necesitado de un equipo para sacar al mundo del borde del desastre. ¡Comienza un atrevido esfuerzo de reclutamiento en todo el mundo!', N'http://marvel.com/avengers_movie/', 86, 53, 241, 1, 4, 143, 4, CAST(220000000.00 AS Numeric(18, 2)), CAST(1520000000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (291, N'Skyfall', N'Skyfall', N'Piensa en tus pecados.', CAST(N'2012-10-26' AS Date), N'Cuando la última misión de Bond sale gravemente mal y los agentes de todo el mundo quedan expuestos, el MI6 es atacado, lo que obliga a M a reubicar la agencia. Estos hechos hacen que su autoridad y posición sean desafiadas por Gareth Mallory, el nuevo presidente del Comité de Inteligencia y Seguridad. Con el MI6 ahora comprometido tanto por dentro como por fuera, M se queda con un aliado en el que puede confiar: Bond. 007 se adentra en las sombras, ayudado únicamente por la agente de campo Eve, siguiendo un rastro hasta el misterioso Silva, cuyos motivos letales y ocultos aún no se han revelado.', N'http://www.skyfall-movie.com', 61, 51, 240, 1, 9, 143, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(1109000000.00 AS Numeric(18, 2)), 5, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (292, N'The Dark Knight Rises', N'El Caballero de la Noche Asciende', N'La leyenda termina', CAST(N'2012-07-20' AS Date), N'Tras la muerte del fiscal de distrito Harvey Dent, Batman asume la responsabilidad de los crímenes de Dent para proteger la reputación del difunto abogado y posteriormente es perseguido por el Departamento de Policía de Gotham City. Ocho años después, Batman se encuentra con la misteriosa Selina Kyle y el villano Bane, un nuevo líder terrorista que abruma a los mejores de Gotham. El Caballero Oscuro resurge para proteger una ciudad que lo ha tildado de enemigo.', N'http://www.thedarkknightrises.com/', 27, 43, 241, 1, 4, 165, 4, CAST(230000000.00 AS Numeric(18, 2)), CAST(1085000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (293, N'The Hobbit: An Unexpected Journey', N'El Hobbit: Un Viaje Inesperado', N'Desde los comienzos más pequeños vienen las leyendas más grandes.', CAST(N'2012-12-14' AS Date), N'Bilbo Bolsón, un hobbit que disfruta de su vida tranquila, se ve arrastrado a una búsqueda épica por Gandalf el Gris y trece enanos que buscan recuperar su hogar en la montaña de manos de Smaug, el dragón.', N'http://www.thehobbit.com/', 12, 42, 167, 1, 12, 169, 4, CAST(200000000.00 AS Numeric(18, 2)), CAST(1021000000.00 AS Numeric(18, 2)), 3, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (294, N'Ice Age: Continental Drift', N'La Era de Hielo 4: La Deriva Continental', N'Manny, Diego y Sid se embarcan en otra aventura después de que su continente está a la deriva.', CAST(N'2012-06-27' AS Date), N'Manny, Diego y Sid se embarcan en otra aventura después de que su continente queda a la deriva. Usando un iceberg como barco, se encuentran con criaturas marinas y luchan contra piratas mientras exploran un mundo nuevo.', N'http://www.iceagemovies.com/films/ice-age-continental-drift', 149, 4, 241, 1, 11, 88, 1, CAST(95000000.00 AS Numeric(18, 2)), CAST(877200000.00 AS Numeric(18, 2)), 0, 0)
