GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (302, N'Pirates of the Caribbean: On Stranger Tides', N'Piratas del Caribe: Navegando Aguas Misteriosas', N'Vivir para siempre o morir intentando.', CAST(N'2011-05-20' AS Date), N'El Capitán Jack Sparrow se cruza con una mujer de su pasado, y no está seguro de si es amor o si ella es una estafadora despiadada que lo está utilizando para encontrar la legendaria Fuente de la Juventud. Cuando ella lo obliga a subir a bordo del Queen Anne''s Revenge, el barco del formidable pirata Barbanegra, Jack se encuentra en una aventura inesperada en la que no sabe a quién temer más: a Barbanegra o a la mujer de su pasado.', N'http://disney.go.com/pirates/index-on-stranger-tides.html#/video/', 153, 3, 241, 1, 8, 137, 4, CAST(378500000.00 AS Numeric(18, 2)), CAST(1046000000.00 AS Numeric(18, 2)), 0, 0)
GO
