INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (304, N'Mission: Impossible - Ghost Protocol', N'Misión: Imposible - Protocolo Fantasma', N'Ningún plan. Sin respaldo. Sin elección.', CAST(N'2011-12-16' AS Date), N'En la cuarta entrega de la serie Misión Imposible, Ethan Hunt (Cruise) y su equipo corren contra el tiempo para localizar a un peligroso terrorista llamado Hendricks (Nyqvist), que ha obtenido acceso a códigos de lanzamiento nucleares rusos y está planeando un ataque a la Estados Unidos. Un intento de detenerlo termina en una explosión que causa graves destrozos al Kremlin y al FMI al verse implicados en el bombardeo, lo que obliga al presidente a desautorizarlos. Al no contar con la ayuda del gobierno, Ethan y su equipo persiguen a Hendricks por todo el mundo, aunque quizás todavía sea demasiado tarde para detener un desastre.', N'http://www.missionimpossible.com/', 24, 126, 241, 1, 9, 133, 4, CAST(145000000.00 AS Numeric(18, 2)), CAST(694700000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (305, N'Kung Fu Panda 2', N'Kung Fu Panda 2', N'¡Prepárese para el año de la genialidad!', CAST(N'2011-05-26' AS Date), N'Po ahora está viviendo su sueño como El Guerrero Dragón, protegiendo el Valle de la Paz junto a sus amigos y compañeros maestros de kung fu, Los Cinco Furiosos: Tigresa, Grulla, Mantis, Víbora y Mono. Pero la nueva vida de genialidad de Po se ve amenazada por la aparición de un formidable villano, que planea utilizar un arma secreta e imparable para conquistar China y destruir el kung fu. Depende de Po y Los Cinco Furiosos viajar a través de China para enfrentar esta amenaza y vencerla. ¿Pero cómo puede Po detener un arma que puede detener el kung fu? Debe mirar a su pasado y descubrir los secretos de sus misteriosos orígenes; sólo entonces podrá desbloquear la fuerza que necesita para triunfar.', N'http://www.kungfupanda.com/', 154, 8, 241, 1, 11, 90, 2, CAST(150000000.00 AS Numeric(18, 2)), CAST(665700000.00 AS Numeric(18, 2)), 1, 0)
GO
