GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (307, N'The Hangover Part II', N'¿Qué Pasó Ayer? Parte 2', N'El Wolfpack está de vuelta', CAST(N'2011-05-26' AS Date), N'El equipo de Hangover se dirige a Tailandia para la boda de Stu. Después del desastre de una despedida de soltero en Las Vegas el año pasado, Stu va a lo seguro con un suave brunch previo a la boda. Sin embargo, nada sale según lo planeado y Bangkok es el escenario perfecto para otra aventura con el ruidoso grupo.', N'http://hangoverpart2.warnerbros.com/', 75, 43, 241, 1, 7, 102, 5, CAST(80000000.00 AS Numeric(18, 2)), CAST(586800000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (308, N'The Smurfs', N'Los Pitufos', N'Pitufo sucede.', CAST(N'2011-07-29' AS Date), N'Cuando el malvado mago Gargamel expulsa a los diminutos Pitufos azules de su aldea, ellos caen de su mundo mágico al nuestro; de hecho, justo en medio de Central Park. Con sólo tres manzanas de altura y atrapados en la Gran Manzana, los Pitufos deben encontrar una manera de regresar a su aldea antes de que Gargamel los localice.', N'http://www.smurfhappens.com/', 155, 127, 241, 1, 11, 103, 1, CAST(110000000.00 AS Numeric(18, 2)), CAST(563700000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (309, N'Cars 2', N'Cars 2', N'Ka-Ciao!', CAST(N'2011-06-24' AS Date), N'El auto de carreras estrella Rayo McQueen y su amigo Mater viajan al extranjero para competir en la carrera del Gran Premio Mundial. Pero el camino hacia el campeonato se vuelve difícil cuando Mater queda atrapado en su propia intrigante aventura: el espionaje internacional.', N'http://www.disney.go.com/cars/', 156, 10, 241, 1, 11, 106, 1, CAST(200000000.00 AS Numeric(18, 2)), CAST(559900000.00 AS Numeric(18, 2)), 0, 0)
GO
