INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (311, N'Alice in Wonderland', N'Alicia en el País de las Maravillas', N'Estás invitado a una fecha muy importante.', CAST(N'2010-02-25' AS Date), N'Alice, una joven de 19 años sin pretensiones e individual, está comprometida con un noble inglés tonto. En su fiesta de compromiso, se escapa de la multitud para considerar si seguir adelante con el matrimonio y cae por un agujero en el jardín después de ver un conejo inusual. Al llegar a un lugar extraño y surrealista llamado ''Underland'', se encuentra en un mundo que se asemeja a las pesadillas que tuvo cuando era niña, lleno de animales que hablan, reinas y caballeros malvados y bandersnatches frumosos. Alice se da cuenta de que está allí por una razón: conquistar al horrible Jabberwocky y restaurar a la legítima reina en su trono.', N'http://disney.go.com/wonderland/', 28, 3, 240, 1, 12, 108, 2, CAST(150000000.00 AS Numeric(18, 2)), CAST(1025000000.00 AS Numeric(18, 2)), 3, 2)
GO
