INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (314, N'Shrek Forever After', N'Shrek para Siempre', N'No es ogro ... hasta que es ogro', CAST(N'2010-05-21' AS Date), N'Un Shrek aburrido y domesticado hace pactos con el negociador Rumpelstiltskin para volver a sentirse como un verdadero ogro, pero cuando lo engañan y lo envían a una versión retorcida de Muy, muy lejos, donde Rumpelstiltskin es el rey, los ogros son cazados y él y Fiona Nunca se han conocido: se propone restaurar su mundo y reclamar su verdadero amor.', N'http://www.shrekforeverafter.com/', 158, 8, 241, 1, 11, 93, 1, CAST(135000000.00 AS Numeric(18, 2)), CAST(753000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (315, N'The Twilight Saga: Eclipse', N'La Saga Crepúsculo: Eclipse', N'Todo comienza ... con una elección.', CAST(N'2010-06-30' AS Date), N'Bella una vez más se encuentra rodeada de peligro mientras Seattle es devastada por una serie de misteriosos asesinatos y un vampiro malicioso continúa su búsqueda de venganza. En medio de todo esto, se ve obligada a elegir entre su amor por Edward y su amistad con Jacob, sabiendo que su decisión tiene el potencial de encender la eterna lucha entre vampiros y hombres lobo. Con su graduación acercándose rápidamente, Bella se enfrenta a la decisión más importante de su vida.', N'http://eclipsethemovie.com', 159, 125, 241, 1, 12, 123, 4, CAST(68000000.00 AS Numeric(18, 2)), CAST(698500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (316, N'Iron Man 2', N'Iron Man 2', N'No es la armadura lo que hace al héroe, sino al hombre dentro.', CAST(N'2010-05-07' AS Date), N'Ahora que el mundo es consciente de su doble vida como el superhéroe blindado Iron Man, el inventor multimillonario Tony Stark enfrenta presiones del gobierno, la prensa y el público para compartir su tecnología con el ejército. No dispuesto a abandonar su invento, Stark, con Pepper Potts y James ''Rhodey'' Rhodes a su lado, debe forjar nuevas alianzas y enfrentarse a enemigos poderosos.', N'http://www.ironmanmovie.com/', 160, 53, 241, 1, 4, 125, 4, CAST(200000000.00 AS Numeric(18, 2)), CAST(623900000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (317, N'Tangled', N'Enredados', N'Están llevando la aventura a nuevos longitudes.', CAST(N'2010-11-24' AS Date), N'Cuando el bandido más buscado y encantador del reino, Flynn Rider, se esconde en una torre misteriosa, Rapunzel, una hermosa y luchadora adolescente atada a una torre con 70 pies de cabello mágico y dorado, lo toma como rehén. El curioso captor de Flynn, que está buscando su billete para salir de la torre donde ha estado encerrada durante años, llega a un acuerdo con el apuesto ladrón y el improbable dúo emprende una escapada llena de acción, completa con un caballo súper policía, un un camaleón sobreprotector y una banda brusca de matones de pub.', N'http://disney.go.com/disneypictures/tangled/', 161, 3, 241, 1, 11, 100, 2, CAST(260000000.00 AS Numeric(18, 2)), CAST(591800000.00 AS Numeric(18, 2)), 1, 0)
GO
