INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (319, N'How to Train Your Dragon', N'Cómo Entrenar a Tu Dragón', N'Una aventura cambiará dos mundos', CAST(N'2010-03-26' AS Date), N'Como hijo de un líder vikingo en la cúspide de la edad adulta, el tímido Hipo Horrendo Abadejo III se enfrenta a un rito de iniciación: debe matar a un dragón para demostrar su temple guerrero. Pero después de derribar a un temido dragón, se da cuenta de que ya no quiere destruirlo y, en cambio, se hace amigo de la bestia, a la que llama Chimuelo, para disgusto de su padre guerrero.', N'http://www.howtotrainyourdragon.com/', 162, 8, 241, 1, 11, 98, 2, CAST(165000000.00 AS Numeric(18, 2)), CAST(494900000.00 AS Numeric(18, 2)), 2, 0)
GO
