INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (322, N'Ice Age: Dawn of the Dinosaurs', N'La Era de Hielo 3', N'¡No creerás tu hielo!', CAST(N'2009-07-01' AS Date), N'Los tiempos están cambiando para Manny, el malhumorado mamut, Sid, el perezoso con boca motora, y Diego, el astuto tigre dientes de sable. La vida se calienta para nuestros héroes cuando conocen a unos vecinos nuevos y no demasiado amigables: los poderosos dinosaurios.', N'http://www.iceagemovies.com/films/ice-age-dawn-of-the-dinosaurs', 163, 4, 241, 1, 11, 94, 1, CAST(90000000.00 AS Numeric(18, 2)), CAST(886700000.00 AS Numeric(18, 2)), 0, 0)
