INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (324, N'2012', N'2012', N'Nos advirtieron.', CAST(N'2009-11-13' AS Date), N'El Dr. Adrian Helmsley, parte de un equipo geofísico mundial que investiga el efecto en la Tierra de la radiación de tormentas solares sin precedentes, descubre que el núcleo de la Tierra se está calentando. Advierte al presidente estadounidense Thomas Wilson que la corteza terrestre se está volviendo inestable y que sin los preparativos adecuados para salvar a una fracción de la población mundial, toda la carrera está condenada al fracaso. Mientras tanto, el escritor Jackson Curtis tropieza con la misma información. Mientras los líderes del mundo se apresuran a construir "arcas" para escapar del cataclismo inminente, Curtis lucha por encontrar una manera de salvar a su familia. Mientras tanto, erupciones volcánicas y terremotos de una fuerza sin precedentes causan estragos en todo el mundo.', N'http://www.sonypictures.com/movies/2012', 42, 57, 241, 1, 25, 158, 4, CAST(200000000.00 AS Numeric(18, 2)), CAST(769700000.00 AS Numeric(18, 2)), 0, 0)
GO
