GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (326, N'The Twilight Saga: New Moon', N'La Saga Crepúsculo: Luna Nueva', N'Comienza el siguiente capítulo.', CAST(N'2009-11-20' AS Date), N'Bella Swan, residente de Forks, Washington, se está recuperando de la partida de su amor vampiro, Edward Cullen, y encuentra consuelo en su amistad con Jacob Black, un hombre lobo. Pero antes de que se dé cuenta, se ve envuelta en un conflicto de siglos de antigüedad, y su deseo de estar con Edward a cualquier precio la lleva a tomar riesgos cada vez mayores.', N'http://www.twilightthemovie.com/', 164, 125, 241, 1, 12, 130, 4, CAST(50000000.00 AS Numeric(18, 2)), CAST(709700000.00 AS Numeric(18, 2)), 0, 0)
