INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (329, N'The Hangover', N'¿Qué Pasó Ayer?', N'Algunos chicos simplemente no pueden manejar a Vegas.', CAST(N'2009-06-05' AS Date), N'Cuando tres amigos finalmente regresan en sí después de una estridente noche de juerga de despedida de soltero, encuentran un bebé en el armario y un tigre en el baño. Pero parece que no pueden localizar a su mejor amigo, Doug, quien se supone que se va a casar. Al iniciar una búsqueda frenética de Doug, el trío persevera a través de una desagradable resaca para tratar de llegar a tiempo a la iglesia.', N'http://hangoverpart2.warnerbros.com/dvd/', 75, 43, 241, 1, 7, 100, 5, CAST(35000000.00 AS Numeric(18, 2)), CAST(467500000.00 AS Numeric(18, 2)), 0, 0)
