INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (330, N'The Dark Knight', N'El Caballero de la Noche', N'¿Por qué tan serio?', CAST(N'2008-07-24' AS Date), N'Batman aumenta las apuestas en su guerra contra el crimen. Con la ayuda del teniente Jim Gordon y el fiscal de distrito Harvey Dent, Batman se propone desmantelar las organizaciones criminales restantes que asolan las calles. La asociación demuestra ser efectiva, pero pronto se encuentran presa de un reinado de caos desatado por un cerebro criminal en ascenso conocido por los aterrorizados ciudadanos de Gotham como el Joker.', N'http://thedarkknight.warnerbros.com/dvdsite/', 27, 43, 241, 1, 4, 152, 4, CAST(185000000.00 AS Numeric(18, 2)), CAST(1005000000.00 AS Numeric(18, 2)), 8, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (332, N'Kung Fu Panda', N'Kung Fu Panda', N'Prepárese para la genialidad.', CAST(N'2008-06-06' AS Date), N'Cuando el Valle de la Paz se ve amenazado, el perezoso Po el panda descubre su destino como "el elegido" y se entrena para convertirse en un héroe de kung fu, pero transformar al holgazán en un valiente guerrero no será fácil. Depende del Maestro Shifu y los Cinco Furiosos (Tigresa, Grulla, Mantis, Víbora y Mono) intentarlo.', N'http://www.kungfupanda.com/', 166, 8, 241, 1, 11, 92, 2, CAST(130000000.00 AS Numeric(18, 2)), CAST(631700000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (333, N'Hancock', N'Hancock', N'Mal comportamiento. Mala actitud. Héroe de verdad.', CAST(N'2008-07-02' AS Date), N'Hancock es un superhéroe decadente que se ve obligado a contratar a un experto en relaciones públicas para que le ayude a reparar su imagen cuando el público se cansa de todo el daño que ha infligido durante sus actos heroicos para salvar vidas. La idea del agente de encarcelar al antihéroe para que el mundo lo extrañe resulta exitosa, pero ¿Hancock se apegará a su nuevo sentido de propósito o volverá a caer en viejos hábitos?', N'http://www.sonypictures.com/movies/hancock/', 167, 128, 241, 1, 4, 92, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(624300000.00 AS Numeric(18, 2)), 0, 0)
GO
