INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (339, N'The Chronicles of Narnia: Prince Caspian', N'Las Crónicas de Narnia: El Príncipe Caspian', N'La esperanza tiene una cara nueva.', CAST(N'2008-05-16' AS Date), N'Un año después de sus increíbles aventuras en El León, la Bruja y el Armario, Peter, Edmund, Lucy y Susan Pevensie regresan a Narnia para ayudar a un joven príncipe cuya vida ha sido amenazada por el malvado rey Miraz. Ahora, con la ayuda de un colorido elenco de nuevos personajes, incluidos Trufflehunter el tejón y Nikabrik el enano, el clan Pevensie se embarca en una increíble búsqueda para garantizar que Narnia regrese a su legítimo heredero.', N'', 67, 3, 240, 1, 12, 150, 2, CAST(225000000.00 AS Numeric(18, 2)), CAST(419700000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (340, N'National Treasure: Book of Secrets', N'La Leyenda del Tesoro Perdido: El Libro de los Secretos', N'El mayor secreto de todos los tiempos.', CAST(N'2007-12-21' AS Date), NULL, NULL, 171, 17, 241, 1, 8, 124, 2, CAST(130000000.00 AS Numeric(18, 2)), CAST(457400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (341, N'Frost/Nixon', N'Frost/Nixon: La Entrevista del Escándalo', N'400 millones de personas esperaban la verdad.', CAST(N'2008-10-15' AS Date), N'Durante tres años después de haber sido obligado a dejar el cargo, Nixon permaneció en silencio. Pero en el verano de 1977, el férreo y astuto ex comandante en jefe accedió a asistir a una entrevista exhaustiva para afrontar las cuestiones de su mandato y el escándalo Watergate que puso fin a su presidencia. Nixon sorprendió a todos al seleccionar a Frost como su confesor televisivo, con la intención de superar fácilmente al alegre showman británico y asegurarse un lugar en los corazones y las mentes de los estadounidenses. Asimismo, el equipo de Frost albergaba dudas sobre la capacidad de su jefe para defenderse. Pero mientras las cámaras rodaban, se produjo una intensa batalla de ingenio.', N'', 40, 20, 241, 1, 2, 122, 5, CAST(25000000.00 AS Numeric(18, 2)), CAST(27400000.00 AS Numeric(18, 2)), 5, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (342, N'Ice Age: The Meltdown', N'La Era de Hielo 2', N'La edad de hielo se está derritiendo.', CAST(N'2006-03-31' AS Date), N'Diego, Manny y Sid regresan en esta secuela de la exitosa película animada Ice Age. Esta vez, la congelación ha terminado y la tierra cubierta de hielo está empezando a derretirse, lo que destruirá el preciado valle del trío. El desastre inminente los lleva a reunirse y advertir a todas las demás bestias sobre la desesperada situación.', N'http://www.iceagemovies.com/films/ice-age-the-meltdown', 163, 4, 241, 1, 11, 91, 1, CAST(80000000.00 AS Numeric(18, 2)), CAST(660900000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (343, N'Night at the Museum', N'Una Noche en el Museo', N'Donde la historia llega a la vida', CAST(N'2006-12-22' AS Date), N'El caos reina en el museo de historia natural cuando el vigilante nocturno Larry Daley accidentalmente provoca una antigua maldición, despertando a Atila el Huno, un ejército de gladiadores, un Tyrannosaurus rex y otras exhibiciones. Larry intenta desesperadamente mantener el museo bajo control, pero está librando una batalla perdida hasta que el presidente Teddy Roosevelt llega al rescate.', N'', 172, 28, 241, 1, 8, 108, 2, CAST(110000000.00 AS Numeric(18, 2)), CAST(574500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (344, N'Cars', N'Cars', N'Ahhh ... tiene ese nuevo olor a película.', CAST(N'2006-06-09' AS Date), N'Rayo McQueen, un auto de carreras novato y de gran éxito, descubre que la vida se trata del viaje, no de la línea de meta, cuando se encuentra inesperadamente desviado en la tranquila ciudad de Radiator Springs, en la Ruta 66. De camino a través del país hacia el gran Campeonato de la Copa Piston en California para competir contra dos profesionales experimentados, McQueen llega a conocer a los personajes poco convencionales de la ciudad.', N'http://disney.go.com/disneyvideos/animatedfilms/cars/', 156, 10, 241, 1, 11, 116, 2, CAST(120000000.00 AS Numeric(18, 2)), CAST(462000000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (345, N'Happy Feet', N'Happy Feet: El Pingüino', N'ADVERTENCIA: puede causar toe-tope.', CAST(N'2006-11-17' AS Date), N'En el mundo de los pingüinos emperadores, que encuentran a sus almas gemelas a través del canto, nace un pingüino que no sabe cantar. ¡Pero sabe bailar algo feroz!', N'http://www.warnerbros.com/happy-feet', 173, 49, 261, 1, 11, 108, 1, CAST(100000000.00 AS Numeric(18, 2)), CAST(384300000.00 AS Numeric(18, 2)), 1, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (346, N'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', N'Las Crónicas de Narnia: El León, La Bruja y El Ropero', N'El mal ha reinado durante 100 años ...', CAST(N'2005-12-08' AS Date), N'Los hermanos Lucy, Edmund, Susan y Peter atraviesan un guardarropa mágico y encuentran la tierra de Narnia. Allí, descubren un reino encantador, alguna vez pacífico, que ha sido sumido en un invierno eterno por la malvada Bruja Blanca, Jadis. Ayudados por el sabio y magnífico león Aslan, los niños llevan a Narnia a una espectacular y culminante batalla para liberarse para siempre de los poderes glaciales de la Bruja.', N'', 67, 63, 240, 1, 12, 145, 2, CAST(180000000.00 AS Numeric(18, 2)), CAST(745000000.00 AS Numeric(18, 2)), 3, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (347, N'Madagascar', N'Madagascar', N'Alguien tiene un zoológico suelto.', CAST(N'2005-05-27' AS Date), N'Los animales del zoológico abandonan las comodidades de los hábitats creados por el hombre para vivir aventuras exóticas en esta película familiar animada. Después de escapar del zoológico, cuatro amigos (un león, un hipopótamo, una cebra y una jirafa) son enviados de regreso a África. Cuando su barco naufraga, dejándolos varados en Madagascar, una isla poblada por criaturas locas, los amigos deben adaptarse a la vida en la jungla y a sus nuevos roles como animales salvajes.', N'', 151, 8, 241, 1, 11, 86, 1, CAST(75000000.00 AS Numeric(18, 2)), CAST(532700000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (348, N'Hitch', N'Hitch: Especialista en Seducción', N'La cura para el hombre común.', CAST(N'2005-02-11' AS Date), N'El entrenador de citas Alex ''Hitch'' Hitchens es el mentor de un cliente torpe, Albert, que espera ganarse el corazón de la glamorosa Allegra Cole. Mientras Albert progresa, Hitch se enfrenta a sus propios reveses románticos cuando las técnicas probadas no funcionan con Sara Melas, una reportera sensacionalista que investiga la vida amorosa de Allegra Cole. Cuando Sara descubre la conexión de Hitch con Albert (ahora novio de Allegra), amenaza con destruir ambas relaciones.', N'', 174, 130, 241, 1, 6, 118, 4, CAST(70000000.00 AS Numeric(18, 2)), CAST(368100000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (349, N'The Incredibles', N'Los Increíbles', N'Sin intestino, sin gloria', CAST(N'2004-11-05' AS Date), N'Bob Parr ha renunciado a sus días de superhéroe para trabajar como tasador de seguros y criar a sus tres hijos con su ex heroica esposa en los suburbios. Pero cuando recibe una misión misteriosa, es hora de volver a disfrazarse.', N'http://disney.go.com/disneyvideos/animatedfilms/incredibles/main.html', 24, 10, 241, 1, 11, 115, 1, CAST(92000000.00 AS Numeric(18, 2)), CAST(633000000.00 AS Numeric(18, 2)), 4, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (350, N'Meet the Fockers', N'La Familia de Mi Novio', N'La miseria ama a la familia.', CAST(N'2004-12-22' AS Date), N'Jack Byrnes, un ex-CIA difícil de descifrar, y su esposa, Dina, se dirigen a los climas más cálidos de Florida para conocer a su futuro yerno, los padres de Greg Focker. A diferencia de sus descendientes felizmente emparejados, los futuros suegros se encuentran en una situación de opuestos que definitivamente no se atraen.', N'http://www.meetthefockers.com/index.php', 175, 131, 241, 1, 7, 115, 4, CAST(80000000.00 AS Numeric(18, 2)), CAST(516000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (351, N'Shark Tale', N'El Espantatiburones', N'La historia de lo que sucede cuando un pequeño pez cuenta una gran mentira blanca ...', CAST(N'2004-10-01' AS Date), N'Oscar es un pez pequeño cuyas grandes aspiraciones a menudo le meten en problemas. Mientras tanto, Lenny es un gran tiburón blanco con un secreto sorprendente que ninguna criatura marina adivinaría: es vegetariano. Cuando una mentira convierte a Oscar en un héroe improbable y Lenny se convierte en un paria, los dos forman una amistad improbable.', N'', 176, 8, 241, 1, 11, 90, 1, CAST(75000000.00 AS Numeric(18, 2)), CAST(367300000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (352, N'Finding Nemo', N'Buscando a Nemo', N'Hay 3.7 billones de peces en el océano, están buscando uno.', CAST(N'2003-05-30' AS Date), N'Nemo, un joven y aventurero pez payaso, es llevado inesperadamente desde su casa en la Gran Barrera de Coral al acuario del consultorio de un dentista. Depende de su preocupante padre Marlin y de su amigable pero olvidadiza pez Dory traer a Nemo a casa, encontrándose con tiburones vegetarianos, tortugas surfistas, medusas hipnóticas, gaviotas hambrientas y más en el camino.', N'http://movies.disney.com/finding-nemo', 170, 10, 241, 1, 11, 100, 1, CAST(94000000.00 AS Numeric(18, 2)), CAST(940300000.00 AS Numeric(18, 2)), 4, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (353, N'Terminator 3: Rise of the Machines', N'Terminator 3: La Rebelión de las Máquinas', N'Las máquinas se elevarán.', CAST(N'2003-07-02' AS Date), N'Han pasado 10 años desde que John Connor salvó a la Tierra del Día del Juicio, y ahora vive bajo el radar, evitando usar cualquier cosa que Skynet pueda rastrear. Es decir, hasta que se encuentra con T-X, un robot asesino al que se le ordenó terminar lo que comenzó el T-1000. Lo bueno es que el antiguo enemigo de Connor, Terminator, ha regresado para ayudar al ahora adulto Connor... tal como lo prometió.', N'', 177, 132, 241, 1, 3, 109, 4, CAST(187300000.00 AS Numeric(18, 2)), CAST(433400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (354, N'Bad Boys II', N'Dos Policías Rebeldes 2', N'Si no puede soportar el calor, sal de Miami.', CAST(N'2003-07-18' AS Date), N'Marcus Burnett y Mike Lowrey, de la Fuerza de Tarea Antinarcóticos de Miami, están fuera de control y hablan basura y se reúnen, y las balas vuelan, los autos chocan y las risas estallan mientras persiguen a un narcotraficante desquiciado desde las calles de Miami hasta los barrios. de Cuba. Pero los verdaderos fuegos artificiales surgen cuando Marcus descubre que el playboy Mike está teniendo un romance en secreto con la sexy hermana de Marcus.', N'', 18, 17, 241, 1, 4, 147, 5, CAST(130000000.00 AS Numeric(18, 2)), CAST(273300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (355, N'Signs', N'Señales', N'No es como si no nos adviertan.', CAST(N'2002-08-02' AS Date), N'Una familia que vive en una granja encuentra misteriosos círculos en las cosechas en sus campos, lo que sugiere que algo más aterrador está por venir.', N'', 62, 7, 241, 1, 18, 107, 4, CAST(72000000.00 AS Numeric(18, 2)), CAST(408200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (356, N'Ice Age', N'La Era de Hielo', N'Ellos vinieron. Se descongelaron. Conquistaron.', CAST(N'2002-03-15' AS Date), N'Con la inminente edad de hielo casi sobre ellos, un trío disparejo de criaturas prehistóricas (Manny el mamut lanudo, Diego el tigre dientes de sable y Sid el perezoso gigante) encuentran a un bebé huérfano y deciden devolvérselo a sus padres humanos. En el camino, los improbables aliados se hacen amigos pero, cuando los enemigos atacan, su búsqueda adquiere objetivos mucho más nobles.', N'http://www.iceagemovies.com/films/ice-age', 163, 4, 241, 1, 11, 81, 1, CAST(59000000.00 AS Numeric(18, 2)), CAST(383300000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (357, N'My Big Fat Greek Wedding', N'Casarse... Está en Griego', N'El amor está aquí para quedarse ... también lo está su familia.', CAST(N'2002-04-19' AS Date), N'Una joven griega se enamora de un no griego y lucha por lograr que su familia lo acepte mientras ella acepta su herencia e identidad cultural.', N'', 184, 135, 262, 1, 7, 95, 2, CAST(5000000.00 AS Numeric(18, 2)), CAST(368700000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (358, N'The Mummy Returns', N'El Regreso de la Momia', N'La fuerza más poderosa en la tierra está a punto de ser desatada por las dos personas que deberían saber mejor.', CAST(N'2001-05-04' AS Date), N'Rick y Evelyn O''Connell, junto con su hijo Alex de 8 años, descubren la clave del poder del legendario Rey Escorpión, el legendario Brazalete de Anubis. Desafortunadamente, un Imhotep recién resucitado también tiene diseños en el brazalete y no duda en secuestrar a su nuevo portador, Alex, para hacerse con el control del ejército de otro mundo de Anubis.', N'', 186, 137, 241, 1, 8, 130, 3, CAST(98000000.00 AS Numeric(18, 2)), CAST(433000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (359, N'Jurassic Park III', N'Parque Jurásico III', N'¡Esta vez, no es solo un paseo por el parque!', CAST(N'2001-07-18' AS Date), N'Necesitado de fondos para la investigación, el Dr. Alan Grant acepta una gran suma de dinero para acompañar a Paul y Amanda Kirby en un recorrido aéreo por la infame Isla Sorna. No pasa mucho tiempo antes de que se desate el infierno y los caminantes varados deben luchar por sobrevivir mientras una gran cantidad de dinosaurios nuevos (y aún más mortales) intentan convertirlos en bocadillos.', N'', 187, 41, 241, 1, 8, 92, 2, CAST(93000000.00 AS Numeric(18, 2)), CAST(368800000.00 AS Numeric(18, 2)), 0, 0)
GO
