INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (361, N'What Women Want', N'Lo que Ellas Quieren', N'Tiene el poder de escuchar todo lo que las mujeres están pensando. Finalmente ... un hombre está escuchando.', CAST(N'2000-12-15' AS Date), N'El ejecutivo de publicidad Nick Marshall es tan engreído como parece, pero ¿qué le sucede a un tipo machista cuando de repente puede escuchar lo que piensan las mujeres? Nick es ignorado para un ascenso, pero después de que un accidente le permite escuchar los pensamientos de las mujeres, pone su nuevo talento a trabajar contra Darcy, su nuevo jefe, que parece estar enamorado de él.', N'', 188, 25, 241, 1, 7, 127, 3, CAST(70000000.00 AS Numeric(18, 2)), CAST(374111707.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (362, N'Dinosaur', N'Dinosaurio', N'Nunca has visto algo así.', CAST(N'2000-05-19' AS Date), N'Un dinosaurio huérfano criado por lémures se une a un arduo viaje hasta un santuario después de que una lluvia de meteoritos destruyera la casa de su familia.', N'', 189, 3, 241, 1, 11, 82, 2, CAST(127500000.00 AS Numeric(18, 2)), CAST(349800000.00 AS Numeric(18, 2)), 0, 0)
