INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (377, N'The Lost World: Jurassic Park', N'El Mundo Perdido: Parque Jurásico', N'Algo ha sobrevivido.', CAST(N'1997-05-23' AS Date), N'Cuatro años después de que los dinosaurios criados genéticamente de Jurassic Park se volvieran locos, el multimillonario John Hammond sorprende al teórico del caos Ian Malcolm al revelar que Hammond ha estado criando más bestias en un lugar secreto. Malcolm, su amada paleontóloga y un camarógrafo de vida silvestre se unen a una expedición para documentar el comportamiento natural de los letales lagartos en este thriller lleno de acción.', N'', 4, 41, 241, 1, 8, 129, 2, CAST(73000000.00 AS Numeric(18, 2)), CAST(618600000.00 AS Numeric(18, 2)), 1, 0)
