INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (396, N'The Mask', N'La Máscara', N'De cero a heroe.', CAST(N'1994-07-29' AS Date), N'Cuando el tímido empleado de banco Stanley Ipkiss descubre una máscara mágica que contiene el espíritu del dios nórdico Loki, toda su vida cambia. Mientras usa la máscara, Ipkiss se convierte en un playboy sobrenatural que rezuma encanto y confianza, lo que le permite llamar la atención de la cantante de un club nocturno local Tina Carlyle. Desafortunadamente, bajo la influencia de la máscara, Ipkiss también roba un banco, lo que enfurece al joven señor del crimen Dorian Tyrell, cuyos matones son culpados por el atraco.', N'', 202, 142, 241, 1, 7, 101, 2, CAST(23000000.00 AS Numeric(18, 2)), CAST(351600000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (397, N'Speed', N'Máxima Velocidad', N'Prepárate para la hora pico', CAST(N'1994-06-10' AS Date), N'El policía SWAT de Los Ángeles, Jack Traven, se enfrenta al experto en bombas Howard Payne, que busca un gran rescate. Primero, es un ascensor manipulado en un edificio muy alto. Entonces es un autobús manipulado: si reduce la velocidad, explotará, lo cual es bastante malo cualquier día, pero es una pesadilla en el tráfico de Los Ángeles. Y ese todavía no es el final.', N'', 198, 143, 241, 1, 4, 115, 5, CAST(30000000.00 AS Numeric(18, 2)), CAST(350400000.00 AS Numeric(18, 2)), 3, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (398, N'The Flintstones', N'Los Picapiedra', N'Yabba-Dabba-Doo!', CAST(N'1994-05-27' AS Date), N'La familia moderna de la Edad de Piedra, los Picapiedra, llega a la pantalla grande en esta versión de acción real del clásico dibujo animado. Fred ayuda a Barney a adoptar un niño. Barney ve una oportunidad para pagarle cuando Slate Mining pone a prueba a sus empleados para encontrar un nuevo ejecutivo. Pero ninguna buena acción queda impune.', N'', 208, 41, 241, 1, 7, 91, 1, CAST(46000000.00 AS Numeric(18, 2)), CAST(341600000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (399, N'Dumb and Dumber', N'Una Pareja de Idiotas', N'Lo que no tiene, el otro falta el otro.', CAST(N'1994-12-16' AS Date), N'Lloyd y Harry son dos hombres cuya estupidez es realmente indescriptible. Cuando Mary, una hermosa mujer, pierde una importante maleta con dinero antes de partir hacia Aspen, los dos amigos (que han encontrado la maleta) deciden devolvérsela. Después de algunas \"aventuras\" finalmente llegan a Aspen donde, usando el dinero perdido, viven y luchan por el corazón de Mary.', N'', 192, 144, 241, 1, 7, 107, 3, CAST(17000000.00 AS Numeric(18, 2)), CAST(247000000.00 AS Numeric(18, 2)), 0, 0)
GO
