INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (404, N'The Firm', N'La Firma', N'El poder puede ser asesinato para resistir.', CAST(N'1993-06-30' AS Date), N'Mitch McDeere es un joven con un futuro prometedor en el Derecho. A punto de rendir su examen de la abogacía, ''The Firm'' se le acerca y le hace una oferta que no rechaza. Seducido por el dinero y los regalos que le llueven, ignora por completo el lado más siniestro de su empresa. Luego, dos asociados son asesinados. El FBI contacta con él, le pide información y de repente su vida queda arruinada. Tiene una opción: trabajar con el FBI o quedarse en la Firma. De cualquier manera perderá la vida tal como la conoce. Mitch se da cuenta de que la única salida es seguir su propio plan...', N'', 210, 68, 241, 1, 9, 154, 5, CAST(42000000.00 AS Numeric(18, 2)), CAST(270248367.00 AS Numeric(18, 2)), 2, 0)
