GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (420, N'The Silence of the Lambs', N'El Silencio de los Inocentes', N'Para entrar en la mente de un asesino, debe desafiar la mente de un loco.', CAST(N'1991-02-14' AS Date), N'Clarice Starling, aprendiz del FBI, se aventura en un asilo de máxima seguridad para recoger el cerebro enfermo de Hannibal Lecter, un psiquiatra convertido en caníbal homicida. Starling necesita pistas que la ayuden a capturar a un asesino en serie. pero su relación fáustica con Lecter pronto lo lleva a escapar, y ahora dos asesinos trastornados andan sueltos.', N'', 213, 150, 241, 1, 9, 118, 6, CAST(19000000.00 AS Numeric(18, 2)), CAST(272700000.00 AS Numeric(18, 2)), 7, 5)
GO
