INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (422, N'The Addams Family', N'Los Locos Addams', N'Raro es relativo', CAST(N'1991-11-22' AS Date), N'El tío Fester lleva 25 años desaparecido. Un médico malvado lo descubre e introduce un Fester falso en un intento de conseguir el dinero de la familia Adams. La hija menor tiene algunas dudas sobre el nuevo tío Fester, pero el falso tío se adapta muy bien a la extraña familia. ¿Podrá la doctora llevar a cabo sus malvados planes y hacerse cargo de la fortuna de la familia Adams?', N'', 31, 151, 241, 1, 7, 99, 2, CAST(30000000.00 AS Numeric(18, 2)), CAST(191500000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (423, N'Cape Fear', N'Cabo de Miedo', N'No hay nada en la oscuridad que no esté allí a la luz. Excepto el miedo.', CAST(N'1991-11-13' AS Date), N'Sam Bowden es un abogado corporativo de una pequeña ciudad. Max Cady es un violador psicótico, tatuado, fumador de cigarros y que cita la Biblia. ¿Qué tienen en común? Hace catorce años, Sam era un defensor público asignado al juicio por violación de Max Cady y cometió un grave error: ocultó un documento a su cliente analfabeto que podría haberlo absuelto. Ahora, el astuto y bibliófilo Cady ha sido liberado y tiene la intención de enseñarle a Sam Bowden y su familia un par de cosas sobre la pérdida.', N'', 9, 41, 241, 1, 9, 128, 6, CAST(35000000.00 AS Numeric(18, 2)), CAST(182300000.00 AS Numeric(18, 2)), 2, 0)
GO
