INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (427, N'Home Alone', N'Mi Pobre Angelito', N'Una comedia familiar sin la familia.', CAST(N'1990-11-16' AS Date), N'Kevin McCallister, de ocho años, aprovecha al máximo la situación después de que su familia, sin saberlo, lo deja atrás cuando se van de vacaciones de Navidad. Pero cuando un par de ladrones torpes ponen sus miras en la casa de Kevin, el valiente niño está listo para defender su territorio. Al colocar muchas trampas explosivas, el adorable y travieso Kevin se mantiene firme mientras su frenética madre intenta correr a casa antes.', N'https://www.foxconnect.com/home-alone-4.html', 41, 148, 241, 1, 7, 102, 2, CAST(18000000.00 AS Numeric(18, 2)), CAST(476700000.00 AS Numeric(18, 2)), 2, 0)
GO
