INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (593, N'Patton', N'Patton', N'El guerrero rebelde', CAST(N'1970-04-02' AS Date), N'\"Patton\" cuenta la historia del general George S. Patton, famoso comandante de tanques de la Segunda Guerra Mundial. La película comienza con la carrera de Patton en el norte de África y avanza a través de la invasión de Alemania y la caída del Tercer Reich. Las tramas secundarias también hablan de los numerosos defectos de Patton, como su temperamento y su hábito de insubordinación.', N'', 285, 4, 241, 1, 19, 170, 2, CAST(12600000.00 AS Numeric(18, 2)), CAST(61800000.00 AS Numeric(18, 2)), 10, 7)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (598, N'Tora! Tora! Tora!', N'Tora! Tora! Tora!', N'El increíble ataque a Pearl Harbor.', CAST(N'1970-09-23' AS Date), N'En el verano de 1941, Estados Unidos y Japón parecen al borde de la guerra después de que los constantes embargos y la diplomacia fallida no tuvieran fin. \"¡Tora! ¡Tora! ¡Tora!\", que lleva el nombre de las palabras clave utilizadas por el piloto japonés principal para indicar que habían sorprendido a los estadounidenses, cubre los días previos al ataque a Pearl Harbor, que sumió a Estados Unidos en la Segunda Guerra Mundial. .', N'', 297, 4, 118, 1, 5, 144, 1, CAST(25500000.00 AS Numeric(18, 2)), CAST(29500000.00 AS Numeric(18, 2)), 5, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (600, N'Butch Cassidy and the Sundance Kid', N'Dos Hombres y un Destino', N'No es que importe, pero la mayor parte es cierto.', CAST(N'1969-10-24' AS Date), N'A finales de la década de 1890, en Wyoming, Butch Cassidy es el líder afable, inteligente y conversador de la banda forajida Hole in the Wall. Su compañero más cercano es el lacónico ''Sundance Kid''. A medida que Occidente se civiliza rápidamente, la ley finalmente alcanza a Butch, Sundance y su pandilla.  Perseguidos tenazmente por un grupo especial, los dos deciden viajar a Sudamérica con la esperanza de evadir a sus perseguidores de una vez por todas.', N'', 283, 4, 241, 1, 1, 110, 2, CAST(6000000.00 AS Numeric(18, 2)), CAST(102300000.00 AS Numeric(18, 2)), 7, 4)
GO
