INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (605, N'Paint Your Wagon', N'El Botín de los Valientes', N'¡Apuesta su reclamo a la Musical Goldmine del 69!', CAST(N'1969-10-15' AS Date), N'Un granjero de Michigan y un buscador de oro forman una sociedad en la región aurífera de California. Sus aventuras incluyen comprar y compartir una esposa, secuestrar un escenario, secuestrar a seis prostitutas y convertir su campamento minero en una ciudad en auge. A lo largo del camino se bebe mucho, se juega y se canta. Incluso encuentran tiempo para realizar una extracción de oro creativa.', N'', 300, 31, 241, 1, 20, 154, 2, CAST(20000000.00 AS Numeric(18, 2)), CAST(31678778.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (606, N'True Grit', N'Temple de Acero', N'El castigo viene de una forma u otra.', CAST(N'1969-06-11' AS Date), N'Tras el asesinato de su padre a manos de Tom Chaney, la granjera de 14 años Mattie Ross se propone capturar al asesino. Para ayudarla, contrata al mariscal estadounidense más duro que puede encontrar, un hombre con "verdadera determinación", Reuben J. "Rooster" Cogburn. Mattie insiste en acompañar a Cogburn, cuyo carácter bebedor, perezoso y generalmente reprobado no aumenta su fe en él. En contra de sus deseos, ella se une a él en su viaje hacia las Naciones Indias en busca de Chaney. A ellos se une el Texas Ranger LaBoeuf, que quiere a Chaney para sus propios fines. El improbable trío encuentra peligro y aventuras en el viaje, y cada uno pone a prueba su "valor".', N'http://www.truegritmovie.com/', 301, 2, 241, 1, 1, 128, 1, NULL, CAST(43700000.00 AS Numeric(18, 2)), 2, 1)
GO
