INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (665, N'The Longest Day', N'El Día Más Largo', N'Este es el día que cambió el mundo ... cuando la historia contuvo el aliento.', CAST(N'1962-09-25' AS Date), N'La nueva narración del 6 de junio de 1944 desde la perspectiva de los alemanes, estadounidenses, británicos, canadienses y los franceses libres. El mariscal Erwin Rommel, recorriendo las defensas que se están estableciendo como parte del Muro Atlántico del Reich, señala a sus oficiales que cuando llegue la invasión aliada deben ser detenidos en la playa. \"Tanto para los aliados como para los alemanes, será el día más largo\"', N'', 318, 4, 241, 1, 5, 178, 2, CAST(7750000.00 AS Numeric(18, 2)), CAST(50100000.00 AS Numeric(18, 2)), 5, 2)
