INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (767, N'Singin'' in the Rain', N'Cantando Bajo la Lluvia', N'¡Qué sensación tan gloriosa!', CAST(N'1952-04-11' AS Date), N'En el Hollywood de 1927, Don Lockwood y Lina Lamont son una famosa pareja romántica en pantalla en películas mudas, pero Lina confunde el romance en pantalla con el amor real. Cuando su última película se transforma en un musical, Don tiene la voz perfecta para las canciones, pero una voz estridente se enfrenta al estudio para doblar su voz. Traen a Kathy Selden, aspirante a actriz, y, mientras trabaja en la película, Don se enamora de ella.', N'', 340, 11, 241, 1, 20, 103, 1, CAST(2500000.00 AS Numeric(18, 2)), CAST(12400000.00 AS Numeric(18, 2)), 2, 0)
