INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1126, N'Inside Out', N'Intensamente', N'Conoce las pequeñas voces dentro de tu cabeza.', CAST(N'2015-06-19' AS Date), N'Crecer puede ser un camino lleno de obstáculos, y no es una excepción para Riley, quien es desarraigada de su vida en el Medio Oeste cuando su padre comienza un nuevo trabajo en San Francisco. Como todos nosotros, Riley se guía por sus emociones: alegría, miedo, ira, disgusto y tristeza. Las emociones viven en el Cuartel General, el centro de control dentro de la mente de Riley, donde la ayudan a asesorarla en la vida cotidiana. Mientras Riley y sus emociones luchan por adaptarse a una nueva vida en San Francisco, se produce un caos en la sede. Aunque Joy, la emoción principal y más importante de Riley, intenta mantener las cosas positivas, las emociones entran en conflicto sobre cuál es la mejor manera de navegar en una nueva ciudad, casa y escuela.', N'http://movies.disney.com/inside-out', 46, 10, 241, 1, 11, 94, 1, CAST(175000000.00 AS Numeric(18, 2)), CAST(857400000.00 AS Numeric(18, 2)), 2, 1)
GO
