INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1203, N'Romeo Must Die', N'Romeo Debe Morir', N'En la ciudad gobernada por delincuentes, dos familias han olvidado su miedo. Los hará recordar.', CAST(N'2000-03-22' AS Date), N'Dos familias de pandillas en guerra (una afroamericana y la otra china) maniobran para alardear de los derechos de los muelles de Oakland, California. Hang SIng y Trish O''Day descubren un rastro de engaño que deja muertas a la mayoría de las facciones en guerra... ¡o algo peor!', N'', 373, 52, 241, 1, 4, 115, 5, CAST(25000000.00 AS Numeric(18, 2)), CAST(91000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1204, N'The One', N'El Único', N'Robando el poder de los universos uno por uno.', CAST(N'2001-11-02' AS Date), N'Un ayudante del sheriff lucha contra una versión de sí mismo del universo alternativo que se vuelve más fuerte con cada yo alternativo que mata.', N'', 374, 19, 241, 1, 3, 87, 5, CAST(49000000.00 AS Numeric(18, 2)), CAST(72700000.00 AS Numeric(18, 2)), 0, 0)
