INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1205, N'Kiss of the Dragon', N'El Beso del Dragón', N'Beso de adiós de miedo', CAST(N'2001-07-06' AS Date), N'Liu Jian, un policía chino de élite, llega a París para arrestar a un narcotraficante chino. Cuando Jian es traicionado por un oficial francés y acusado de asesinato, debe esconderse y encontrar nuevos aliados.', N'', 375, 195, 79, 1, 4, 98, 6, CAST(25000000.00 AS Numeric(18, 2)), CAST(64400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1206, N'Cradle 2 the Grave', N'De la Cuna a la Tumba', N'Los enemigos mortales hacen amigos peligrosos.', CAST(N'2003-02-28' AS Date), N'Tony, el líder de la pandilla, lleva a cabo un importante atraco de diamantes con su equipo, pero Ling, el policía convertido en criminal, sabe quién tiene el botín y responde secuestrando a la hija de Tony y reteniéndola para pedir un rescate. Desafortunadamente, Tony también perdió los diamantes. Mientras busca frenéticamente a su hija y las joyas, Tony se une a un agente del gobierno que alguna vez trabajó con Ling y busca vengarse de él.', N'', 373, 52, 241, 1, 4, 101, 5, CAST(25000000.00 AS Numeric(18, 2)), CAST(56500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1207, N'Unleashed', N'Desatado', N'No sirva de maestro', CAST(N'2005-02-02' AS Date), N'Criado como esclavo, Danny está acostumbrado a luchar por su supervivencia. De hecho, su "maestro", Bart, lo considera una mascota y llega incluso a atarlo con un collar para poder ganar dinero en clubes de lucha, donde Danny es el principal contendiente. Cuando el equipo de Bart sufre un accidente automovilístico, Danny escapa y se encuentra con un afinador de pianos ciego y de buen corazón que lo acoge y usa la música para liberar el corazón del luchador, enterrado durante mucho tiempo.', N'http://www.universalstudiosentertainment.com/unleashed/', 376, 196, 79, 1, 17, 102, 6, CAST(45000000.00 AS Numeric(18, 2)), CAST(50900000.00 AS Numeric(18, 2)), 0, 0)
GO
