INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1211, N'The Forbidden Kingdom', N'El Reino Prohibido', N'La batalla por la eternidad es la fantasía de su vida.', CAST(N'2008-04-18' AS Date), N'Un adolescente estadounidense obsesionado con el cine de Hong Kong y los clásicos del kung-fu hace un descubrimiento extraordinario en una casa de empeño de Chinatown: el legendario arma de palo del sabio y guerrero chino, el Rey Mono. Con la reliquia perdida en la mano, el adolescente inesperadamente se encuentra viajando de regreso a la antigua China para unirse a un grupo de guerreros de la tradición de las artes marciales en una peligrosa búsqueda para liberar al Rey Mono encarcelado.', N'http://www.forbiddenkingdommovie.com/', 379, 128, 241, 1, 17, 104, 4, CAST(55000000.00 AS Numeric(18, 2)), CAST(128000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1212, N'The Mummy: Tomb of the Dragon Emperor', N'La Momia: La Tumba del Emperador Dragón', N'Un nuevo mal despierta.', CAST(N'2008-08-01' AS Date), N'El arqueólogo Rick O''Connell viaja a China y lo enfrenta a un emperador de la dinastía Han de 2000 años de antigüedad que ha regresado de entre los muertos para perseguir la dominación mundial. Esta vez, O''Connell solicita la ayuda de su esposa y su hijo para aplastar al llamado "Emperador Dragón" y su abuso de poder sobrenatural.', N'http://www.themummy.com/', 32, 128, 241, 1, 8, 111, 4, CAST(145000000.00 AS Numeric(18, 2)), CAST(401100000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1213, N'The Expendables', N'Los Indestructibles', N'Elije tu arma.', CAST(N'2010-08-03' AS Date), N'Barney Ross lidera una banda de mercenarios altamente cualificados, incluido el entusiasta de los cuchillos Lee Christmas, un experto en artes marciales, especialista en armas pesadas, demolicionista y un francotirador con cañón suelto. Cuando el misterioso Sr. Church encarga al grupo asesinar al dictador de una pequeña isla sudamericana, Barney y Lee visitan el lugar remoto para explorar a su oposición y descubrir la verdadera naturaleza del conflicto que envuelve a la ciudad.', N'http://expendablesthemovie.com/', 242, 80, 241, 1, 4, 103, 6, CAST(82000000.00 AS Numeric(18, 2)), CAST(274500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1214, N'The Expendables 2', N'Los Indestructibles 2', N'Volver para la guerra.', CAST(N'2012-08-13' AS Date), N'El Sr. Church reúne a los Mercenarios para obtener lo que debería ser un sueldo fácil, pero cuando uno de sus hombres es asesinado en el trabajo, su búsqueda de venganza los lleva a lo profundo del territorio enemigo y a enfrentarse a una amenaza inesperada.', N'http://theexpendables2film.com/', 380, 80, 241, 1, 4, 103, 5, CAST(100000000.00 AS Numeric(18, 2)), CAST(305400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1215, N'The Expendables 3', N'Los Indestructibles 3', N'Nuevo equipo. Nueva actitud. Nueva misión.', CAST(N'2014-08-04' AS Date), N'Barney, Christmas y el resto del equipo se encuentran cara a cara con Conrad Stonebanks, quien hace años cofundó The Expendables con Barney. Posteriormente, Stonebanks se convirtió en un traficante de armas despiadado y en alguien a quien Barney se vio obligado a matar... o eso pensaba. Stonebanks, que una vez eludió la muerte, ahora tiene como misión acabar con Los Indestructibles, pero Barney tiene otros planes. Barney decide que tiene que luchar contra sangre vieja con sangre nueva y trae una nueva era de miembros del equipo de Expendables, reclutando individuos que son más jóvenes, más rápidos y más conocedores de la tecnología. La última misión se convierte en un choque entre el estilo clásico de la vieja escuela y la experiencia en alta tecnología en la batalla más personal de los Expendables hasta el momento.', N'http://theexpendables3film.com/', 381, 80, 241, 1, 4, 126, 5, CAST(90000000.00 AS Numeric(18, 2)), CAST(206200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1216, N'The Incredible Hulk', N'El Increíble Hulk', N'Te gustará cuando esté enojado.', CAST(N'2008-06-08' AS Date), N'El científico Bruce Banner recorre el planeta en busca de un antídoto para la fuerza desenfrenada de ira que lleva dentro: Hulk. Pero cuando los cerebros militares que sueñan con explotar sus poderes lo obligan a regresar a la civilización, se encuentra cara a cara con un enemigo nuevo y mortal.', N'', 376, 53, 241, 1, 4, 112, 4, CAST(150000000.00 AS Numeric(18, 2)), CAST(263400000.00 AS Numeric(18, 2)), 0, 0)
GO
