GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1218, N'Clash of the Titans', N'Furia de Titanes', N'Los titanes chocarán.', CAST(N'2010-04-02' AS Date), N'Nacido de un dios pero criado como hombre, Perseo no puede salvar a su familia de Hades, el dios vengativo del inframundo. Sin nada que perder, Perseo se ofrece como voluntario para liderar una peligrosa misión para derrotar a Hades antes de que pueda arrebatarle el poder a Zeus y desatar el infierno en la tierra. Luchando contra demonios impíos y bestias temibles, Perseo y sus guerreros sólo sobrevivirán si Perseo acepta su poder como dios, desafía el destino y crea su propio destino.', N'http://www.clash-of-the-titans.com/', 376, 43, 241, 1, 8, 106, 4, CAST(125000000.00 AS Numeric(18, 2)), CAST(493200000.00 AS Numeric(18, 2)), 0, 0)
