GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1274, N'Battleship', N'Batalla Naval', N'La batalla por la tierra comienza en el mar', CAST(N'2012-04-03' AS Date), N'Cuando la humanidad envía una señal de radio al espacio, llega una respuesta del "Planeta G", en forma de varias naves extraterrestres que aterrizan en las aguas de Hawaii. El teniente Alex Hopper es un oficial de armas asignado al USS John Paul Jones, parte de una coalición naval internacional que se convierte en la última esperanza de supervivencia del mundo mientras se enfrentan a la fuerza alienígena hostil de una fuerza inimaginable. Mientras se enfrenta a los invasores, Hopper también debe intentar estar a la altura del potencial que su hermano y el padre de su prometida, el almirante Shane, esperan de él.', N'', 167, 210, 241, 1, 4, 131, 4, CAST(220000000.00 AS Numeric(18, 2)), CAST(303000000.00 AS Numeric(18, 2)), 0, 0)
GO
