INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1303, N'Taken', N'Búsqueda Implacable', N'Tomaron a su hija. Se llevará la vida.', CAST(N'2008-02-27' AS Date), N'Mientras estaba de vacaciones con una amiga en París, una niña estadounidense es secuestrada por una banda de traficantes de personas que intentan venderla para la prostitución forzada. Trabajando contrarreloj, su padre ex-espía debe hacer todo lo posible para salvarla. Pero con sus mejores años posiblemente detrás de él, el trabajo puede ser más de lo que puede manejar.', N'', 403, 196, 79, 1, 9, 90, 6, CAST(22000000.00 AS Numeric(18, 2)), CAST(226800000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1304, N'From Paris with Love', N'Desde París con Amor', N'Dos agentes. Una ciudad. No Merci.', CAST(N'2010-02-05' AS Date), N'James Reese tiene un buen trabajo como ayudante del embajador en Francia, pero su verdadera pasión es un trabajo paralelo, trabajando en un papel menor en la CIA. Le encantaría ser un agente de pleno derecho y no puede creer su suerte cuando consigue una misión con Charlie Wax. Charlie, que tiene el gatillo fácil, pronto hace que James llore por su trabajo de escritorio, pero cuando se entera de que los mismos tipos que están tratando de atrapar lo persiguen, James se da cuenta de que Charlie puede ser su única esperanza de supervivencia.', N'http://www.frompariswithlovefilm.com/', 403, 196, 79, 1, 9, 92, 5, CAST(52000000.00 AS Numeric(18, 2)), CAST(52800000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1305, N'The Gunman', N'Caza al Asesino', N'Armado con la verdad.', CAST(N'2015-03-20' AS Date), N'Ocho años después de huir del Congo tras el asesinato del ministro de minería de ese país, el ex asesino Jim Terrier está de regreso, sufriendo de trastorno de estrés postraumático y cavando pozos para expiar su pasado violento. Después de un atentado contra su vida, Terrier vuela a Londres para descubrir quién lo quiere muerto y por qué. La búsqueda de Terrier lo lleva a reencontrarse con Annie, una mujer que una vez amó y que ahora está casada con un aceitoso hombre de negocios con negocios en África.', N'', 403, 52, 241, 1, 9, 115, 5, CAST(40000000.00 AS Numeric(18, 2)), CAST(24200000.00 AS Numeric(18, 2)), 0, 0)
GO
