GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1327, N'The Best Exotic Marigold Hotel', N'El Exótico Hotel Marigold', N'Comparte el viaje. Compartir la risa.', CAST(N'2011-11-30' AS Date), N'Unos jubilados británicos viajan a la India para establecerse en lo que creen que es un hotel recién restaurado. Menos lujoso que sus anuncios, el Hotel Marigold poco a poco comienza a encantar de maneras inesperadas a medida que los residentes encuentran un nuevo propósito en su vejez.', N'http://www.foxsearchlight.com/thebestexoticmarigoldhotel/', 195, 225, 240, 1, 7, 124, 4, CAST(10000000.00 AS Numeric(18, 2)), CAST(136800000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1328, N'The Second Best Exotic Marigold Hotel', N'El Nuevo Exótico Hotel Marigold', NULL, CAST(N'2015-02-26' AS Date), N'Como al Best Exotic Marigold Hotel solo le queda una vacante, lo que plantea un problema de alojamiento para dos recién llegados, Sonny persigue su sueño expansionista de abrir un segundo hotel.', N'', 195, 225, 240, 1, 7, 122, 2, CAST(10000000.00 AS Numeric(18, 2)), CAST(86000000.00 AS Numeric(18, 2)), 0, 0)
