INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1329, N'John Carter', N'John Carter: Entre Dos Mundos', N'Perdido en nuestro mundo, encontrado en otro.', CAST(N'2012-03-07' AS Date), N'John Carter es un ex capitán militar cansado de la guerra que inexplicablemente es transportado al misterioso y exótico planeta de Barsoom (Marte) y, de mala gana, se ve envuelto en un conflicto épico. Es un mundo al borde del colapso, y Carter redescubre su humanidad cuando se da cuenta de que la supervivencia de Barsoom y su gente está en sus manos.', N'http://movies.disney.com/john-carter', 170, 3, 241, 1, 3, 132, 4, CAST(350000000.00 AS Numeric(18, 2)), CAST(284100000.00 AS Numeric(18, 2)), 0, 0)
