INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1330, N'Ironclad', N'Templario', N'Heavy Metal se vuelve medieval.', CAST(N'2011-03-04' AS Date), N'En el año 1215, los barones rebeldes de Inglaterra obligaron a su despreciado rey Juan a poner su sello real en la Carta Magna, un documento fundamental que defendía los derechos de los hombres libres. Sin embargo, a los pocos meses de comprometerse con la gran carta, el rey incumplió su palabra y reunió un ejército mercenario en la costa sur de Inglaterra con la intención de volver a poner a los barones y al país bajo su gobierno tiránico. Bloqueándole el paso se encontraba el poderoso castillo de Rochester, un lugar que se convertiría en el símbolo de la trascendental lucha de los rebeldes por la justicia y la libertad.', N'', 412, 226, 240, 1, 13, 121, 5, CAST(25000000.00 AS Numeric(18, 2)), NULL, 0, 0)
GO
