INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1335, N'28 Weeks Later', N'28 Semanas Después', N'Cuando los días pasan a semanas ... el horror regresa.', CAST(N'2007-04-26' AS Date), N'En esta escalofriante secuela de 28 días después, los habitantes de las Islas Británicas parecen haber perdido la batalla contra el ataque de la enfermedad, ya que el mortal virus de la ira ha matado a todos los ciudadanos allí. Seis meses después, un grupo de estadounidenses se atreve a poner un pie en las islas, convencidos de que el peligro ha ido y venido. Pero pronto queda muy claro que el flagelo continúa vivo, esperando abalanzarse sobre sus próximas víctimas.', N'', 415, 113, 240, 1, 10, 100, 6, CAST(15000000.00 AS Numeric(18, 2)), CAST(64200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1336, N'127 Hours', N'127 Horas', N'No hay fuerza más poderosa que la voluntad de vivir.', CAST(N'2010-09-04' AS Date), N'La historia real de la extraordinaria aventura del alpinista Aron Ralston para salvarse después de que una roca caída choca contra su brazo y lo atrapa en un cañón aislado en Utah.', N'', 108, 221, 240, 1, 19, 93, 5, CAST(18000000.00 AS Numeric(18, 2)), CAST(60700000.00 AS Numeric(18, 2)), 6, 0)
