INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1337, N'Trance', N'Trance', N'No seas un héroe.', CAST(N'2013-03-19' AS Date), N'Un subastador de bellas artes mezclado con una pandilla, une fuerzas con un hipnoterapeuta para recuperar un cuadro perdido. A medida que los límites entre el deseo, la realidad y la sugestión hipnótica comienzan a desdibujarse, lo que está en juego aumenta más rápido de lo que cualquiera podría haber anticipado.', N'', 108, 172, 240, 1, 14, 101, 5, CAST(20000000.00 AS Numeric(18, 2)), CAST(24300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1338, N'Steve Jobs', N'Steve Jobs', N'¿Puede un gran hombre ser un buen hombre?', CAST(N'2015-09-05' AS Date), N'Ambientado entre bastidores en tres lanzamientos de productos icónicos y finalizando en 1998 con la presentación del iMac, Steve Jobs nos lleva detrás de escena de la revolución digital para pintar un retrato íntimo del hombre brillante en su epicentro.', N'http://www.stevejobsthefilm.com', 108, 43, 241, 1, 19, 122, 5, CAST(30000000.00 AS Numeric(18, 2)), CAST(34400000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1339, N'Life of Pi', N'Una Aventura Extraordinaria', N'Cree lo increíble', CAST(N'2012-09-28' AS Date), N'La historia de un niño indio llamado Pi, hijo de un cuidador del zoológico, que se encuentra en compañía de una hiena, una cebra, un orangután y un tigre de Bengala después de que un naufragio los dejara a la deriva en el Océano Pacífico.', N'http://www.lifeofpimovie.com/', 8, 79, 241, 1, 8, 127, 2, CAST(120000000.00 AS Numeric(18, 2)), CAST(609000000.00 AS Numeric(18, 2)), 11, 4)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1340, N'Terminator Genisys', N'Terminator Génesis', N'Restablecer el futuro', CAST(N'2015-06-22' AS Date), N'Es el año 2029. John Connor, líder de la resistencia continúa la guerra contra las máquinas. Durante la ofensiva de Los Ángeles, los temores de John sobre un futuro desconocido comienzan a surgir cuando los espías de TECOM revelan un nuevo complot de SkyNet que lo atacará desde ambos frentes; pasado y futuro, y en última instancia cambiará la guerra para siempre.', N'http://www.terminatormovie.com/', 144, 2, 241, 1, 3, 126, 4, CAST(155000000.00 AS Numeric(18, 2)), CAST(440600000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1341, N'Maggie', N'Maggie', N'No te mordes', CAST(N'2015-04-22' AS Date), N'Hay una mortal epidemia de zombis que amenaza a la humanidad, pero Wade, un granjero y padre de familia de un pequeño pueblo, se niega a aceptar la derrota incluso cuando su hija Maggie se infecta. A medida que la condición de Maggie empeora y las autoridades buscan erradicar a quienes tienen el virus, Wade se ve llevado al límite en un esfuerzo por protegerla. Joely Richardson coprotagoniza este thriller post-apocalíptico.', N'http://www.maggiethefilm.com/', 416, 228, 241, 1, 10, 95, 5, CAST(4500000.00 AS Numeric(18, 2)), CAST(1400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1342, N'Sabotage', N'Sabotaje', N'No dejar cabos sueltos', CAST(N'2014-03-19' AS Date), N'En \"Sabotaje\", Arnold Schwarzenegger lidera un grupo de trabajo de élite de la DEA que se enfrenta a los cárteles de la droga más mortíferos del mundo. Cuando el equipo ejecuta con éxito una redada de alto riesgo en una casa segura de un cártel, creen que su trabajo está hecho, hasta que, uno por uno, los miembros del equipo comienzan a ser eliminados misteriosamente. A medida que aumenta el número de cadáveres, todos son sospechosos.', N'', 181, 229, 241, 1, 14, 109, 5, CAST(35000000.00 AS Numeric(18, 2)), CAST(18400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1343, N'Escape Plan', N'Plan de Escape', N'Nadie estalla sola.', CAST(N'2013-10-09' AS Date), N'Ray Breslin es la principal autoridad mundial en seguridad estructural. Después de analizar cada prisión de alta seguridad y aprender una amplia gama de habilidades de supervivencia para poder diseñar prisiones a prueba de fugas, sus habilidades se ponen a prueba. Está incriminado y encarcelado en una prisión maestra que él mismo diseñó. Necesita escapar y encontrar a la persona que lo puso tras las rejas.', N'http://escapeplanmovie.com/', 417, 108, 241, 1, 4, 115, 5, CAST(50000000.00 AS Numeric(18, 2)), CAST(137300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1344, N'The Last Stand', N'El Último Desafío', N'No en su ciudad. No bajo su reloj.', CAST(N'2013-01-18' AS Date), N'Ray Owens es el sheriff de la tranquila ciudad fronteriza estadounidense de Sommerton Junction después de dejar la policía de Los Ángeles tras una operación fallida. Tras su fuga del FBI, un famoso narcotraficante, su banda y un rehén se dirigen hacia Sommerton Junction, donde la policía se prepara para hacer una última resistencia para interceptarlos antes de que crucen la frontera. Owens se muestra reacio a involucrarse, pero finalmente se une a los esfuerzos de aplicación de la ley.', N'http://www.thelaststandfilm.com', 418, 46, 241, 1, 4, 107, 5, CAST(45000000.00 AS Numeric(18, 2)), CAST(48300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1345, N'Terminator Salvation', N'Terminator Salvación', N'El final comienza.', CAST(N'2009-05-21' AS Date), N'John Connor, adulto en el 2018 post-apocalíptico, debe liderar la resistencia de los humanos contra los robots militaristas cada vez más dominantes. Pero cuando aparece Marcus Wright, su existencia confunde la misión mientras Connor intenta determinar si Wright vino del futuro o del pasado, y si es amigo o enemigo.', N'https://www.warnerbros.com/terminator-salvation', 419, 5, 241, 1, 3, 115, 4, CAST(200000000.00 AS Numeric(18, 2)), CAST(371400000.00 AS Numeric(18, 2)), 0, 0)
GO
