GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1353, N'True Grit', N'Temple de Acero', N'El castigo viene de una forma u otra.', CAST(N'2010-12-22' AS Date), N'Tras el asesinato de su padre a manos de Tom Chaney, la granjera de 14 años Mattie Ross se propone capturar al asesino. Para ayudarla, contrata al mariscal estadounidense más duro que puede encontrar, un hombre con "verdadera determinación", Reuben J. "Rooster" Cogburn. Mattie insiste en acompañar a Cogburn, cuyo carácter bebedor, perezoso y generalmente reprobado no aumenta su fe en él. En contra de sus deseos, ella se une a él en su viaje hacia las Naciones Indias en busca de Chaney. A ellos se une el Texas Ranger LaBoeuf, que quiere a Chaney para sus propios fines. El improbable trío encuentra peligro y aventuras en el viaje, y cada uno pone a prueba su "valor".', N'http://www.truegritmovie.com/', 5, 2, 241, 1, 1, 110, 5, CAST(38000000.00 AS Numeric(18, 2)), CAST(252300000.00 AS Numeric(18, 2)), 10, 0)
GO
