INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1355, N'Predator', N'Depredador', N'Si sangra, lo podemos matar...', CAST(N'1987-06-12' AS Date), N'La CIA contrata a Dutch y su grupo de comandos para rescatar a aviadores caídos de las guerrillas en una jungla centroamericana. La misión va bien pero cuando regresan descubren que algo los está persiguiendo. Casi invisible, se mezcla con el bosque y toma trofeos de los cuerpos de sus víctimas a medida que avanza. De vez en cuando, al ver a través de sus ojos, el público ve que es un cazador de extraterrestres inteligente, que los caza por deporte y los mata uno a la vez.', N'', 58, 52, 241, 1, 3, 107, 6, CAST(18000000.00 AS Numeric(18, 2)), CAST(98300000.00 AS Numeric(18, 2)), 1, 0)
GO
