INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1357, N'Commando', N'Comando', N'En algún lugar ... de alguna manera ... alguien va a pagar.', CAST(N'1985-10-04' AS Date), N'John Matrix, el ex líder de un comando especial de ataque que siempre hacía los trabajos más duros, se ve obligado a volver a la acción cuando secuestran a su pequeña hija. Para encontrarla, Matrix tiene que abrirse camino a través de una serie de punks, asesinos, uno de sus antiguos comandos y un ejército privado totalmente equipado. Con la ayuda de una azafata luchadora y un viejo amigo, Matrix tiene sólo unas horas para superar su mayor desafío: encontrar a su hija antes de que la maten.', N'', 422, 52, 241, 1, 4, 90, 6, CAST(10000000.00 AS Numeric(18, 2)), CAST(57500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1358, N'X-Men: The Last Stand', N'X-Men: La Batalla Final', N'Tomar una posición', CAST(N'2006-05-25' AS Date), N'Cuando se encuentra una cura para tratar las mutaciones, se trazan líneas entre los X-Men y La Hermandad, una banda de poderosos mutantes organizados bajo el antiguo aliado de Xavier, Magneto.', N'', 57, 53, 241, 1, 4, 104, 4, CAST(210000000.00 AS Numeric(18, 2)), CAST(459400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1359, N'Red Sonja', N'Sonia la Roja', N'Una mujer y una guerrera que se convirtió en una leyenda.', CAST(N'1985-07-03' AS Date), N'El tirano Gedren busca el poder total en un mundo de barbarie. Asalta la ciudad de Hablac y mata al guardián de un talismán que le otorga un gran poder. Red Sonja, hermana del guardián, parte con su espada mágica para derrocar a Gedren.', N'', 297, 96, 269, 1, 12, 89, 5, CAST(17900000.00 AS Numeric(18, 2)), CAST(6900000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1360, N'Conan the Destroyer', N'Conan el Destructor', N'La leyenda más poderosa de todas está de vuelta en una nueva aventura.', CAST(N'1984-06-29' AS Date), N'Basada en un personaje creado por Robert E. Howard, esta trepidante y ocasionalmente divertida secuela de Conan el Bárbaro presenta al héroe (Arnold Schwarzenegger) mientras la malvada reina Taramis (Sarah Douglas) le encarga escoltar de forma segura a una princesa adolescente ( Olivia D''Abo) y su poderoso guardaespaldas (Wilt Chamberlain) a un castillo lejano para recuperar el mágico Cuerno de Dagón. Sin que Conan lo sepa, la reina planea sacrificar a la princesa cuando regrese y heredar su reino después de que el guardaespaldas mate a Conan. Los planes de la reina no tienen en cuenta la fuerza y ​​la astucia de Conan ni las habilidades de sus compañeros: el excéntrico mago Akiro (Mako), la mujer salvaje Zula (Grace Jones) y el inepto Malak (Tracey Walter). Juntos, el héroe y sus aliados deben derrotar a enemigos mortales y sobrenaturales en este viaje a la tierra de la espada y la brujería.', N'', 297, 96, 241, 1, 12, 101, 5, CAST(18000000.00 AS Numeric(18, 2)), CAST(100000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1361, N'Conan the Barbarian', N'Conan el Bárbaro', N'Ladrón. Guerrero. Gladiador. Rey.', CAST(N'1982-03-16' AS Date), N'Una adaptación cinematográfica del clásico héroe de espada y brujería, Conan el Bárbaro. Una horda de guerreros furiosos masacra a los padres del joven Conan y esclaviza al niño durante años en La Rueda del Dolor. Como único superviviente de la masacre infantil, Conan es liberado de la esclavitud y se le enseñan las antiguas artes de la lucha. Transformándose en una máquina de matar, Conan viaja al desierto para buscar venganza contra Thulsa Doom, el hombre responsable de matar a su familia. En el desierto, Conan se reúne con los ladrones Valeria y Subotai. El grupo se encuentra con el rey Osric, que quiere que el trío de guerreros ayude a rescatar a su hija, que se ha unido a Doom en las colinas.', N'', 423, 96, 241, 1, 12, 129, 5, CAST(16000000.00 AS Numeric(18, 2)), CAST(130000000.00 AS Numeric(18, 2)), 0, 0)
GO
