INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1388, N'Amistad', N'Amistad', N'La libertad no se da. Es nuestro derecho al nacer. Pero hay algunos momentos en los que debe tomarse.', CAST(N'1997-12-10' AS Date), N'En 1839, el barco negrero Amistad zarpó de Cuba hacia América. Durante el largo viaje, Cinque lidera a los esclavos en un levantamiento sin precedentes. Luego son retenidos prisioneros en Connecticut y su liberación se convierte en tema de acalorado debate. El esclavo liberado Theodore Joadson quiere que Cinque y los demás sean exonerados y contrata al abogado inmobiliario Roger Baldwin para que le ayude en su caso. Con el tiempo, John Quincy Adams también se convierte en un aliado.', N'', 4, 8, 241, 1, 13, 154, 5, CAST(36000000.00 AS Numeric(18, 2)), CAST(44200000.00 AS Numeric(18, 2)), 4, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1389, N'A.I. Artificial Intelligence', N'Inteligencia Artificial', N'David tiene 11 años. Pesa 60 libras. Tiene 4 pies, 6 pulgadas de alto. Él tiene cabello café. Su amor es real. Pero él no lo es.', CAST(N'2001-06-29' AS Date), N'David, un niño robótico, el primero programado para amar, es adoptado como caso de prueba por un empleado de Cybertronics y su esposa. Aunque poco a poco se convierte en su hijo, una serie de circunstancias inesperadas hacen que esta vida sea imposible para David. Sin la aceptación final por parte de humanos o máquinas, David se embarca en un viaje para descubrir a dónde pertenece realmente, descubriendo un mundo en el que la línea entre robot y máquina es vasta y profundamente delgada.', N'', 4, 41, 241, 1, 3, 146, 3, CAST(100000000.00 AS Numeric(18, 2)), CAST(235900000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1390, N'Catch Me If You Can', N'Atrápame si Puedes', N'La verdadera historia de una verdadera falsa.', CAST(N'2002-12-25' AS Date), N'Una historia real sobre Frank Abagnale Jr. quien, antes de cumplir 19 años, estafó con éxito cheques por valor de millones de dólares como piloto, médico y fiscal de Pan Am. Un agente del FBI tiene como misión ponerlo tras las rejas. Pero Frank no sólo elude la captura, sino que también disfruta de la persecución.', N'https://www.facebook.com/CatchMeIfYouCanMovie', 4, 41, 241, 1, 19, 141, 4, CAST(52000000.00 AS Numeric(18, 2)), CAST(352100000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1391, N'The Terminal', N'La Terminal', N'La vida está esperando.', CAST(N'2004-06-18' AS Date), N'Viktor Navorski es un hombre sin patria; su avión despegó justo cuando un golpe de estado explotó en su tierra natal, dejándola en ruinas, y ahora está varado en el aeropuerto Kennedy, donde sostiene un pasaporte que nadie reconoce. Mientras está en cuarentena en la sala de tránsito hasta que las autoridades puedan decidir qué hacer con él, Viktor simplemente sigue viviendo y corteja un romance con una hermosa azafata.', N'http://www.theterminal-themovie.com/', 4, 41, 241, 1, 7, 128, 4, CAST(60000000.00 AS Numeric(18, 2)), CAST(219400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1392, N'Lincoln', N'Lincoln', N'Con el coraje moral y la feroz determinación de tener éxito, sus elecciones cambiarán el destino de las generaciones venideras.', CAST(N'2012-10-08' AS Date), N'Un drama revelador que se centra en los tumultuosos últimos meses en el cargo del decimosexto presidente. En una nación dividida por la guerra y los fuertes vientos de cambio, Lincoln sigue un curso de acción diseñado para poner fin a la guerra, unir al país y abolir la esclavitud. Con el coraje moral y la feroz determinación de triunfar, sus decisiones durante este momento crítico cambiarán el destino de las generaciones venideras.', N'', 4, 41, 241, 1, 19, 150, 4, CAST(65000000.00 AS Numeric(18, 2)), CAST(275300000.00 AS Numeric(18, 2)), 12, 2)
GO
