INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1439, N'Space Cowboys', N'Cowboys del Espacio', N'El espacio nunca será el mismo.', CAST(N'2000-08-01' AS Date), N'Frank Corvin, ''Hawk'' Hawkins, Jerry O''Neill y ''Tank'' Sullivan fueron miembros del Proyecto Daedalus, el programa de pruebas de viajes espaciales de la Fuerza Aérea, pero sus esperanzas se desvanecieron en 1958 con la formación de la NASA y el uso de aviones capacitados. chimpancés. Chantajean para entrar en órbita cuando la órbita del misterioso satélite de comunicaciones ruso "Ikon" comienza a degradarse y amenaza con estrellarse contra la Tierra.', N'http://movies.warnerbros.com/spacecowboys/index.html', 10, 31, 241, 1, 9, 130, 2, CAST(60000000.00 AS Numeric(18, 2)), CAST(128900000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1440, N'Gran Torino', N'Gran Torino', N'¿Alguna vez te has encontrado con alguien con quien no deberías haberte metido?', CAST(N'2008-12-12' AS Date), N'Walt Kowalski es un viudo que se aferra a sus prejuicios a pesar de los cambios en su barrio de Michigan y el mundo que le rodea. Kowalski es un anciano gruñón, duro e infeliz que no se lleva bien ni con sus hijos ni con sus vecinos. Es un veterano de la Guerra de Corea cuya posesión más preciada es un Gran Torino de 1972 que mantiene en perfecto estado. Cuando su vecino Thao, un joven adolescente hmong presionado por su primo miembro de una pandilla, intenta robar su Gran Torino, Kowalski se propone reformar al joven. Atraído contra su voluntad a la vida de la familia de Thao, Kowalski pronto toma medidas para protegerlos de las pandillas que infestan su vecindario.', N'http://www.thegrantorino.com/', 10, 31, 241, 1, 2, 116, 5, CAST(33000000.00 AS Numeric(18, 2)), CAST(270000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1441, N'Invictus', N'Invictus', N'Su gente necesitaba un líder. Les dio un campeón.', CAST(N'2009-12-11' AS Date), N'El recién elegido presidente Nelson Mandela sabe que su nación sigue dividida racial y económicamente tras el apartheid. Creyendo que puede unir a su pueblo a través del lenguaje universal del deporte, Mandela reúne al equipo de rugby de Sudáfrica en su histórica carrera hacia el partido por el Campeonato Mundial de Rugby de 1995.', N'http://invictusmovie.warnerbros.com', 10, 31, 241, 1, 22, 133, 4, CAST(60000000.00 AS Numeric(18, 2)), CAST(122200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1442, N'American Sniper', N'Francotirador', N'El francotirador más letal en la historia de los Estados Unidos.', CAST(N'2014-11-11' AS Date), N'El SEAL de la Marina de los EE. UU., Chris Kyle, se toma en serio su única misión: proteger a sus camaradas y se convierte en uno de los francotiradores más letales de la historia de Estados Unidos. Su precisión milimétrica no sólo salva innumerables vidas sino que también lo convierte en un objetivo principal de los insurgentes. A pesar del grave peligro y de su lucha por ser un buen marido y padre para su familia en Estados Unidos, Kyle cumple cuatro períodos de servicio en Irak. Sin embargo, cuando finalmente regresa a casa, descubre que no puede dejar atrás la guerra.', N'http://www.americansnipermovie.com', 10, 49, 241, 1, 19, 132, 5, CAST(58800000.00 AS Numeric(18, 2)), CAST(547400000.00 AS Numeric(18, 2)), 6, 1)
GO
