INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1444, N'J. Edgar', N'J. Edgar', N'El hombre más poderoso del mundo.', CAST(N'2011-11-03' AS Date), N'Como rostro de las fuerzas del orden en Estados Unidos durante casi 50 años, J. Edgar Hoover fue temido, admirado, vilipendiado y reverenciado. Pero detrás de puertas cerradas guardaba secretos que habrían destruido su imagen, su carrera y su vida.', N'http://jedgarmovie.warnerbros.com/dvd/', 10, 20, 241, 1, 19, 137, 5, CAST(35000000.00 AS Numeric(18, 2)), CAST(84600000.00 AS Numeric(18, 2)), 0, 0)
