INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1446, N'Blade: Trinity', N'Blade: Trinity', N'Comienza la búsqueda final.', CAST(N'2004-12-08' AS Date), N'Durante años, Blade ha luchado contra los vampiros al amparo de la noche. Pero ahora, después de caer en el punto de mira del FBI, se ve obligado a salir a la luz del día, donde se ve obligado a unir fuerzas con un clan de cazadores de vampiros humanos que nunca supo que existía: los Nightstalkers. Junto con Abigail y Hannibal, dos Nightstalkers hábilmente entrenados, Blade sigue un rastro de sangre hasta la antigua criatura que también lo está cazando, el vampiro original, Drácula.', N'http://www.warnerbros.com/blade-trinity', 445, 53, 241, 1, 4, 113, 5, CAST(65000000.00 AS Numeric(18, 2)), CAST(128900000.00 AS Numeric(18, 2)), 0, 0)
