INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1452, N'The Long Riders', N'Los Asaltantes', N'\ A todo el mundo le gusta un forajido. Por alguna razón, los recuerdan. \ - Jesse James', CAST(N'1980-05-16' AS Date), N'Los orígenes, las hazañas y el destino final de la banda de James se cuentan en un simpático retrato de los ladrones de bancos formados por hermanos que inician sus legendarias redadas bancarias en busca de venganza.', N'', 250, 22, 241, 1, 1, 99, 6, CAST(8000000.00 AS Numeric(18, 2)), CAST(15795000.00 AS Numeric(18, 2)), 0, 0)
