INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1453, N'The Wild Bunch', N'La Pandilla Salvaje', N'Si solo quieres pasar dos horas en una sala de cine y volver a casa y olvidarlo, mantente alejado del grupo salvaje.', CAST(N'1969-06-18' AS Date), N'El anciano forajido Pike Bishop (William Holden) se prepara para retirarse después de un último robo. Junto a su pandilla, que incluye al holandés Engstrom (Ernest Borgnine) y los hermanos Lyle (Warren Oates) y Tector Gorch (Ben Johnson), Bishop descubre que el atraco es un montaje orquestado en parte por su antiguo socio, Deke Thornton (Robert Ryan). Mientras la pandilla restante se refugia en territorio mexicano, Thornton los sigue, lo que resulta en feroces tiroteos con muchas bajas.', N'', 448, 181, 241, 1, 1, 143, 6, CAST(6000000.00 AS Numeric(18, 2)), CAST(11138000.00 AS Numeric(18, 2)), 2, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1454, N'American History X', N'Historia Americana X', N'Algunos legados deben terminar.', CAST(N'1998-10-30' AS Date), N'Derek Vineyard obtiene la libertad condicional después de cumplir 3 años de prisión por matar a dos matones que intentaron entrar o robar su camioneta. A través de la narración de su hermano, Danny Vineyard, aprendemos que antes de ir a prisión, Derek era un skinhead y líder de una violenta pandilla supremacista blanca que cometió actos de crímenes raciales en todo Los Ángeles y sus acciones influyeron mucho en Danny. Reformado y recién salido de prisión, Derek corta el contacto con la pandilla y está decidido a evitar que Danny siga el mismo camino violento que él.', N'http://www.historyx.com/', 449, 14, 241, 1, 2, 119, 6, CAST(20000000.00 AS Numeric(18, 2)), CAST(23900000.00 AS Numeric(18, 2)), 1, 0)
GO
