INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1458, N'Straw Dogs', N'Perros de Paja', N'Todos tienen un punto de ruptura', CAST(N'1971-12-29' AS Date), N'El guionista de Los Ángeles, David Sumner, se muda con su esposa, Amy, a su ciudad natal en el sur profundo. Allí, mientras aumentan las tensiones entre ellos, un conflicto en ciernes con los lugareños se convierte en una amenaza para ambos.', N'http://www.strawdogsmovie.com/', 448, 244, 241, 1, 9, 117, 6, CAST(2200000.00 AS Numeric(18, 2)), CAST(8000000.00 AS Numeric(18, 2)), 1, 0)
