INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1459, N'Judgment at Nuremberg', N'El Juicio de Nuremberg', N'El evento que el mundo nunca olvidará', CAST(N'1961-12-19' AS Date), N'En 1947, cuatro jueces alemanes que ejercieron durante el régimen nazi se enfrentan a un tribunal militar para responder a cargos de crímenes contra la humanidad. El presidente del Tribunal Supremo, Haywood, escucha pruebas y testimonios no sólo del principal acusado, Ernst Janning, y su abogado defensor, Hans Rolfe, sino también de la viuda de un general nazi, un capitán idealista del ejército estadounidense y testigo reticente, Irene Wallner.', N'', 316, 22, 241, 1, 2, 179, 2, CAST(3000000.00 AS Numeric(18, 2)), CAST(10000000.00 AS Numeric(18, 2)), 11, 2)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1460, N'The Great Escape', N'La Gran Evasión', N'Pon una cerca frente a estos hombres ... ¡y la treparán!', CAST(N'1963-06-20' AS Date), N'Los nazis, exasperados por el número de fugas de sus campos de prisioneros por parte de un número relativamente pequeño de prisioneros aliados, los reubican en un campo de alta seguridad "a prueba de fugas" para que permanezcan fuera el resto de la guerra. Impertérritos, los prisioneros planean uno de los intentos de fuga más ambiciosos de la Segunda Guerra Mundial. Basado en una historia real.', N'', 331, 167, 241, 1, 5, 172, 2, CAST(3800000.00 AS Numeric(18, 2)), CAST(11744000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1461, N'Zulu', N'Zulu', NULL, CAST(N'1964-01-22' AS Date), N'Cuando era niño, Ali Neuman escapó por poco de ser asesinado por Inkhata, un partido político militante en guerra con el Congreso Nacional Africano de Nelson Mandela. Sólo él y su madre sobrevivieron a la carnicería de aquellos años. Pero como ocurre con muchos supervivientes, las cicatrices psicológicas persisten.', N'', 450, 2, 240, 1, 13, 139, 2, CAST(3500000.00 AS Numeric(18, 2)), CAST(8000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1462, N'Lucky Number Slevin', N'Misión: Siete', N'Tiempo inadecuado. Lugar equivocado. Número equivocado.', CAST(N'2006-02-24' AS Date), N'Slevin se encuentra por error en medio de una guerra personal entre los mayores jefes criminales de la ciudad. Bajo constante vigilancia, Slevin debe intentar no ser asesinado por un infame asesino y tener una idea de cómo salir de su dilema actual. Una película con muchas idas y venidas.', N'', 451, 11, 257, 1, 14, 110, 6, CAST(27000000.00 AS Numeric(18, 2)), CAST(56300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1463, N'Star Trek Beyond', N'Star Trek: Sin Límites', NULL, CAST(N'2016-07-07' AS Date), N'La tripulación del USS Enterprise explora los confines más lejanos del espacio inexplorado, donde se encuentran con un nuevo y misterioso enemigo que los pone a prueba y todo lo que representa la Federación.', N'http://www.startrekmovie.com/', 142, 126, 241, 1, 3, 122, 4, CAST(185000000.00 AS Numeric(18, 2)), CAST(343500000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1464, N'Star Trek Into Darkness', N'Star Trek: En la Oscuridad', N'La tierra caerá', CAST(N'2013-04-23' AS Date), N'Cuando la tripulación del Enterprise es llamada a regresar a casa, descubren que una fuerza terrorista imparable desde dentro de su propia organización ha detonado la flota y todo lo que representa, dejando nuestro mundo en un estado de crisis.  Con una cuenta personal que saldar, el Capitán Kirk lidera una búsqueda en un mundo en zona de guerra para capturar un arma de destrucción masiva de un solo hombre. Mientras nuestros héroes se ven impulsados ​​a un juego de ajedrez épico de vida o muerte, el amor será desafiado, las amistades se romperán y se deberán hacer sacrificios por la única familia que le queda a Kirk: su tripulación.', N'', 44, 126, 241, 1, 3, 133, 3, CAST(185000000.00 AS Numeric(18, 2)), CAST(467400000.00 AS Numeric(18, 2)), 1, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1465, N'Star Trek', N'Star Trek', N'Comienza el futuro.', CAST(N'2009-04-07' AS Date), N'El destino de la galaxia está en manos de acérrimos rivales. Uno de ellos, James Kirk, es un granjero de Iowa delincuente y en busca de emociones fuertes. El otro, Spock, un vulcano, se crió en una sociedad basada en la lógica que rechaza toda emoción. Mientras el instinto ardiente choca con la razón tranquila, su improbable pero poderosa asociación es lo único capaz de guiar a su tripulación a través de peligros inimaginables, yendo con valentía a donde nadie ha ido antes. La aventura humana ha comenzado de nuevo.', N'', 44, 126, 241, 1, 3, 127, 3, CAST(150000000.00 AS Numeric(18, 2)), CAST(385700000.00 AS Numeric(18, 2)), 4, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1466, N'RoboCop', N'RoboCop', N'Tenemos el futuro bajo control.', CAST(N'1987-07-17' AS Date), N'En RoboCop, el año es 2028 y el conglomerado multinacional OmniCorp está en el centro de la tecnología robótica.  En el extranjero, sus drones han sido utilizados por el ejército durante años, pero en Estados Unidos están prohibidos para las fuerzas del orden.  Ahora OmniCorp quiere llevar su controvertida tecnología al frente interno y ve una oportunidad de oro para hacerlo.  Cuando Alex Murphy, un amoroso esposo, padre y buen policía que hace todo lo posible para detener la ola de crimen y corrupción en Detroit, resulta gravemente herido, OmniCorp ve la oportunidad de construir un oficial de policía mitad hombre y mitad robot.  OmniCorp imagina un RoboCop en cada ciudad y aún más miles de millones para sus accionistas, pero nunca contaron con una cosa: todavía hay un hombre dentro de la máquina.', N'http://www.robocop.com', 72, 151, 241, 1, 3, 101, 6, CAST(13000000.00 AS Numeric(18, 2)), CAST(53400000.00 AS Numeric(18, 2)), 2, 0)
GO
