INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1485, N'Hugo', N'Hugo', N'Uno de los directores más legendarios de nuestro tiempo lo lleva a una aventura extraordinaria.', CAST(N'2011-10-10' AS Date), N'Hugo es un niño huérfano que vive entre los muros de una estación de tren en el París de los años 30. Aprendió a arreglar relojes y otros aparatos de su padre y su tío, que utiliza para mantener en funcionamiento los relojes de la estación de tren. Lo único que le queda que lo conecta con su padre muerto es un autómata (hombre mecánico) que no funciona sin una llave especial que Hugo necesita encontrar para desbloquear el secreto que cree que contiene. En sus aventuras, conoce a un comerciante, George Méliès, que trabaja en la estación de tren, y a su ahijada, que busca aventuras. Hugo descubre que tienen una conexión sorprendente con su padre y el autómata, y descubre que esto desbloquea algunos recuerdos que el anciano ha enterrado en su interior con respecto a su pasado.', N'http://www.hugomovie.com/', 9, 2, 240, 1, 8, 126, 1, CAST(170000000.00 AS Numeric(18, 2)), CAST(185800000.00 AS Numeric(18, 2)), 11, 5)
GO
