INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1493, N'Mad Max: Fury Road', N'Mad Max: Furia en el Camino', N'Que hermoso día.', CAST(N'2015-05-07' AS Date), N'Una historia apocalíptica ambientada en los confines de nuestro planeta, en un paisaje desértico y desolado donde la humanidad está destrozada y casi todo el mundo está enloquecido luchando por las necesidades de la vida. Dentro de este mundo existen dos rebeldes huyendo que podrían restaurar el orden. Está Max, un hombre de acción y de pocas palabras, que busca tranquilidad tras la pérdida de su esposa y su hijo a raíz del caos. Y Furiosa, una mujer de acción y una mujer que cree que su camino hacia la supervivencia puede lograrse si logra cruzar el desierto de regreso a la tierra natal de su infancia.', N'http://www.madmaxmovie.com/', 173, 154, 261, 1, 4, 120, 5, CAST(150000000.00 AS Numeric(18, 2)), CAST(378400000.00 AS Numeric(18, 2)), 10, 6)
GO
