INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1515, N'The Replacement Killers', N'Asesinos de Reemplazo', N'Matar o ser reemplazado.', CAST(N'1998-02-06' AS Date), N'El jefe criminal de Chinatown, Terence Wei, le pide al asesino a sueldo John Lee que asesine al joven hijo del policía Stan Zedkov. Lee tiene al niño en la mira, pero su conciencia se apodera de él y le perdona la vida. Temeroso de que Wei se vengue de su familia en China, Lee busca a la experta falsificadora Meg Coburn para obtener el pasaporte que necesita para salir del país, pero pronto una banda de asesinos sustitutos le sigue la pista.', N'', 440, 5, 241, 1, 9, 87, 6, CAST(30000000.00 AS Numeric(18, 2)), CAST(19200000.00 AS Numeric(18, 2)), 0, 0)
