INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1517, N'Tears of the Sun', N'Lágrimas del Sol', N'Fue entrenado para seguir órdenes. Se convirtió en un héroe desafiándolos.', CAST(N'2003-03-07' AS Date), N'El teniente de los Navy SEAL A.K. Waters y su escuadrón de élite de especialistas tácticos se ven obligados a elegir entre su deber y su humanidad, entre seguir órdenes ignorando el conflicto que los rodea o encontrar el coraje para seguir su conciencia y proteger a un grupo de refugiados inocentes. Cuando el gobierno democrático de Nigeria colapsa y el país es tomado por un despiadado dictador militar, Waters, un veterano ferozmente leal y endurecido es enviado en una misión de rutina para recuperar a un médico de Médicos Sin Fronteras.', N'', 440, 19, 241, 1, 5, 121, 5, CAST(75000000.00 AS Numeric(18, 2)), CAST(86500000.00 AS Numeric(18, 2)), 0, 0)
GO
