INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1519, N'Shooter', N'Francotirador', N'Ayer fue sobre honor. Hoy se trata de justicia.', CAST(N'2007-03-23' AS Date), N'Un tirador que vive en el exilio es convencido de volver a la acción después de enterarse de un complot para matar al presidente. Al final, traicionado e incriminado por el intento, huye para rastrear al verdadero asesino y descubrir quién exactamente le tendió una trampa y por qué.', N'http://www.shootermovie.com/', 440, 46, 241, 1, 4, 125, 5, CAST(61000000.00 AS Numeric(18, 2)), CAST(95700000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1520, N'Olympus Has Fallen', N'Olimpo Bajo Fuego', N'Cuando nuestra bandera caiga, nuestra nación se elevará.', CAST(N'2013-03-20' AS Date), N'Cuando la Casa Blanca (Código del Servicio Secreto: \"Olympus\") es capturada por un cerebro terrorista y el presidente es secuestrado, el ex guardia presidencial caído en desgracia Mike Banning se encuentra atrapado dentro del edificio. Mientras el equipo de seguridad nacional se apresura a responder, se ven obligados a confiar en el conocimiento interno de Banning para ayudar a retomar la Casa Blanca, salvar al presidente y evitar un desastre aún mayor.', N'', 440, 80, 241, 1, 4, 119, 5, CAST(70000000.00 AS Numeric(18, 2)), CAST(161000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1521, N'The Equalizer', N'El Justiciero', N'¿Qué ves cuando me miras?', CAST(N'2014-09-07' AS Date), N'En The Equalizer, Denzel Washington interpreta a McCall, un hombre que cree haber dejado atrás su misterioso pasado y se ha dedicado a comenzar una vida nueva y tranquila. Pero cuando McCall conoce a Teri (Chloë Grace Moretz), una joven bajo el control de gánsteres rusos ultraviolentos, no puede quedarse de brazos cruzados: tiene que ayudarla. Armado con habilidades ocultas que le permiten vengarse de cualquiera que brutalice a los indefensos, McCall sale de su retiro autoimpuesto y descubre que su deseo de justicia ha vuelto a despertar. Si alguien tiene un problema, si las probabilidades están en su contra, si no tiene a quién acudir, McCall lo ayudará. Él es El Igualador.', N'', 440, 49, 241, 1, 9, 132, 5, CAST(55000000.00 AS Numeric(18, 2)), CAST(192300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1522, N'Southpaw', N'Revancha', N'Cree en la esperanza.', CAST(N'2015-06-15' AS Date), N'Billy \"The Great\" Hope, el actual campeón de boxeo de peso mediano junior, tiene una carrera impresionante, una esposa e hija amorosas y un estilo de vida lujoso. Sin embargo, cuando ocurre la tragedia, Billy toca fondo y pierde a su familia, su casa y a su manager. Pronto encuentra un improbable salvador en Tick Willis, un ex peleador que entrena a los boxeadores aficionados más duros de la ciudad. Con su futuro en juego, Hope lucha por recuperar la confianza de aquellos a quienes más ama.', N'', 440, 251, 241, 1, 2, 123, 5, CAST(30000000.00 AS Numeric(18, 2)), CAST(92000000.00 AS Numeric(18, 2)), 0, 0)
GO
