INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1524, N'Mars Attacks!', N'¡Marcianos al Ataque!', N'Buen planeta. ¡Lo tomaremos!', CAST(N'1996-12-13' AS Date), N'Venimos en paz» no es lo que quieren decir esos hombres verdes de Marte cuando invaden nuestro planeta, armados con armas irresistibles y un cruel sentido del humor.  Este elenco repleto de estrellas debe ser víctima de la diversión y los juegos de los extraterrestres en esta comedia homenaje a las películas de ciencia ficción de los años 50 y 60.', N'http://marsattacks.warnerbros.com/', 28, 236, 241, 1, 3, 106, 3, CAST(70000000.00 AS Numeric(18, 2)), CAST(101400000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1525, N'Planet of the Apes', N'El Planeta de los Simios', N'Lamentarás que alguna vez hayas nacido humano', CAST(N'2001-07-27' AS Date), N'Después de un espectacular aterrizaje forzoso en un planeta inexplorado, el atrevido astronauta Leo Davidson se encuentra atrapado en un mundo salvaje donde los simios parlantes dominan a la raza humana. Desesperado por encontrar el camino a casa, Leo debe evadir al invencible ejército de gorilas liderado por el despiadado general Thade.', N'', 28, 73, 241, 1, 3, 120, 3, CAST(100000000.00 AS Numeric(18, 2)), CAST(362200000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1526, N'Big Fish', N'El Gran Pez', N'Una aventura tan grande como la vida misma.', CAST(N'2003-12-10' AS Date), N'A lo largo de su vida, Edward Bloom siempre ha sido un hombre de grandes apetitos, enormes pasiones y cuentos fantásticos. En sus últimos años, sigue siendo un gran misterio para su hijo, William. Ahora, para conocer al verdadero hombre, Will comienza a reconstruir una imagen real de su padre a partir de flashbacks de sus increíbles aventuras.', N'', 28, 73, 241, 1, 12, 125, 2, CAST(70000000.00 AS Numeric(18, 2)), CAST(122900000.00 AS Numeric(18, 2)), 1, 0)
GO
