INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1528, N'Watchmen', N'Los Vigilantes', N'La justicia viene a todos nosotros. No importa lo que hacemos.', CAST(N'2009-02-23' AS Date), N'En un 1985 descarnado y alternativo, los días de gloria de los vigilantes disfrazados llegan a su fin gracias a una ofensiva gubernamental, pero después de que uno de los veteranos enmascarados es brutalmente asesinado, se inicia una investigación sobre el asesino. Los héroes reunidos se proponen evitar su propia destrucción, pero al hacerlo descubren un siniestro complot que pone a toda la humanidad en grave peligro.', N'https://www.warnerbros.com/watchmen', 76, 43, 241, 1, 4, 163, 6, CAST(130000000.00 AS Numeric(18, 2)), CAST(185300000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1529, N'Man of Steel', N'El Hombre de Acero', N'Creerás que un hombre puede volar.', CAST(N'2013-06-10' AS Date), N'Un niño descubre que tiene poderes extraordinarios y que no es de esta tierra. Cuando era joven, viaja para descubrir de dónde vino y para qué fue enviado aquí. Pero el héroe que hay en él debe emerger si quiere salvar al mundo de la aniquilación y convertirse en el símbolo de esperanza para toda la humanidad.', N'http://www.manofsteel.com/', 76, 43, 241, 1, 4, 143, 4, CAST(225000000.00 AS Numeric(18, 2)), CAST(668000000.00 AS Numeric(18, 2)), 0, 0)
