INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1629, N'Mr. Holland''s Opus', N'Mr. Holland: Opus', N'De todas las vidas que cambió, la que más cambió fue la suya.', CAST(N'1995-12-29' AS Date), N'En 1965, el apasionado músico Glenn Holland acepta un trabajo como profesor de música en una escuela secundaria, convencido de que es sólo un pequeño obstáculo en el camino hacia su verdadera vocación: escribir una obra histórica. A medida que pasan las décadas con la composición no escrita pero generaciones de estudiantes inspiradas a través de su enseñanza, Holland debe redefinir el propósito de su vida.', N'', 200, 104, 241, 1, 2, 143, 2, CAST(31000000.00 AS Numeric(18, 2)), CAST(106269000.00 AS Numeric(18, 2)), 1, 0)
