GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1635, N'21 Jump Street', N'Comando Especial', N'Pensaron que las calles eran malas. Luego volvieron a la escuela secundaria.', CAST(N'2012-03-16' AS Date), N'En la escuela secundaria, Schmidt era un idiota y Jenko era el deportista popular. Después de graduarse, ambos se unieron a la policía y terminaron como compañeros andando en bicicleta en el parque de la ciudad. Como son jóvenes y parecen estudiantes de secundaria, se les asigna una unidad encubierta para infiltrarse en una red de narcotraficantes que suministra drogas sintéticas a los estudiantes de secundaria.', N'http://www.21jumpstreet-movie.com/', 497, 128, 241, 1, 7, 109, 5, CAST(55000000.00 AS Numeric(18, 2)), CAST(201500000.00 AS Numeric(18, 2)), 0, 0)
