INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1636, N'Cloudy with a Chance of Meatballs', N'Lluvia de Hamburguesas', N'Prepárese para servir.', CAST(N'2009-09-18' AS Date), N'El inventor Flint Lockwood crea una máquina que hace llover comida en las nubes, lo que permite a los ciudadanos desfavorecidos de Chewandswallow alimentarse por sí mismos. Pero cuando la caída de alimentos alcanza proporciones gigantescas, Flint debe luchar para evitar el desastre. ¿Podrá recuperar el control de la máquina y poner fin al mal tiempo antes de que la ciudad sea destruida?', N'http://www.cloudywithachanceofmeatballs.com/', 497, 127, 241, 1, 11, 90, 1, CAST(100000000.00 AS Numeric(18, 2)), CAST(243000000.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1637, N'Anastasia', N'Anastasia', N'Descubra la aventura detrás del mayor misterio de nuestro tiempo.', CAST(N'1956-12-13' AS Date), N'Esta aventura animada vuelve a contar la historia de la hija perdida del último zar de Rusia. El malvado Rasputín lanza una maldición sobre la familia Romanov, y Anastasia y su abuela, la emperatriz María, se separan. Después de crecer en un orfanato, Anastasia se encuentra con dos hombres rusos que buscan una recompensa ofrecida por la emperatriz María por el regreso de su nieta. El trío viaja a París, donde descubren que la emperatriz se ha vuelto escéptica ante los impostores.', N'', 499, 4, 241, 1, 2, 105, 1, CAST(3520000.00 AS Numeric(18, 2)), CAST(5000000.00 AS Numeric(18, 2)), 2, 1)
GO
