INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1680, N'El Secreto de sus Ojos
', N'El Secreto de sus Ojos
', N'Una persona no puede cambiar de pasión.', CAST(N'2009-08-13' AS Date), N'Benjamín Espósito acaba de jubilarse después de trabajar toda su vida en un Juzgado Penal. Para ocupar el tiempo libre decide escribir una novela, basada en una historia real de la que ha sido testigo y protagonista. La novela narra, en apariencia, la historia de un asesinato ocurrido en Buenos Aires en 1974, y de la investigación para hallar al culpable. Pero una vez abierta la puerta de ese pasado, al mismo Benjamín le será imposible cerrarla. Porque la turbulenta Argentina de entonces se cuela en la vida de los personajes y, sobre todo, porque aunque él suponga que la historia que teje habla solo del pasado, esa búsqueda ilumina de un modo descarnado su presente, y lo pone de frente con un dilema de amor que lo obsesiona desde hace demasiado tiempo.', NULL, 510, 267, 461, 16, 9, 127, 3, CAST(2000000.00 AS Numeric(18, 2)), CAST(56965279.00 AS Numeric(18, 2)), 1, 1)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1681, N'La Niña Santa', N'La Niña Santa', N'Ella es la tentación y la salvación.', CAST(N'2004-05-06' AS Date), N'Amalia es una adolescente atrapada en la agonía de su sexualidad emergente y su profunda pasión por su fe católica. Estos dos impulsos se mezclan cuando el Dr. Jano, visitante, se aprovecha de la multitud para acercarse inapropiadamente a la niña. Rechazada por él pero inspirada por un ardor interior, Amalia decide que la misión que Dios le ha encomendado es salvar al médico de su comportamiento y comienza a acechar al Dr. Jano, convirtiéndose en una voyeur de lo más inusual.', N'', 511, 268, 461, 16, 2, 103, 3, CAST(1400000.00 AS Numeric(18, 2)), CAST(1261792.00 AS Numeric(18, 2)), 0, 0)
GO
INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1682, N'Tango, No Me Dejes Nunca', N'Tango, No Me Dejes Nunca', N'Tango: nunca me dejes', CAST(N'1998-02-12' AS Date), N'Una peligrosa historia de amor inspira a un director a crear la película de danza más espectacular y seductora jamás realizada. 1998 Nominada al Oscar Mejor Película en Lengua Extranjera.', N'', 512, 269, 461, 16, 20, 115, 7, CAST(4685408.00 AS Numeric(18, 2)), CAST(1687311.00 AS Numeric(18, 2)), 1, 0)
GO
