INSERT [dbo].[Pelicula] ([PeliculaID], [TituloOriginal], [TituloLatam], [TagLine], [FechaEstreno], [Sinopsis], [SitioWeb], [DirectorID], [EstudioID], [PaisID], [LenguajeID], [GeneroID], [Duracion], [ClasificacionID], [Presupuesto], [Recaudacion], [OscarNomin], [OscarGanados]) VALUES (1684, N'Metegol', N'Metegol', N'Solo hay un equipo este verano.', CAST(N'2013-07-18' AS Date), N'En el pequeño pueblo donde vive Amadeo no hay nadie lo suficientemente bueno como para desafiar sus habilidades en el futbolín. Pero, si bien Amadeo puede ser un genio como jugador de futbolín en la vida real, es un perdedor. Está enamorado de Lara, su amiga de la infancia, pero es tan tímido que no se atreve a confesarle su amor. Así que simplemente pasa el rato en su pintoresco y eterno pueblo. Cuando Amadeo vence al matón del pueblo, Flash, en el futbolín. El escenario está preparado para una rivalidad épica. Consumido por la ira, Flash promete vengarse y 10 años después regresa como una superestrella internacional, un ícono del fútbol y Galático decidido a vengarse.', N'', 510, 267, 461, 16, 11, 106, 1, CAST(22000000.00 AS Numeric(18, 2)), CAST(34745097.00 AS Numeric(18, 2)), 0, 0)
GO
